/* =======================================================================
   C6 -- Promotion History: add Class/Section filters. Additive -- the
   original GetPromotionBatches proc is untouched, this is a new proc
   with two extra filter parameters (matching PromotionBatches' own
   SourceClassId/SourceSectionId columns, the same values BulkPromoteStudents
   already writes when a batch is created).
   ======================================================================= */

CREATE   PROCEDURE dbo.GetPromotionBatchesFiltered
    @UserId               INT,
    @SourceAcademicYearId INT = 0,
    @SourceClassId        INT = 0,
    @SourceSectionId      INT = 0
AS
BEGIN
    SET NOCOUNT ON;
    EXEC dbo.RequirePermission @UserId, N'Reports.View';

    SELECT PB.*
    FROM dbo.PromotionBatches PB
    WHERE (@SourceAcademicYearId = 0 OR PB.SourceAcademicYearId = @SourceAcademicYearId)
      AND (@SourceClassId = 0 OR PB.SourceClassId = @SourceClassId)
      AND (@SourceSectionId = 0 OR PB.SourceSectionId = @SourceSectionId)
    ORDER BY PB.PromotionBatchId DESC;
END;

-- SaveRolePermissions
CREATE   PROCEDURE dbo.SaveRolePermissions
@UserId INT, @RoleId INT, @PermissionIdsJson NVARCHAR (MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequireAnyPermission @UserId, N'System.Roles', N'System.Roles.Manage', N'System.Administration';
    IF @RoleId <= 0
        THROW 57300, 'A valid role is required.', 1;
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.Roles
                   WHERE  RoleId = @RoleId)
        THROW 57301, 'The selected role was not found.', 1;
    IF EXISTS (SELECT 1
               FROM   dbo.Roles
               WHERE  RoleId = @RoleId
                      AND RoleName = N'Administrator')
        THROW 57302, 'Administrator permissions are managed automatically.', 1;
    IF ISJSON(@PermissionIdsJson) <> 1
        THROW 57303, 'The supplied permission list is not valid JSON.', 1;
    DECLARE @SelectedPermissions TABLE (
        PermissionId INT NOT NULL PRIMARY KEY);
    INSERT INTO @SelectedPermissions (PermissionId)
    SELECT DISTINCT TRY_CONVERT (INT, [value])
    FROM   OPENJSON (@PermissionIdsJson)
    WHERE  TRY_CONVERT (INT, [value]) IS NOT NULL;
    IF EXISTS (SELECT 1
               FROM   @SelectedPermissions AS SP
                      LEFT OUTER JOIN
                      dbo.Perm
issions AS P
                      ON P.PermissionId = SP.PermissionId
               WHERE  P.PermissionId IS NULL)
        THROW 57304, 'One or more selected permissions are invalid.', 1;
    DECLARE @OldPermissionIds TABLE (
        PermissionId INT NOT NULL);
    INSERT INTO @OldPermissionIds (PermissionId)
    SELECT PermissionId
    FROM   dbo.RolePermissions
    WHERE  RoleId = @RoleId;
    BEGIN TRANSACTION;
    DELETE dbo.RolePermissions
    WHERE  RoleId = @RoleId;
    INSERT INTO dbo.RolePermissions (RoleId, PermissionId)
    SELECT @RoleId,
           PermissionId
    FROM   @SelectedPermissions;
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    DECLARE @AuditRecordId AS NVARCHAR (200) = CAST (@RoleId AS NVARCHAR (200));
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'ROLE_PERMISSIONS_SAVE', @AuditRecordId);
    DECLARE @OldPermissionIdsJson AS NVARCHAR (MAX);
    DECLARE @NewPermissionIdsJson AS NVARCHAR (MAX);
    SELECT @OldPermissionIdsJson = N'[' + ISNULL(STRING_AGG(CAST (PermissionId AS NVARCHAR (10)), N',') WITHIN GROUP (ORDER BY PermissionId), N'') + N']'
    FROM   @OldPermissionIds;
    SELECT @NewPermissionIdsJson = N'[' + ISNULL(STRING_AGG(CAST (PermissionId AS NVARCHAR (10)), N',') WITHIN GROUP (ORDER BY PermissionId), N'') + N']'
    FROM   @SelectedPermissions;
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'RolePermissions', @RecordId = @AuditRecordId, @Action = N'UPDATE', @OldValues = @OldPermissionIdsJson, @NewValues = @NewPermissionIdsJson;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @RoleId AS RoleId;
END

-- CreateCharacterCertificate
CREATE   PROCEDURE dbo.CreateCharacterCertificate
@UserId INT, @AdmissionId INT, @CertificateDate DATE, @RollNumber NVARCHAR (50)=NULL, @Remarks NVARCHAR (1000)=NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Certificates.Create';
    IF @AdmissionId <= 0
        THROW 58000, 'A valid student is required.', 1;
    IF @CertificateDate IS NULL
        THROW 58001, 'Certificate date is required.', 1;
    IF @CertificateDate > CONVERT (DATE, SYSDATETIME())
        THROW 58002, 'Certificate date cannot be in the future.', 1;
    IF @RollNumber IS NULL
       OR LTRIM(RTRIM(@RollNumber)) = N''
        THROW 58003, 'BISE Roll Number is required.', 1;
    IF @Remarks IS NULL
       OR LTRIM(RTRIM(@Remarks)) = N''
        THROW 58004, 'Remarks are required.', 1;
    IF EXISTS (SELECT 1
               FROM   dbo.CharacterCertificates
               WHERE  AdmissionId = @AdmissionId)
        THROW 58005, 'This student already has a character certificate.', 1;
    DECLARE @StudentName AS NVARCHAR (500), @FatherName AS NVARCHAR (500), @Gender AS NVARCHAR (20), @AcademicYearId AS INT, @LastExamYear AS INT, @CertificateRecordId AS INT, @IssueId AS INT;
    BEGIN TRANSACTION;
    SELECT @StudentName = S.StudentName,
           @FatherName = S.FatherName,

     @Gender = S.Gender
    FROM   dbo.Students AS S WITH (UPDLOCK, HOLDLOCK)
    WHERE  S.AdmissionId = @AdmissionId;
    IF @StudentName IS NULL
        THROW 58006, 'The student was not found.', 1;
    SELECT   TOP (1) @AcademicYearId = E.AcademicYearId
    FROM     dbo.Enrollments AS E
    WHERE    E.AdmissionId = @AdmissionId
    ORDER BY E.EnrollmentDate DESC, E.EnrollmentId DESC;
    IF @AcademicYearId IS NULL
        THROW 58007, 'The student has no enrollment record to determine the examination year from.', 1;
    SELECT @LastExamYear = YEAR(AY.EndDate)
    FROM   dbo.AcademicYears AS AY
    WHERE  AY.AcademicYearId = @AcademicYearId;
    IF @LastExamYear IS NULL
        THROW 58008, 'The academic year for this student could not be resolved.', 1;
    INSERT  dbo.CharacterCertificates (AdmissionId, StudentName, FatherName, Gender, LastExamYear, RollNumber, Remarks, CertificateDate, CreatedByUserId)
    VALUES                           (@AdmissionId, @StudentName, @FatherName, @Gender, @LastExamYear, LTRIM(RTRIM(@RollNumber)), LTRIM(RTRIM(@Remarks)), @CertificateDate, @UserId);
    SET @CertificateRecordId = CONVERT (INT, SCOPE_IDENTITY());
    INSERT  dbo.CharacterCertificateIssues (CertificateRecordId, IssuedAt, IssuedByUserId)
    VALUES                                (@CertificateRecordId, SYSDATETIME(), @UserId);
    SET @IssueId = CONVERT (INT, SCOPE_IDENTITY());
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    DECLARE @RecordId AS NVARCHAR (200) = CONVERT (NVARCHAR (200), @CertificateRecordId);
    DECLARE @NewValues AS NVARCHAR (MAX);
    SELECT @NewValues = (SELECT @CertificateRecordId AS CertificateRecordId,
                                @IssueId AS CharacterCertificateIssueId,
                                @AdmissionId AS AdmissionId,
                                @StudentName AS StudentName,
                                @FatherName AS FatherName,

       @LastExamYear AS LastExamYear,
                                @RollNumber AS RollNumber,
                                @Remarks AS Remarks,
                                @CertificateDate AS CertificateDate
                         FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'CHARACTER_CERTIFICATE', CONVERT (NVARCHAR (200), @AdmissionId));
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'CharacterCertificates', @RecordId = @RecordId, @Action = N'INSERT', @OldValues = NULL, @NewValues = @NewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @CertificateRecordId AS CertificateRecordId,
           @IssueId AS CharacterCertificateIssueId,
           @AdmissionId AS AdmissionId;
END

/* =====================================================================
   4. dbo.IssueCharacterCertificate ("Issue Again")
   ===================================================================== */

CREATE   PROCEDURE dbo.IssueCharacterCertificate
    @UserId INT,
    @CertificateRecordId INT,
    @Remarks NVARCHAR(1000) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    EXEC dbo.RequirePermission
        @UserId,
        N'Certificates.Create';

    IF @CertificateRecordId <= 0
        THROW 58100, 'A valid character certificate is required.', 1;

    BEGIN TRANSACTION;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.CharacterCertificates
        WHERE CertificateRecordId = @CertificateRecordId
    )
        THROW 58101, 'The character certificate was not found.', 1;

    DECLARE
        @LastIssueId INT,
        @LastCollectedAt DATETIME2;

    SELECT TOP (1)
        @LastIssueId = CCI.CharacterCertificateIssueId,
        @LastCollectedAt = CCI.CollectedAt
    FROM dbo.CharacterCertificateIssues AS CCI WITH (UPDLOCK, HOLDLOCK)
    WHERE CCI.CertificateRecordId = @CertificateRecordId
    ORDER BY
        CCI.IssuedAt DESC,
        CCI.CharacterCertificateIssueId DESC;

    IF @LastIssueId IS
 NOT NULL
       AND @LastCollectedAt IS NULL
        THROW 58102, 'The currently issued certificate has not been collected yet.', 1;

    INSERT dbo.CharacterCertificateIssues
    (
        CertificateRecordId,
        IssuedAt,
        IssuedByUserId,
        Remarks
    )
    VALUES
    (
        @CertificateRecordId,
        SYSDATETIME(),
        @UserId,
        @Remarks
    );

    DECLARE @IssueId INT =
        CONVERT(INT, SCOPE_IDENTITY());

    COMMIT;

    SELECT
        @IssueId AS CharacterCertificateIssueId,
        @CertificateRecordId AS CertificateRecordId;
END;

/* =====================================================================
   5. dbo.MarkCharacterCertificateCollected
   ===================================================================== */

CREATE   PROCEDURE dbo.MarkCharacterCertificateCollected
    @UserId INT,
    @CharacterCertificateIssueId INT,
    @CollectedBy NVARCHAR(200)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    EXEC dbo.RequirePermission
        @UserId,
        N'Certificates.Create';

    IF @CharacterCertificateIssueId <= 0
        THROW 58200, 'A valid certificate issue is required.', 1;

    IF NULLIF(LTRIM(RTRIM(@CollectedBy)), N'') IS NULL
        THROW 58201, 'The name of the person collecting the certificate is required.', 1;

    UPDATE dbo.CharacterCertificateIssues
    SET
        CollectedAt = SYSDATETIME(),
        CollectedBy = LTRIM(RTRIM(@CollectedBy))
    WHERE CharacterCertificateIssueId = @CharacterCertificateIssueId
      AND CollectedAt IS NULL;

    IF @@ROWCOUNT <> 1
        THROW 58202, 'The certificate issue was not found or has already been collected.', 1;

    SELECT
        CharacterCertificateIssueId,
        CertificateRecordId,
        IssuedAt,
        IssuedByUserId,
        CollectedAt,
        C
ollectedBy
    FROM dbo.CharacterCertificateIssues
    WHERE CharacterCertificateIssueId = @CharacterCertificateIssueId;
END;

CREATE PROCEDURE dbo.SetFeeTypeDefaultFrequency
    @UserId           INT,
    @FeeTypeId        INT,
    @DefaultFrequency NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    EXEC dbo.RequirePermission @UserId, N'Fees.Configuration.Manage';

    IF @DefaultFrequency NOT IN (N'Monthly', N'Yearly', N'As Needed')
        THROW 53001, 'Default frequency must be Monthly, Yearly, or As Needed.', 1;

    UPDATE dbo.FeeTypes
    SET DefaultFrequency = @DefaultFrequency
    WHERE FeeTypeId = @FeeTypeId;

    IF @@ROWCOUNT = 0
        THROW 53002, 'The fee type was not found.', 1;
END;

-- CreateSportsCertificate
CREATE   PROCEDURE dbo.CreateSportsCertificate
@UserId INT, @AdmissionId INT, @CertificateDate DATE, @SportName NVARCHAR (200), @Performance NVARCHAR (1000)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Certificates.Create';
    IF @AdmissionId <= 0
        THROW 58400, 'A valid student is required.', 1;
    IF @CertificateDate IS NULL
        THROW 58401, 'Certificate date is required.', 1;
    IF @CertificateDate > CONVERT (DATE, SYSDATETIME())
        THROW 58402, 'Certificate date cannot be in the future.', 1;
    IF @SportName IS NULL
       OR LTRIM(RTRIM(@SportName)) = N''
        THROW 58403, 'Sport Name is required.', 1;
    IF @Performance IS NULL
       OR LTRIM(RTRIM(@Performance)) = N''
        THROW 58404, 'Performance is required.', 1;
    DECLARE @StudentName AS NVARCHAR (500), @FatherName AS NVARCHAR (500), @SportsCertificateId AS INT;
    BEGIN TRANSACTI
ON;
    SELECT @StudentName = S.StudentName,
           @FatherName = S.FatherName
    FROM   dbo.Students AS S WITH (UPDLOCK, HOLDLOCK)
    WHERE  S.AdmissionId = @AdmissionId;
    IF @StudentName IS NULL
        THROW 58405, 'The student was not found.', 1;
    INSERT  dbo.SportsCertificates (AdmissionId, StudentName, FatherName, SportName, Performance, CertificateDate, CreatedByUserId)
    VALUES                        (@AdmissionId, @StudentName, @FatherName, LTRIM(RTRIM(@SportName)), LTRIM(RTRIM(@Performance)), @CertificateDate, @UserId);
    SET @SportsCertificateId = CONVERT (INT, SCOPE_IDENTITY());
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    DECLARE @RecordId AS NVARCHAR (200) = CONVERT (NVARCHAR (200), @SportsCertificateId);
    DECLARE @NewValues AS NVARCHAR (MAX);
    SELECT @NewValues = (SELECT @SportsCertificateId AS SportsCertificateId,
                                @AdmissionId AS AdmissionId,
                                @StudentName AS StudentName,
                                @FatherName AS FatherName,
                                @SportName AS SportName,
                                @Performance AS Performance,
                                @CertificateDate AS CertificateDate
                         FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'SPORTS_CERTIFICATE', CONVERT (NVARCHAR (200), @AdmissionId));
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'SportsCertificates', @RecordId = @RecordId, @Action = N'INSERT', @OldValues = NULL, @NewValues = @NewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @SportsCertificateId AS SportsCertificateId,\
n           @AdmissionId AS AdmissionId;
END

-- UpdateSportsCertificate
CREATE   PROCEDURE dbo.UpdateSportsCertificate
@UserId INT, @SportsCertificateId INT, @CertificateDate DATE, @SportName NVARCHAR (200), @Performance NVARCHAR (1000)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission 
@UserId, N'Certificates.Create';
    IF @SportsCertificateId <= 0
        THROW 58410, 'A valid sports certificate is required.', 1;
    IF @CertificateDate IS NULL
        THROW 58411, 'Certificate date is required.', 1;
    IF @CertificateDate > CONVERT (DATE, SYSDATETIME())
        THROW 58412, 'Certificate date cannot be in the future.', 1;
    IF @SportName IS NULL
       OR LTRIM(RTRIM(@SportName)) = N''
        THROW 58413, 'Sport Name is required.', 1;
    IF @Performance IS NULL
       OR LTRIM(RTRIM(@Performance)) = N''
        THROW 58414, 'Performance is required.', 1;
    BEGIN TRANSACTION;
    DECLARE @AdmissionId AS INT;
    DECLARE @OldValues AS NVARCHAR (MAX);
    SELECT @AdmissionId = SC.AdmissionId,
           @OldValues = (SELECT SC.SportsCertificateId,
                                SC.AdmissionId,
                                SC.SportName,
                                SC.Performance,
                                SC.CertificateDate
                         FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES)
    FROM   dbo.SportsCertificates AS SC WITH (UPDLOCK, HOLDLOCK)
    WHERE  SC.SportsCertificateId = @SportsCertificateId;
    IF @AdmissionId IS NULL
        THROW 58415, 'The sports certificate was not found.', 1;
    UPDATE dbo.SportsCertificates
    SET    SportName       = LTRIM(RTRIM(@SportName)),
           Performance     = LTRIM(RTRIM(@Performance)),
           CertificateDate = @CertificateDate,
           UpdatedByUserId = @UserId,
           UpdatedAt       = SYSDATETIME()
    WHERE  SportsCertificateId = @SportsCertificateId;
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    DECLARE @RecordId AS NVARCHAR (200) = CONVERT (NVARCHAR (200), @SportsCertificateId);
    DECLARE @NewValues AS NVARCHAR (MAX);
    SELECT @NewValues = (SELECT @SportsCertificateId AS SportsCertificateId,
                                @AdmissionId 
AS AdmissionId,
                                @SportName AS SportName,
                                @Performance AS Performance,
                                @CertificateDate AS CertificateDate
                         FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'SPORTS_CERTIFICATE', CONVERT (NVARCHAR (200), @AdmissionId));
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'SportsCertificates', @RecordId = @RecordId, @Action = N'UPDATE', @OldValues = @OldValues, @NewValues = @NewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @SportsCertificateId AS SportsCertificateId,
           @AdmissionId AS AdmissionId;
END

/* =====================================================================
   8. dbo.GetCharacterCertificateFieldSuggestions

      Only Remarks recurs in practice (Roll Number is unique per
      student/certificate, so it gets no suggestion list).
   ===================================================================== */

CREATE   PROCEDURE dbo.GetCharacterCertificateFieldSuggestions
    @UserId INT,
    @Field NVARCHAR
(50)
AS
BEGIN
    SET NOCOUNT ON;

    EXEC dbo.RequirePermission
        @UserId,
        N'Certificates.Create';

    IF @Field = N'Remarks'
        SELECT DISTINCT TOP (500) Remarks AS Value
        FROM dbo.CharacterCertificates
        WHERE Remarks IS NOT NULL
          AND LTRIM(RTRIM(Remarks)) <> N''
        ORDER BY Remarks;

    ELSE
        THROW 51600, 'Unknown suggestion field.', 1;
END;

/* =====================================================================
   6. dbo.GetSportsCertificateFieldSuggestions

      Both Sport Name and Performance recur across certificates, so
      unlike Character Certificate (Remarks only) both fields get a
      type-ahead suggestion list.
   ===================================================================== */

CREATE   PROCEDURE dbo.GetSportsCertificateFieldSuggestions
    @UserId INT,
    @Field NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    EXEC dbo.RequirePermission
        @UserId,
        N'Certificates.Create';

    IF @Field = N'SportName'
        SELECT DISTINCT TOP (500) SportName AS Value
        FROM dbo.SportsCertificates
        WHERE SportName IS NOT NULL
          AND LTRIM(RTRIM(SportName)) <> N''
        ORDER BY SportName;

    ELSE IF @Field = N'Performance'
        SELECT DISTINCT TOP (500) Performance AS Value
        FROM dbo.SportsCertificates
        WHERE Performance IS NOT NULL
          AND LTRIM(RTRIM(Performance)) <> N''
        ORDER BY Performance;

    ELSE
        THROW 51601, 'Unknown suggestion field.', 1;
END;

-- PostEnrollmentOpeningCharges
CREATE PROCEDURE dbo.PostEnrollmentOpeningCharges
@EnrollmentId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @BillingStartDate AS DATE, @ChargeDate AS DATE, @Status AS NVARCHAR (30), @BillingReady AS BIT;
    SELECT @BillingStartDate = ISNULL(E.BillingStartDate, E.EnrollmentDate),
           @ChargeDate = COALESCE (CONVERT (DATE, E.ReturnConfirmedAt), E.EnrollmentDate),
           @Status = E.Status,
           @BillingReady = E.BillingReady
    FROM   dbo.Enrollments AS E
    WHERE  E.EnrollmentId = @EnrollmentId;
    IF @BillingStartDate IS NULL
        THROW 59401, 'The enrollment does not exist.', 1;
    IF @Status <> N'Active'
       OR @BillingReady <> 1
        THROW 59402, 'Confirm admission before posting opening charges.', 1;
    DECLARE @OpeningMonth AS DATE = DATEFROMPARTS(YEAR(@BillingStartDate), MONTH(@BillingStartDate), 1);
    IF @@TRANCOUNT > 0
        BEGIN
            DECLARE @LockResult AS INT;
            DECLARE @LockResource AS NVARCHAR (255) = N'FMSC.GenerateEnrollmentCharges.' + CONVERT (NVARCHAR (20), @EnrollmentId);
            EXECUTE @LockResult = sys.sp_getapplock @Resource = @LockResource, @LockMode = N'Exclusive', @LockOwner = N'Transaction', @LockTimeout = 0;
            IF @LockResult < 0
                THROW 59403, 'Charges for this enrollment are already being posted.', 1;
        END
    INSERT dbo.BillingCharges (StudentFeeAssignmentId, EnrollmentId, AdmissionId, FeeTypeId, BillingMonth, ChargeDate, DueDate, GrossAmount, DiscountAmount, ChargeKind)
    SELECT SFA.StudentFeeAssignmentId,
           SFA.EnrollmentId,
           SFA.AdmissionId,
           SFA.FeeTypeId,
           @OpeningMonth,
           @ChargeDate,
           @ChargeDate,
           SFA.Amount,
           SFA.DiscountAmount,
           N'Annual'
    FROM   dbo.StudentFeeA
ssignments AS SFA
    WHERE  SFA.EnrollmentId = @EnrollmentId
           AND SFA.CancelledAt IS NULL
           AND SFA.Frequency = N'Yearly'
           AND (SFA.EffectiveFrom IS NULL
                OR @OpeningMonth >= SFA.EffectiveFrom)
           AND (SFA.EffectiveTo IS NULL
                OR @OpeningMonth <= SFA.EffectiveTo)
           AND NOT EXISTS (SELECT 1
                           FROM   dbo.BillingCharges AS BC
                           WHERE  BC.EnrollmentId = @EnrollmentId
                                  AND BC.FeeTypeId = SFA.FeeTypeId
                                  AND BC.ChargeKind = N'Annual'
                                  );
    INSERT dbo.BillingCharges (StudentFeeAssignmentId, EnrollmentId, AdmissionId, FeeTypeId, BillingMonth, ChargeDate, DueDate, GrossAmount, DiscountAmount, ChargeKind)
    SELECT SFA.StudentFeeAssignmentId,
           SFA.EnrollmentId,
           SFA.AdmissionId,
           SFA.FeeTypeId,
           @OpeningMonth,
           @OpeningMonth,
           @OpeningMonth,
           SFA.Amount,
           SFA.DiscountAmount,
           N'Monthly'
    FROM   dbo.StudentFeeAssignments AS SFA
    WHERE  SFA.EnrollmentId = @EnrollmentId
           AND SFA.CancelledAt IS NULL
           AND SFA.Frequency = N'Monthly'
           AND (SFA.EffectiveFrom IS NULL
                OR @OpeningMonth >= SFA.EffectiveFrom)
           AND (SFA.EffectiveTo IS NULL
                OR @OpeningMonth <= SFA.EffectiveTo)
           AND NOT EXISTS (SELECT 1
                           FROM   dbo.BillingCharges AS BC
                           WHERE  BC.EnrollmentId = @EnrollmentId
                                  AND BC.FeeTypeId = SFA.FeeTypeId
                                  AND BC.BillingMonth = @OpeningMonth
                                  AND BC.ChargeKind = N'Monthly'
                                  );
END

CREATE PROCEDURE dbo.DeleteDatabaseBackupRecord
(
      @UserId   INT
    , @BackupId BIGINT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* Mutating the history is the same kind of action as relocating a record, which
       dbo.UpdateDatabaseBackupPath gates on Backup.Create. */
    EXEC dbo.RequirePermission @UserId, N'Backup.Create';

    IF @BackupId IS NULL OR @BackupId <= 0
        THROW 59920, 'A backup record id is required.', 1;

    DELETE FROM dbo.DatabaseBackups
    WHERE BackupId = @BackupId;

    /* No row count check on purpose: see the idempotence note above. */
END;

CREATE   PROCEDURE dbo.SaveFeeType
@UserId INT, @FeeTypeCode NVARCHAR (30), @FeeTypeName NVARCHAR (100), @FeeTypeId INT=0, @Description NVARCHAR (250)=NULL, @DisplayOrder INT=0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Fees.Configuration.Manage';
    BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @OrderLock int;
    EXEC @OrderLock = sys.sp_getapplock @Resource=N'SetupOrder:FeeTypes', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=10000;
    IF @OrderLock < 0 THROW 57401, 'Unable to lock setup ordering. Please try again.', 1;
    IF NULLIF (LTRIM(RTRIM(@FeeTypeCode)), N'') IS NULL
        THROW 56302, 'Fee type code is required.', 1;
    IF NULLIF (LTRIM(RTRIM(@FeeTypeName)), N'') IS NULL
        THROW 56303, 'Fee type name is required.', 1;
    IF @FeeTypeId = 0
        BEGIN
            SELECT @DisplayOrder = ISNULL(MAX(DisplayOrder), 0) + 1
                    FROM   dbo.FeeTypes WITH (UPDLOCK,HOLDLOCK);
            INSERT  dbo.FeeTypes (FeeTypeCode, FeeTypeName, Description, DisplayOrder)
            VALUES              (@FeeTypeCode, @FeeTypeName, @Description, @DisplayOrder);

    COMMIT TRANSACTION;
    SELECT CONVERT (INT, SCOPE_IDENTITY()) AS FeeTypeId;
        END
    ELSE
        BEGIN
            UPDATE dbo.FeeTypes
            SET    FeeTypeName  = @FeeTypeName,
                   Description  = @Description
            WHERE  FeeTypeId = @FeeTypeId;
            IF @@ROWCOUNT = 0
                THROW 56301, 'The selected fee type was not found.', 1;

    COMMIT TRANSACTION;
    SELECT @FeeTypeId AS FeeTypeId;
        END
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END

-- SaveFeeConfiguration
CREATE   PROCEDURE dbo.SaveFeeConfiguration
@UserId INT, @CampusId INT, @ClassId INT, @FeeTypeId INT, @Amount DECIMAL (12, 2), @Frequency NVARCHAR (30), @FeeConfigurationId INT, @Remarks NVARCHAR (500)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Fees.Configuration.Manage';
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.Campuses
                   WHERE  CampusId = @CampusId)
        THROW 56310, 'Please select an campus.', 1;
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.Classes
                   WHERE  ClassId = @ClassId)
        THROW 56312, 'Please select an class.', 1;
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.FeeTypes
                   WHERE  FeeTypeId = @FeeTypeId)
        THROW 56313, 'Please select an fee type.', 1;
    IF @Amount < 0
        THROW 56314, 'Fee amount cannot be negative.', 1;
    DECLARE @ResultId AS INT;
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    DECLARE @AuditAction AS NVARCHAR (20) = NULL;
    DECLARE @OldValues AS NVARCHAR (MAX) = NULL;
    DECLARE @NewValues AS NVARCHAR (MAX);
    DECLARE @NewRemarks AS NVARCHAR (500) = NULLIF (LTRIM(RTRIM(@Remarks)), N'');
    BEGIN TRANSACTION;
    IF @FeeConfigurationId = 0
        BEGIN
            INSERT  dbo.FeeConfigurations (CampusId, ClassId, FeeTypeId, Amount, Frequency, Remarks)
            VALUES                       (@CampusId, @ClassId, @FeeTypeId, @Amount, @Frequency, @NewRemarks);
            SET @ResultId = CONVERT (INT, SCOPE_IDENTITY());
            SET @AuditAction = N'INSERT';
        END
    ELSE
        BEGIN
            DECLARE @OldCampusId AS INT, @OldClassId AS INT, @OldFeeTypeId AS INT, @OldAmount AS DECIMAL (12, 2), @OldFrequency AS NVARCHAR (30), @OldRemarks AS NVARCHAR (500);

            SELECT @OldCampusId = CampusId,
                   @OldClassId = ClassId,
                   @OldFeeTypeId = FeeTypeId,
                   @OldAmount = Amount,
                   @OldFrequency = Frequency,
                   @OldRemarks = Remarks
            FROM   dbo.FeeConfigurations WITH (UPDLOCK, HOLDLOCK)
            WHERE  FeeConfigurationId = @FeeConfigurationId;
            IF @@ROWCOUNT = 0
                THROW 56315, 'The selected fee configuration was not found.', 1;
            SET @ResultId = @FeeConfigurationId;
            IF @OldCampusId = @CampusId
               AND @OldClassId = @ClassId
               AND @OldFeeTypeId = @FeeTypeId
               AND @OldAmount = @Amount
               AND ISNULL(@OldFrequency, N'') = ISNULL(@Frequency, N'')
               AND ISNULL(@OldRemarks, N'') = ISNULL(@NewRemarks, N'')
                BEGIN
                    UPDATE dbo.FeeConfigurations
                    SET    UpdatedAt = SYSDATETIME()
                    WHERE  FeeConfigurationId = @FeeConfigurationId;
                END
            ELSE
                BEGIN
                    SET @OldValues = (SELECT @FeeConfigurationId AS FeeConfigurationId,
                                             @OldCampusId AS CampusId,
                                             @OldClassId AS ClassId,
                                             @OldFeeTypeId AS FeeTypeId,
                                             @OldAmount AS Amount,
                                             @OldFrequency AS Frequency,
                                             @OldRemarks AS Remarks
                                      FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
                    UPDATE dbo.FeeConfigurations
                    SET    CampusId  = @CampusId,
                           ClassId   = @ClassId,
                           FeeTypeId = @FeeTypeId,

                    Amount    = @Amount,
                           Frequency = @Frequency,
                           Remarks   = @NewRemarks,
                           UpdatedAt = SYSDATETIME()
                    WHERE  FeeConfigurationId = @FeeConfigurationId;
                    SET @AuditAction = N'UPDATE';
                END
        END
    IF @AuditAction IS NOT NULL
        BEGIN
            SET @NewValues = (SELECT @ResultId AS FeeConfigurationId,
                                     @CampusId AS CampusId,
                                     @ClassId AS ClassId,
                                     @FeeTypeId AS FeeTypeId,
                                     @Amount AS Amount,
                                     @Frequency AS Frequency,
                                     @NewRemarks AS Remarks
                              FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
            INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
            VALUES                     (@OperationId, @UserId, N'FEE_CONFIGURATION', CONVERT (NVARCHAR (200), @ResultId));
            DECLARE @RecordId AS NVARCHAR (200) = CONVERT (NVARCHAR (200), @ResultId);
            EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'FeeConfigurations', @RecordId = @RecordId, @Action = @AuditAction, @OldValues = @OldValues, @NewValues = @NewValues;
        END
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @ResultId AS FeeConfigurationId;
END

-- DiscontinueStudentFeeAssignment
CREATE   PROCEDURE dbo.DiscontinueStudentFeeAssignment
@UserId INT, @StudentFeeAssignmentId INT, @EffectiveTo DATE, @Reason NVARCHAR (500)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Fees.Adjust';
    IF @Reason IS NULL
       OR LTRIM(RTRIM(@Reason)) = N''
        THROW 53130, 'A reason is required to discontinue a fee assignment.', 1;
    IF @EffectiveTo IS NULL
        THROW 53136, 'An effective-to date is required.', 1;
    DECLARE @EnrollmentId AS INT, @AdmissionId AS INT, @FeeTypeId AS INT, @Amount AS DECIMAL (12, 2), @DiscountAmount AS DECIMAL (12, 2), @Frequency AS NVARCHAR (20), @ExistingEffectiveFrom AS DATE, @ExistingEffectiveTo AS DATE, @CancelledAt AS DATETIME2;
    SELECT @EnrollmentId = EnrollmentId,
           @AdmissionId = AdmissionId,
           @FeeType
Id = FeeTypeId,
           @Amount = Amount,
           @DiscountAmount = DiscountAmount,
           @Frequency = Frequency,
           @ExistingEffectiveFrom = EffectiveFrom,
           @ExistingEffectiveTo = EffectiveTo,
           @CancelledAt = CancelledAt
    FROM   dbo.StudentFeeAssignments
    WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId;
    IF @EnrollmentId IS NULL
        THROW 53131, 'The selected student fee assignment does not exist.', 1;
    IF @CancelledAt IS NOT NULL
        THROW 53132, 'This fee assignment has been cancelled.', 1;
    IF @ExistingEffectiveTo IS NOT NULL
        THROW 53133, 'This fee assignment has already been discontinued.', 1;
    DECLARE @NormalizedEffectiveTo AS DATE = DATEFROMPARTS(YEAR(@EffectiveTo), MONTH(@EffectiveTo), 1);
    IF @ExistingEffectiveFrom IS NOT NULL
       AND @NormalizedEffectiveTo < @ExistingEffectiveFrom
        THROW 53137, 'Effective-to month cannot be earlier than this version''s own starting month.', 1;
    DECLARE @LastBilledMonth AS DATE = (SELECT MAX(BillingMonth)
                                        FROM   dbo.BillingCharges
                                        WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId);
    IF @LastBilledMonth IS NOT NULL
       AND @NormalizedEffectiveTo < @LastBilledMonth
        THROW 53134, 'Effective-to month cannot be earlier than the last month already billed for this fee.', 1;
    BEGIN TRANSACTION;
    UPDATE dbo.StudentFeeAssignments
    SET    EffectiveTo = @NormalizedEffectiveTo,
           UpdatedAt   = SYSDATETIME()
    WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId
           AND EffectiveTo IS NULL;
    IF @@ROWCOUNT = 0
        BEGIN
            ROLLBACK;
            THROW 53135, 'The fee assignment could not be discontinued (it may have just been changed by another operation).', 1;
        END
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();\
r
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'FEE_ASSIGNMENT_DISCONTINUE', CONVERT (NVARCHAR (200), @StudentFeeAssignmentId));
    DECLARE @OldValues AS NVARCHAR (MAX) = (SELECT @StudentFeeAssignmentId AS StudentFeeAssignmentId,
                                                   @ExistingEffectiveFrom AS EffectiveFrom,
                                                   CAST (NULL AS DATE) AS EffectiveTo
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    DECLARE @NewValues AS NVARCHAR (MAX) = (SELECT @StudentFeeAssignmentId AS StudentFeeAssignmentId,
                                                   @ExistingEffectiveFrom AS EffectiveFrom,
                                                   @NormalizedEffectiveTo AS EffectiveTo,
                                                   @Reason AS Reason,
                                                   @EnrollmentId AS EnrollmentId,
                                                   @AdmissionId AS AdmissionId,
                                                   @FeeTypeId AS FeeTypeId
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'StudentFeeAssignments', @RecordId = @StudentFeeAssignmentId, @Action = N'UPDATE', @OldValues = @OldValues, @NewValues = @NewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT StudentFeeAssignmentId,
           EnrollmentId,
           AdmissionId,
           FeeTypeId,
           Amount,
           DiscountAmount,
           Frequency,
           EffectiveFrom,
           EffectiveTo
    FROM   dbo.StudentFeeAssignments\
n    WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId;
END

CREATE   PROCEDURE dbo.SaveStaff
    @UserId INT,
    @StaffNumber NVARCHAR(30) = NULL,
    @StaffName NVARCHAR(150) = NULL,
    @StaffId INT = 0,
    @FatherName NVARCHAR(150) = NULL,
    @DateOfBirth DATE = NULL,
    @Gender NVARCHAR(20) = NULL,
    @CNIC NVARCHAR(25) = NULL,
    @ContactNumber NVARCHAR(30) = NULL,
    @AlternateContactNumber NVARCHAR(30) = NULL,
    @Address NVARCHAR(500) = NULL,
    @Qualification NVARCHAR(250) = NULL,
    @Specialization NVARCHAR(250) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXEC dbo.RequirePermission @UserId, N'Staff.Manage';
    SET @StaffName = NULLIF(LTRIM(RTRIM(@StaffName)), N'');
    SET @FatherName = NULLIF(LTRIM(RTRIM(@FatherName)), N'');
    IF @StaffName IS NULL THROW 56403, 'Staff name is required.', 1;
    IF @StaffName LIKE N'%[0-9]%' OR @FatherName LIKE N'%[0-9]%'
        THROW 56405, 'Staff and father names cannot contain numbers.', 1;
    IF @DateOfBirth > CONVERT(DATE, GETDATE())
        THROW 56406, 'Date of birth cannot be in the future.', 1;
    SET @Gender = NULLIF(LTRIM(RTRIM(@Gender)), N'');
    IF @Gender IS NOT NULL AND @Gender NOT IN (N'Male', N'Female', N'Other')
        THROW 56407, 'Choose a valid gender.', 1;
    SET @CNIC = NULLIF(LTRIM(RTRIM(@CNIC)), N'');
    IF @CNIC IS NOT NULL
    BEGIN
        IF NOT (LEN(@CNIC) = 13 AND @CNIC COLLATE Latin1_General_100_BIN2 NOT LIKE N'%[^0-9]%')
           AND NOT (LEN(@CNIC) = 15 AND @CNIC COLLATE Latin1_General_100_BIN2
                    LIKE N'[0-9][0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9][0-9][0-9][0-9]-[0-9]')
            THROW 56408, 'Enter a 13-digit CNIC, with or without hyphens.', 1;
        SET @CNIC = REPLACE(@CNIC, N'-', N'');
        SET @CNIC = STUFF(STUFF(@CNIC, 6, 0, N'-'), 14, 0, N'-');
    END;
    SET @ContactNum
ber = NULLIF(LTRIM(RTRIM(@ContactNumber)), N'');
    SET @AlternateContactNumber = NULLIF(LTRIM(RTRIM(@AlternateContactNumber)), N'');
    IF EXISTS
    (
        SELECT 1 FROM (VALUES (@ContactNumber), (@AlternateContactNumber)) phones(number)
        CROSS APPLY (SELECT REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(number,
            N' ', N''), N'+', N''), N'-', N''), N'(', N''), N')', N'') digits) cleaned
        WHERE number IS NOT NULL AND
          (number COLLATE Latin1_General_100_BIN2 LIKE N'%[^0-9 +()-]%'
           OR digits COLLATE Latin1_General_100_BIN2 LIKE N'%[^0-9]%'
           OR CHARINDEX(N'+', SUBSTRING(number, 2, 30)) > 0
           OR LEN(digits) NOT BETWEEN 7 AND 15)
    ) THROW 56416, 'Contact numbers must contain 7 to 15 digits and valid phone punctuation.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;
        IF @StaffId = 0
        BEGIN
            -- Serializable range locks keep concurrent allocations distinct.
            DECLARE @HighestNumber BIGINT;
            SELECT @HighestNumber = COALESCE(MAX(TRY_CONVERT(BIGINT, StaffNumber)), 0)
            FROM dbo.Staff WITH (UPDLOCK, HOLDLOCK)
            WHERE StaffNumber COLLATE Latin1_General_100_BIN2 NOT LIKE N'%[^0-9]%';
            IF @HighestNumber = 9223372036854775807
                THROW 56417, 'Staff numbering has reached its limit.', 1;
            SET @StaffNumber = CONVERT(NVARCHAR(30), @HighestNumber + 1);
            INSERT dbo.Staff
                (StaffNumber, StaffName, FatherName, DateOfBirth, Gender, CNIC,
                 ContactNumber, AlternateContactNumber, Address, Qualification, Specialization)
            VALUES
                (@StaffNumber, @StaffName, @FatherName, @DateOfBirth, @Gender, @CNIC,
                 @ContactNumber, @AlternateContactNumber, @Address, @Qualification, @Specialization);
            SET @StaffId = CONVERT(INT, SCOPE_IDENTITY());
        END
        ELSE
        BEGIN
            -- Identity numbers belong to the saved record; profile ed
its retain them.
            UPDATE dbo.Staff
            SET StaffName = @StaffName, FatherName = @FatherName, DateOfBirth = @DateOfBirth,
                Gender = @Gender, CNIC = @CNIC, ContactNumber = @ContactNumber,
                AlternateContactNumber = @AlternateContactNumber, Address = @Address,
                Qualification = @Qualification, Specialization = @Specialization,
                UpdatedAt = SYSDATETIME()
            WHERE StaffId = @StaffId;
            IF @@ROWCOUNT = 0 THROW 56401, 'The selected staff record was not found.', 1;
            SELECT @StaffNumber = StaffNumber FROM dbo.Staff WHERE StaffId = @StaffId;
        END;
        COMMIT TRANSACTION;
        SELECT @StaffId StaffId, @StaffNumber StaffNumber;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;

/* ============================================================================
   dbo.ChangeStudentFeeAssignmentAmount
   Now just an authorization wrapper: checks Fees.Adjust, then delegates
   to the internal procedure above. Callers (C# included) see no change
   in behavior, parameters, result shape, or error codes.
============================================================================ */
CREATE   PROCEDURE dbo.ChangeStudentFeeAssignmentAmount
    @UserId INT,
    @StudentFeeAssignmentId INT,
    @NewAmount DECIMAL(12,2),
    @EffectiveFrom DATE,
    @Reason NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;

    EXEC dbo.RequirePermission @UserId, N'Fees.Adjust';

    EXEC dbo.ChangeStudentFeeAssignmentAmount_Internal
        @UserId = @UserId,
        @StudentFeeAssignmentId = @StudentFeeAssignmentId,
        @NewAmount = @NewAmount,
        @EffectiveFrom = @EffectiveFrom,
        @Reason = @Reason;
END;

CREATE   PROCEDURE dbo.SaveStaffEmployment
    @UserId INT,
    @StaffId INT,
    @Designation NVARCHAR(100),
    @HireDate DATE,
    @StaffEmploymentId INT = 0,
    @Department NVARCHAR(100) = NULL,
    @EmploymentType NVARCHAR(50) = NULL,
    @LeavingDate DATE = NULL,
    @Remarks NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXEC dbo.RequirePermission
        @UserId,
        N'Staff.Manage';
    IF @StaffId <= 0
        THROW 56409, 'A valid staff member is required.', 1;
    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.Staff
        WHERE StaffId = @StaffId
    )
        THROW 56410, 'The selected staff member was not found.', 1;
    IF NULLIF(LTRIM(RTRIM(@Designation)), N'') IS NULL
        THROW 56413, 'Designation is required.', 1;
    IF @HireDate IS NULL THROW 56415, 'Hire date is required.', 1;
    IF @LeavingDate IS NOT NULL
       AND @LeavingDate < @HireDate
        THROW 56411, 'Leaving date cannot be earlier than hire date.', 1;
    /* FIX 077 - everything from here to the COMMIT is one attempt, so a failure
       anywhere inside it cannot leave the caller's transaction open. */
    BEGIN TRY
        BEGIN TRANSACTION;
        DECLARE @PreviousStaffId int;
        SELECT @PreviousStaffId=StaffId FROM dbo.StaffEmployment WITH(UPDLOCK,HOLDLOCK)
        WHERE StaffEmploymentId=@StaffEmploymentId;
        IF @StaffEmploymentId = 0
        BEGIN
            INSERT dbo.StaffEmployment
            (
                StaffId,
                Designation,
                Department,
                EmploymentType,
                HireDate,
                LeavingDate,
                Status,
                Remarks
            )
            VALUES
            (
                @StaffId,
                @Designati
on,
                @Department,
                @EmploymentType,
                @HireDate,
                @LeavingDate,
                CASE
                    WHEN @LeavingDate IS NULL
                        THEN N'Active'
                    ELSE N'Ended'
                END,
                @Remarks
            );
            SET @StaffEmploymentId =
                CONVERT(INT, SCOPE_IDENTITY());
        END
        ELSE
        BEGIN
            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.StaffEmployment
                WHERE StaffEmploymentId = @StaffEmploymentId
            )
                THROW 56412,
                    'The selected employment record was not found.',
                    1;
            UPDATE dbo.StaffEmployment
            SET
                StaffId = @StaffId,
                Designation = @Designation,
                Department = @Department,
                EmploymentType = @EmploymentType,
                HireDate = @HireDate,
                LeavingDate = @LeavingDate,
                Status =
                    CASE
                        WHEN @LeavingDate IS NULL
                            THEN N'Active'
                        ELSE N'Ended'
                    END,
                Remarks = @Remarks,
                UpdatedAt = SYSDATETIME()
            WHERE StaffEmploymentId = @StaffEmploymentId;
            IF @@ROWCOUNT = 0
                THROW 56412,
                    'The selected employment record was not found.',
                    1;
        END;
        /*
            Synchronize Staff.Status with the actual employment state.
            If this staff member has an active employment record,
            the staff member is Active.
            If no active employment record remains,
            the staff member is Left.
        */
        IF E
XISTS
        (
            SELECT 1
            FROM dbo.StaffEmployment
            WHERE StaffId = @StaffId
              AND Status = N'Active'
        )
        BEGIN
            UPDATE dbo.Staff
            SET
                Status = N'Active',
                UpdatedAt = SYSDATETIME()
            WHERE StaffId = @StaffId;
        END
        ELSE
        BEGIN
            UPDATE dbo.Staff
            SET
                Status = N'Left',
                UpdatedAt = SYSDATETIME()
            WHERE StaffId = @StaffId;
        END;
        IF @PreviousStaffId IS NOT NULL AND @PreviousStaffId<>@StaffId
            UPDATE dbo.Staff SET Status=CASE WHEN EXISTS
                (SELECT 1 FROM dbo.StaffEmployment WHERE StaffId=@PreviousStaffId AND Status=N'Active')
                THEN N'Active' ELSE N'Left' END, UpdatedAt=SYSDATETIME()
            WHERE StaffId=@PreviousStaffId;
        COMMIT;
    END TRY
    BEGIN CATCH
        /* Leave the session clean whatever failed. Without this the caller is
           left with XACT_STATE() = -1 and @@TRANCOUNT = 1 after a constraint
           violation, and every later statement on that connection fails. */
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;
        /* A second ACTIVE employment is the one failure here the operator can
           actually act on, so it is named. 2601 is a unique INDEX violation,
           2627 a unique CONSTRAINT one - both mean the same thing to the caller,
           and @StaffEmploymentId is still 0 only on the insert path. */
        IF ERROR_NUMBER() IN (2601, 2627)
            THROW 56414,
                'This staff member already has an active employment record. Set a leaving date on that record first, then add the new one.',
                1;
        /* Anything else keeps its original number and message. */
        THROW;
    END CATCH;
    SELECT

   @StaffEmploymentId AS StaffEmploymentId;
END;

CREATE   PROCEDURE dbo.EndStaffEmployment
 @UserId int,@StaffId int,@LeavingDate date,@Remarks nvarchar(500)=NULL
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 EXEC dbo.RequirePermission @UserId,N'Staff.Manage';
 IF @LeavingDate IS NULL THROW 56421,'Leaving date is required.',1;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @EmploymentId int,@HireDate date;
  SELECT TOP(1) @EmploymentId=StaffEmploymentId,@HireDate=HireDate
  FROM dbo.StaffEmployment WITH(UPDLOCK,HOLDLOCK)
  WHERE StaffId=@StaffId AND Status=N'Active' ORDER BY StaffEmploymentId DESC;
  IF @EmploymentId IS NULL THROW 56420,'No active employment record was found for this staff member.',1;
  IF @LeavingDate<@HireDate THROW 56411,'Leaving date cannot be earlier than hire date.',1;
  UPDATE dbo.StaffEmployment SET LeavingDate=@LeavingDate,Status=N'Ended',
   Remarks=COALESCE(NULLIF(@Remarks,N''),Remarks),UpdatedAt=SYSDATETIME()
   WHERE StaffEmploymentId=@EmploymentId;
  UPDATE dbo.Staff SET Status=N'Left',UpdatedAt=SYSDATETIME() WHERE StaffId=@StaffId;
  COMMIT TRANSACTION;
  SELECT @StaffId StaffId,@EmploymentId StaffEmploymentId,@LeavingDate LeavingDate,N'Ended' Status;
 END TRY
 BEGIN CATCH
  IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
  THROW;
 END CATCH;
END;

-- CreateNoObjectionCertificate
CREATE   PROCEDURE dbo.CreateNoObjectionCertificate
@UserId INT, @AdmissionId INT, @CertificateDate DATE
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Certificates.Create';
    IF @AdmissionId <= 0
        THROW 58600, 'A valid student is required.', 1;
    IF @CertificateDate IS NULL
        THROW 58601, 'Certificate 
date is required.', 1;
    IF @CertificateDate > CONVERT (DATE, SYSDATETIME())
        THROW 58602, 'Certificate date cannot be in the future.', 1;
    DECLARE @StudentName AS NVARCHAR (500), @FatherName AS NVARCHAR (500), @NoObjectionCertificateId AS INT;
    BEGIN TRANSACTION;
    SELECT @StudentName = S.StudentName,
           @FatherName = S.FatherName
    FROM   dbo.Students AS S WITH (UPDLOCK, HOLDLOCK)
    WHERE  S.AdmissionId = @AdmissionId;
    IF @StudentName IS NULL
        THROW 58603, 'The student was not found.', 1;
    INSERT  dbo.NoObjectionCertificates (AdmissionId, StudentName, FatherName, CertificateDate, CreatedByUserId)
    VALUES                             (@AdmissionId, @StudentName, @FatherName, @CertificateDate, @UserId);
    SET @NoObjectionCertificateId = CONVERT (INT, SCOPE_IDENTITY());
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    DECLARE @RecordId AS NVARCHAR (200) = CONVERT (NVARCHAR (200), @NoObjectionCertificateId);
    DECLARE @NewValues AS NVARCHAR (MAX);
    SELECT @NewValues = (SELECT @NoObjectionCertificateId AS NoObjectionCertificateId,
                                @AdmissionId AS AdmissionId,
                                @StudentName AS StudentName,
                                @FatherName AS FatherName,
                                @CertificateDate AS CertificateDate
                         FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'NO_OBJECTION_CERTIFICATE', CONVERT (NVARCHAR (200), @AdmissionId));
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'NoObjectionCertificates', @RecordId = @RecordId, @Action = N'INSERT', @OldValues = NULL, @NewValues = @NewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM db
o.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @NoObjectionCertificateId AS NoObjectionCertificateId,
           @AdmissionId AS AdmissionId;
END

-- UpdateNoObjectionCertificate
CREATE   PROCEDURE dbo.UpdateNoObjectionCertificate
@UserId INT, @NoObjectionCertificateId INT, @CertificateDate DATE
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Certificates.Create';
    IF @NoObjectionCertificateId <= 0
        THROW 58610, 'A valid NOC is required.', 1;
    IF @CertificateDate IS NULL
        THROW 58611, 'Certificate date is required.', 1;
    IF @CertificateDate > CONVERT (DATE, SYSDATETIME())
        THROW 58612, 'Certificate date cannot be in the future.', 1;
    BEGIN TRANSACTION;
    DECLARE @AdmissionId AS INT;
    DECLARE @OldValues AS NVARCHAR (MAX);
    SELECT @AdmissionId = NOC.AdmissionId,
           @OldValues = (SELECT NOC.NoObjectionCertificateId,
                                NOC.AdmissionId,
                                NOC.CertificateDate
                         FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES)
    FROM   dbo.NoObjectionCertificates AS NOC WITH (UPDLOCK, HOLDLOCK)
    WHERE  NOC.NoObjectionCertificateId = @NoObjectionCertificateId;
    IF @AdmissionId IS NULL
        THROW 58613, 'The NOC was not found.', 1;
    UPDATE dbo.NoObjectionCertificates
    SET    CertificateDate = @CertificateDate,
           UpdatedByUserId = @UserId,
           UpdatedAt       = SYSDATETIME()
    WHERE  NoObjectionCertificateId = @NoObjectionCertificateId;
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    DECLARE @RecordId AS NVARCHAR (200) = CONVERT (NVARCHAR (200), @NoObjectionCertificateId);
    DECLARE @NewValues AS NVARCHAR
 (MAX);
    SELECT @NewValues = (SELECT @NoObjectionCertificateId AS NoObjectionCertificateId,
                                @AdmissionId AS AdmissionId,
                                @CertificateDate AS CertificateDate
                         FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'NO_OBJECTION_CERTIFICATE', CONVERT (NVARCHAR (200), @AdmissionId));
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'NoObjectionCertificates', @RecordId = @RecordId, @Action = N'UPDATE', @OldValues = @OldValues, @NewValues = @NewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @NoObjectionCertificateId AS NoObjectionCertificateId,
           @AdmissionId AS AdmissionId;
END

/* ============================================================================
   PART 8 — dbo.IssueLeaveCertificate: cap at 2 duplicates
============================================================================ */

CREATE PROCEDURE dbo.IssueLeaveCertificate
    @UserId INT,
    @LeaveRecordId INT,
    @Remarks NVARCHAR(2000) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    EXEC dbo.RequirePermission
        @UserId,
        N'Students.Leave';

    IF @LeaveRecordId <= 0
        THROW 57400,
            'A valid leave certificate is required.',
            1;

    BEGIN TRANSACTION;

    IF NOT EXISTS
    (
        SELECT 1
        FROM dbo.LeaveCertificates
        WHERE LeaveRecordId = @LeaveRecordId
    )
        THROW 57401
,
            'The leave certificate was not found.',
            1;

    DECLARE
        @LastIssueId INT,
        @LastCollectedAt DATETIME2;

    SELECT TOP (1)
        @LastIssueId = LCI.LeaveCertificateIssueId,
        @LastCollectedAt = LCI.CollectedAt
    FROM dbo.LeaveCertificateIssues AS LCI WITH (UPDLOCK, HOLDLOCK)
    WHERE LCI.LeaveRecordId = @LeaveRecordId
    ORDER BY
        LCI.IssuedAt DESC,
        LCI.LeaveCertificateIssueId DESC;

    IF @LastIssueId IS NOT NULL
       AND @LastCollectedAt IS NULL
        THROW 57402,
            'The currently issued certificate has not been collected yet.',
            1;

    -- NEW: only 1 Original (created by CreateLeaveCertificate) + 2
    -- Duplicates are allowed per leave certificate. A 3rd "issue again"
    -- attempt is refused.
    DECLARE @DuplicateCount INT;

    SELECT @DuplicateCount = COUNT(*)
    FROM dbo.LeaveCertificateIssues
    WHERE LeaveRecordId = @LeaveRecordId
      AND IssueType = N'Duplicate';

    IF @DuplicateCount >= 2
        THROW 57403,
            'This certificate has already been issued as a duplicate twice (the maximum allowed). No further copies can be issued.',
            1;

    INSERT dbo.LeaveCertificateIssues
    (
        LeaveRecordId,
        IssuedAt,
        IssuedByUserId,
        Remarks,
        IssueType
    )
    VALUES
    (
        @LeaveRecordId,
        SYSDATETIME(),
        @UserId,
        @Remarks,
        N'Duplicate'
    );

    DECLARE @IssueId INT =
        CONVERT(INT, SCOPE_IDENTITY());

    COMMIT;

    SELECT
        @IssueId AS LeaveCertificateIssueId,
        @LeaveRecordId AS LeaveRecordId;
END;

CREATE   PROCEDURE dbo.MarkLeaveCertificateCollected
    @UserId INT,
    @LeaveCertificateIssueId INT,
    @CollectedBy NVARCHAR(400)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    EXEC dbo.RequirePermission
        @UserId,
        N'Students.Leave';

    IF @LeaveCertificateIssueId <= 0
        THROW 57500,
            'A valid certificate issue is required.',
            1;

    IF NULLIF(LTRIM(RTRIM(@CollectedBy)), N'') IS NULL
        THROW 57501,
            'The name of the person collecting the certificate is required.',
            1;

    UPDATE dbo.LeaveCertificateIssues
    SET
        CollectedAt = SYSDATETIME(),
        CollectedBy = LTRIM(RTRIM(@CollectedBy))
    WHERE Le
aveCertificateIssueId = @LeaveCertificateIssueId
      AND CollectedAt IS NULL;

    IF @@ROWCOUNT <> 1
        THROW 57502,
            'The certificate issue was not found or has already been collected.',
            1;

    SELECT
        LeaveCertificateIssueId,
        LeaveRecordId,
        IssuedAt,
        IssuedByUserId,
        CollectedAt,
        CollectedBy
    FROM dbo.LeaveCertificateIssues
    WHERE LeaveCertificateIssueId = @LeaveCertificateIssueId;
END;

/* =====================================================================
   5. dbo.GetNoObjectionCertificatePrintData

      CertificateNumber follows the same derived-from-identity
      convention as the other certificates ("NOC-000123").
   ===================================================================== */

CREATE PROCEDURE dbo.GetNoObjectionCertificatePrintData
    @UserId INT,
    @NoObjectionCertificateId INT
AS
BEGIN
    SET NOCOUNT ON;

    EXEC dbo.RequirePermission
        @UserId,
        N'Certificates.Print';

    IF @NoObjectionCertificateId <= 0
        THROW 58620, 'A valid NOC is required.', 1;

    SELECT
        NOC.NoObjectionCertificateId,
        NOC.AdmissionId,

        NOC.CertificateNumber AS CertificateNumber,

        NOC.StudentName,
        NOC.FatherName,
        NOC.CertificateDate,
        NOC.CreatedAt AS DateOfIssue

    FROM dbo.NoObjectionCertificates AS NOC
    WHERE NOC.NoObjectionCertificateId = @NoObjectionCertificateId;
END;

-- AddStudentFeeAssignment
CREATE   PROCEDURE dbo.AddStudentFeeAssignment
@UserId INT, @EnrollmentId INT, @FeeTypeId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    EXECUTE dbo.RequirePermission @UserId, N'Fees.Adjust';
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.Enrollments
                   WHERE  EnrollmentId = @EnrollmentId)
        THROW 53110, 'The selected enrollment does not exist.', 1;
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.Enrollments
                   WHERE  EnrollmentId = @EnrollmentId
                          AND BillingReady = 1)
        THROW 53114, 'Confirm return admission before adding fees.', 1;
    DECLARE @CampusId AS INT, @ClassId AS INT, @AdmissionId AS INT;
    SELECT @AdmissionId = E.AdmissionId,
           @CampusId = CCS.CampusId,
           @ClassId = CCS.ClassId
    FROM   dbo.Enrollments AS E
           INNER JOIN
           dbo.CampusClassSections AS CCS
           ON CCS.ClassSectionId = E.ClassSectionId
    WHERE  E.EnrollmentId = @EnrollmentId;
    DECLARE @FmscCutoffDay AS INT;
    SELECT TOP (1) @FmscCutoffDay = FeeProrationCutoffDay
    FROM   dbo.SchoolProfile;
    DECLARE @FmscOpeningMonth AS DATE = CASE WHEN @FmscCutoffDay BETWEEN 1 AND 28
                                                  AND DAY(GETDATE()) >= @FmscCutoffDay THEN DATEADD(MONTH, 1, DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1)) ELSE DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1) END;
    BEGIN TRANSACTION;
    DECLARE @StudentFeeAssignmentId AS INT;
    DECLARE @OldValues AS NVARCHAR (MAX) = (SELECT TOP (1) StudentFeeAssignmentId,
                                                           EnrollmentId,
                                                           AdmissionId,
                                                           FeeTypeId,
                                                           Amount,
                                                           DiscountAmount,
                                                           Frequency,

  EffectiveFrom,
                                                           EffectiveTo,
                                                           CancelledAt
                                            FROM   dbo.StudentFeeAssignments WITH (UPDLOCK, HOLDLOCK)
                                            WHERE  EnrollmentId = @EnrollmentId
                                                   AND FeeTypeId = @FeeTypeId
                                                   AND EffectiveTo IS NULL
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    DECLARE @AuditAction AS NVARCHAR (20);
    IF EXISTS (SELECT 1
               FROM   dbo.StudentFeeAssignments
               WHERE  EnrollmentId = @EnrollmentId
                      AND FeeTypeId = @FeeTypeId
                      AND EffectiveTo IS NULL)
        BEGIN
            DECLARE @ExistingAssignmentId AS INT;
            SELECT @ExistingAssignmentId = StudentFeeAssignmentId
            FROM   dbo.StudentFeeAssignments
            WHERE  EnrollmentId = @EnrollmentId
                   AND FeeTypeId = @FeeTypeId
                   AND EffectiveTo IS NULL;
            DECLARE @HasBillingHistory AS BIT = CASE WHEN EXISTS (SELECT 1
                                                                  FROM   dbo.BillingCharges
                                                                  WHERE  StudentFeeAssignmentId = @ExistingAssignmentId) THEN 1 ELSE 0 END;
            SET @AuditAction = N'UPDATE';
            IF @HasBillingHistory = 0
                BEGIN
                    UPDATE SFA
                    SET    SFA.CancelledAt    = NULL,
                           SFA.Amount         = FC.Amount,
                           SFA.Frequency      = FC.Frequency,
                           SFA.DiscountAmount = 0,
                           SFA.UpdatedAt      = SYSDATETIME()
                    FROM   db
o.StudentFeeAssignments AS SFA
                           INNER JOIN
                           dbo.FeeConfigurations AS FC
                           ON FC.FeeTypeId = SFA.FeeTypeId
                              AND FC.CampusId = @CampusId
                              AND FC.ClassId = @ClassId
                    WHERE  SFA.StudentFeeAssignmentId = @ExistingAssignmentId;
                    IF @@ROWCOUNT = 0
                        BEGIN
                            ROLLBACK;
                            THROW 53111, 'This fee is not configured for the student''s campus/class.', 1;
                        END
                    SET @StudentFeeAssignmentId = @ExistingAssignmentId;
                END
            ELSE
                BEGIN
                    DECLARE @ReactivateEffectiveFrom AS DATE = @FmscOpeningMonth;
                    DECLARE @LastBilledMonth AS DATE;
                    SELECT @LastBilledMonth = MAX(BillingMonth)
                    FROM   dbo.BillingCharges
                    WHERE  StudentFeeAssignmentId = @ExistingAssignmentId;
                    IF @LastBilledMonth IS NOT NULL
                       AND @ReactivateEffectiveFrom <= @LastBilledMonth
                        BEGIN
                            ROLLBACK;
                            THROW 53113, 'This fee cannot be reactivated starting this month because a later month has already been billed under the previous version. Please review Fee Setup.', 1;
                        END
                    UPDATE dbo.StudentFeeAssignments
                    SET    EffectiveTo = DATEADD(MONTH, -1, @ReactivateEffectiveFrom),
                           UpdatedAt   = SYSDATETIME()
                    WHERE  StudentFeeAssignmentId = @ExistingAssignmentId
                           AND EffectiveTo IS NULL;
                    INSERT dbo.StudentFeeAssignments (EnrollmentId, AdmissionId, FeeTypeId, Amount, DiscountAmount, Frequency, R
emarks, EffectiveFrom, EffectiveTo)
                    SELECT @EnrollmentId,
                           @AdmissionId,
                           FC.FeeTypeId,
                           FC.Amount,
                           0,
                           FC.Frequency,
                           N'Reactivated - new version starting current month',
                           @ReactivateEffectiveFrom,
                           NULL
                    FROM   dbo.FeeConfigurations AS FC
                    WHERE  FC.FeeTypeId = @FeeTypeId
                           AND FC.CampusId = @CampusId
                           AND FC.ClassId = @ClassId;
                    IF @@ROWCOUNT = 0
                        BEGIN
                            ROLLBACK;
                            THROW 53111, 'This fee is not configured for the student''s campus/class.', 1;
                        END
                    SET @StudentFeeAssignmentId = CONVERT (INT, SCOPE_IDENTITY());
                END
        END
    ELSE
        BEGIN
            SET @AuditAction = N'INSERT';
            DECLARE @EffectiveFromForNewRow AS DATE = @FmscOpeningMonth;
            INSERT dbo.StudentFeeAssignments (EnrollmentId, AdmissionId, FeeTypeId, Amount, DiscountAmount, Frequency, Remarks, EffectiveFrom, EffectiveTo)
            SELECT @EnrollmentId,
                   @AdmissionId,
                   FC.FeeTypeId,
                   FC.Amount,
                   0,
                   FC.Frequency,
                   N'Added from Student Admission',
                   @EffectiveFromForNewRow,
                   NULL
            FROM   dbo.FeeConfigurations AS FC
            WHERE  FC.FeeTypeId = @FeeTypeId
                   AND FC.CampusId = @CampusId
                   AND FC.ClassId = @ClassId;
            IF @@ROWCOUNT = 0
                BEGIN
                    ROLLBACK;
                    THROW 5311
2, 'This fee is not configured for the student''s campus/class.', 1;
                END
            SET @StudentFeeAssignmentId = CONVERT (INT, SCOPE_IDENTITY());
        END
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'FEE_ASSIGNMENT_ADD', CONVERT (NVARCHAR (200), @StudentFeeAssignmentId));
    DECLARE @NewValues AS NVARCHAR (MAX) = (SELECT StudentFeeAssignmentId,
                                                   EnrollmentId,
                                                   AdmissionId,
                                                   FeeTypeId,
                                                   Amount,
                                                   DiscountAmount,
                                                   Frequency,
                                                   EffectiveFrom,
                                                   EffectiveTo,
                                                   CancelledAt
                                            FROM   dbo.StudentFeeAssignments
                                            WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'StudentFeeAssignments', @RecordId = @StudentFeeAssignmentId, @Action = @AuditAction, @OldValues = @OldValues, @NewValues = @NewValues;
    DECLARE @FmscFrequency AS NVARCHAR (30), @FmscAmount AS DECIMAL (18, 2), @FmscDiscount AS DECIMAL (18, 2), @FmscFeeTypeId AS INT, @FmscEnrollmentId AS INT, @FmscAdmissionId AS INT, @FmscStartMonth AS DATE, @FmscPostMonth AS DATE;
    SELECT @FmscFrequency = Frequency,
           @FmscAmount = Amount,
           @FmscDiscount = DiscountAmount,

          @FmscFeeTypeId = FeeTypeId,
           @FmscEnrollmentId = EnrollmentId,
           @FmscAdmissionId = AdmissionId,
           @FmscStartMonth = DATEFROMPARTS(YEAR(ISNULL(EffectiveFrom, @FmscOpeningMonth)), MONTH(ISNULL(EffectiveFrom, @FmscOpeningMonth)), 1)
    FROM   dbo.StudentFeeAssignments
    WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId;
    SET @FmscPostMonth = CASE WHEN @FmscStartMonth > @FmscOpeningMonth THEN @FmscStartMonth ELSE @FmscOpeningMonth END;
    IF @FmscFrequency IN (N'Monthly', N'Yearly')
        BEGIN
            INSERT dbo.BillingCharges (StudentFeeAssignmentId, EnrollmentId, AdmissionId, FeeTypeId, BillingMonth, ChargeDate, DueDate, GrossAmount, DiscountAmount, ChargeKind)
            SELECT @StudentFeeAssignmentId,
                   @FmscEnrollmentId,
                   @FmscAdmissionId,
                   @FmscFeeTypeId,
                   @FmscPostMonth,
                   @FmscPostMonth,
                   @FmscPostMonth,
                   @FmscAmount,
                   @FmscDiscount,
                   CASE WHEN @FmscFrequency = N'Yearly' THEN N'Annual' ELSE N'Monthly' END
            WHERE  NOT EXISTS (SELECT 1
                               FROM   dbo.BillingCharges AS BC
                               WHERE  BC.EnrollmentId = @FmscEnrollmentId
                                      AND BC.FeeTypeId = @FmscFeeTypeId
                                      AND BC.Status <> N'Cancelled'
                                      AND ((@FmscFrequency = N'Yearly'
                                            AND BC.ChargeKind = N'Annual')
                                           OR (@FmscFrequency = N'Monthly'
                                               AND BC.ChargeKind = N'Monthly'
                                               AND BC.BillingMonth = @FmscPostMonth)));
        END
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELE
CT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
END

-- DeleteStudentFeeAssignment
CREATE   PROCEDURE dbo.DeleteStudentFeeAssignment
@UserId INT, @StudentFeeAssignmentId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Fees.Adjust';
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.StudentFeeAssignments
                   WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId
                          AND CancelledAt IS NULL)
        THROW 53120, 'The selected student fee assignment does not exist.', 1;
    IF EXISTS (SELECT 1
               FROM   dbo.BillingCharges AS BC
               WHERE  BC.StudentFeeAssignmentId = @StudentFeeAssignmentId
                      AND (SELECT ISNULL(SUM(FA.Amount), 0)
                           FROM   dbo.FeePaymentAllocations AS FA
                                  INNER JOIN
                                  dbo.FeePayments AS FP
                                  ON FP.FeePaymentId = FA.FeePaymentId
                                     AND FP.Status = N'Completed'
                           WHERE  FA.BillingChargeId = BC.BillingChargeId) > 0)
        THROW 53121, 'This fee has already been paid, so it cannot be removed. Reverse the payment on its charge in Fee Collection first.', 1;
    BEGIN TRANSACTION;
    UPDATE dbo.BillingCharges
    SET    Status  = N'Cancelled',
           Remarks = ISNULL(NULLIF (Remarks, N''), N'') + N' Cancelled with its fee assignment.'
    WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId
           AND Status <> N'Cancelled';
    UPDATE dbo.StudentFeeAssignments
    SET    CancelledAt = SYSDATETIME(),
           UpdatedAt   = SYSDATETIME()
    WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId;
    IF @@ROWCOUNT = 0

 BEGIN
            ROLLBACK;
            THROW 53122, 'The student fee assignment could not be removed.', 1;
        END
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'FEE_ASSIGNMENT_REMOVE', CONVERT (NVARCHAR (200), @StudentFeeAssignmentId));
    DECLARE @CancellationValues AS NVARCHAR (MAX) = (SELECT CancelledAt
                                                     FROM   dbo.StudentFeeAssignments
                                                     WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId
                                                     FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'StudentFeeAssignments', @RecordId = @StudentFeeAssignmentId, @Action = N'UPDATE', @OldValues = N'{"CancelledAt":null}', @NewValues = @CancellationValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
END

CREATE   PROCEDURE dbo.ReserveAdmissionNumber
    @AdmissionNumber VARCHAR(40) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    IF @@TRANCOUNT = 0 THROW 59201, 'Admission number allocation requires an admission transaction.', 1;
    DECLARE @Last BIGINT;
    SELECT @Last=LastNumber FROM dbo.AdmissionNumberCounter WITH (UPDLOCK,HOLDLOCK) WHERE CounterId=1;
    IF @Last IS NULL THROW 59202, 'The admission number counter is missing.', 1;
    IF NULLIF(LTRIM(RTRIM(@AdmissionNumber)), '') IS NULL
        SET @AdmissionNumber=CONVERT(VARCHAR(40), @Last+1);
    SET @AdmissionNumber=dbo.NormalizeAdmissionNumber(@AdmissionNumber);
    IF @AdmissionNumber IS NULL THROW 59203, 'Use a positive admission number with an optional letter suffix, such as 1 or 1a.', 1;
    IF EXISTS (SELECT 1 FROM dbo.Students WHERE AdmissionNumber=@AdmissionNumber)
        THROW 59204, 'This admission number is already assigned to another student. Choose a different number.', 1;
    DECLARE @Base BIGINT = TRY_CONVERT(BIGINT, LEFT(@AdmissionNumber, PATINDEX('%[^0-9]%', @AdmissionNumber+'x')-1));
    IF @Base>@Last UPDATE dbo.AdmissionNumberCounter SET LastNumber=@Base WHERE CounterId=1;
END;

-- SetStudentAdmissionNumber
CREATE   PROCEDURE dbo.SetStudentAdmissionNumber
@UserId INT, @AdmissionId INT, @AdmissionNumber VARCHAR (40)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    EXECUTE dbo.RequirePermission @UserId, N'Students.Administer';
    IF @@TRANCOUNT = 0
        THROW 59205, 'Save the admission number together with student details.', 1;
    SET @AdmissionNumber = dbo.NormalizeAdmissionNumber(@AdmissionNumber);
    IF @AdmissionNumber IS NULL
        THROW 59203, 'Use a positive admission number with an optional letter suffix, such as 1 or 1a.', 1;
    DECLARE @Last AS BIGINT;
    SELECT @Last = LastNumber
    FROM   dbo.AdmissionNumberCounter WITH (UPDLOCK, HOLDLOCK)
    WHERE  CounterId = 1;
    IF @Last IS NULL THROW 59202, 'The admission number counter is missing.', 1;
    DECLARE @OldNumber AS VARCHAR (40);
    SELECT @OldNumber = AdmissionNumber
    FROM   dbo.Students WITH (UPDLOCK, HOLDLOCK)
    WHERE  AdmissionId = @AdmissionId;
    IF @OldNumber IS NULL
        THROW 51710, 'The selected student was not found.', 1;
    IF @OldNumber = @AdmissionNumber
        RETURN;
    IF EXISTS (SELECT 1
               FROM   dbo.Students
               WHERE  AdmissionNumber = @AdmissionNumber
                      AND AdmissionId <> @AdmissionId)
        THROW 59204, 'This admission number is already assigned to another student. Choose a different number.', 1;

    UPDATE dbo.Students
    SET    AdmissionNumber = @AdmissionNumber,
           UpdatedAt       = SYSDATETIME()
    WHERE  AdmissionId = @AdmissionId;
    -- All allocators lock the counter first, so renumbering and allocation stay serialized.
    -- Letter suffixes contribute their numeric base: 6590a belongs to register number 6590.
    DECLARE @HighestAssigned BIGINT;
    SELECT @HighestAssigned = ISNULL(MAX(TRY_CONVERT(BIGINT,
        LEFT(AdmissionNumber, PATINDEX('%[^0-9]%', AdmissionNumber + 'x') - 1))), 0)
    FROM dbo.Students;
    UPDATE dbo.AdmissionNumberCounter SET LastNumber = @HighestAssigned WHERE CounterId = 1;
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID(), @RecordId AS NVARCHAR (200) =
 CONVERT (NVARCHAR (200), @AdmissionId);
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'ADMISSION_NUMBER_CHANGE', @RecordId);
    DECLARE @OldValues AS NVARCHAR (MAX) = (SELECT @OldNumber AS AdmissionNumber
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER);
    DECLARE @NewValues AS NVARCHAR (MAX) = (SELECT @AdmissionNumber AS AdmissionNumber
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER);
    EXECUTE dbo.WriteAuditLog @OperationId, @UserId, N'Students', @RecordId, N'UPDATE', @OldValues, @NewValues;
DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
END

/* ---------------------------------------------------------------------------
   1. The retention procedure, with the row cap
   --------------------------------------------------------------------------- */

CREATE PROCEDURE dbo.PruneAuditTrail
(
      @UserId                        INT
    , @ClearPayloadOlderThanMonths   INT
    , @DeleteOlderThanMonths         INT
    , @MaxRows                       INT = 0
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* Removing or gutting audit evidence is a management action, not a viewing one:
       the screen itself is gated on System.Audit. */
    EXEC dbo.RequirePermission @UserId, N'System.Administration';

    IF @ClearPayloadOlderThanMonths IS NULL OR @ClearPayloadOlderThanMonths < 0
        THROW 59930, 'The full-detail window cannot be negative.', 1;

    IF @DeleteOlderThanMonths IS NULL OR @DeleteOlderThanMonths < 0
        THROW 59931, 'The retention window cannot be negative.', 1;

    IF @MaxRows IS NULL OR @MaxRows < 0
        THROW 59932, 'The row cap cannot be negative.', 1;

    DECLARE @PayloadsCleared INT = 0;
    DECLARE @RowsDeleted INT = 0;
    DECLARE @RowsCapped INT = 0;
    DECLARE @OperationsRemoved INT = 0;
    DECLARE @Cutoff DATETIME2;

    BEGIN TRY
        BEGIN TRANSACTION;

        /* ---- stage 1: keep the record, drop the before/after images ---- */

        IF @ClearPayloadOlderThanMonths > 0
        BEGIN
            SET @Cutoff = DATEADD(month, -@ClearPayloadOlderThanMonths, SYSDATETIME());

            UPDATE dbo.AuditLogs
            SET OldValues = NULL,
                NewValues = NULL
            WHERE ActionDateTime < @Cutoff
              AND (OldValues IS NOT NULL OR NewValues IS NOT NULL);


        SET @PayloadsCleared = @@ROWCOUNT;
        END

        /* ---- stage 2: the rows themselves, only when a window is asked for ---- */

        IF @DeleteOlderThanMonths > 0
        BEGIN
            SET @Cutoff = DATEADD(month, -@DeleteOlderThanMonths, SYSDATETIME());

            DELETE FROM dbo.AuditLogs
            WHERE ActionDateTime < @Cutoff;

            SET @RowsDeleted = @@ROWCOUNT;

            /* The headers those rows belonged to. The NOT EXISTS guard is what makes
               this safe on a second run and leaves any operation that still has a
               line to explain it. */
            DELETE FROM dbo.AuditOperations
            WHERE StartedAt < @Cutoff
              AND NOT EXISTS
                  (
                      SELECT 1
                      FROM dbo.AuditLogs L
                      WHERE L.OperationId = dbo.AuditOperations.OperationId
                  );

            SET @OperationsRemoved = @@ROWCOUNT;
        END

        /* ---- stage 3: the hard cap - the newest @MaxRows lines, and no more ---- */

        IF @MaxRows > 0
        BEGIN
            /* AuditLogId is an identity, so its order IS the order things happened;
               OFFSET without FETCH is "skip the newest N, delete the rest". */
            DELETE FROM dbo.AuditLogs
            WHERE AuditLogId IN
            (
                SELECT AuditLogId
                FROM dbo.AuditLogs
                ORDER BY AuditLogId DESC
                OFFSET @MaxRows ROWS
            );

            SET @RowsCapped = @@ROWCOUNT;

            /* Headers left with nothing to explain. Bounded by the oldest surviving
               line, so a header that never had a line in the first place is not
               touched - and when the trail is empty the comparison is NULL and
               nothing goes. */
            DECLARE @OldestKept DAT
ETIME2 =
                (SELECT MIN(ActionDateTime) FROM dbo.AuditLogs);

            DELETE FROM dbo.AuditOperations
            WHERE StartedAt < @OldestKept
              AND NOT EXISTS
                  (
                      SELECT 1
                      FROM dbo.AuditLogs L
                      WHERE L.OperationId = dbo.AuditOperations.OperationId
                  );

            SET @OperationsRemoved = @OperationsRemoved + @@ROWCOUNT;
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        THROW;
    END CATCH

    SELECT
        @PayloadsCleared      AS PayloadsCleared,
        @RowsDeleted          AS RowsDeleted,
        @RowsCapped           AS RowsCapped,
        @OperationsRemoved    AS OperationsRemoved,
        @ClearPayloadOlderThanMonths AS FullDetailMonths,
        @DeleteOlderThanMonths       AS RetentionMonths,
        @MaxRows                     AS MaxRows;
END;

-- BootstrapFirstAdministrator
CREATE   PROCEDURE dbo.BootstrapFirstAdministrator
@Username NVARCHAR (100), @PasswordHash VARBINARY (64), @PasswordSalt VARBINARY (32)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRANSACTION;
    DECLARE @SetupLockResult AS INT;
    EXECUTE @SetupLockResult = sys.sp_getapplock @Resource = N'FMSC.FirstRunAdministrator', @LockMode = N'Exclusive', @LockOwner = N'Transaction', @LockTimeout = 5000;
    IF @SetupLockResult < 0
        THROW 57207, 'Administrator setup is already in progress in another window. Wait for it to finish, then sign in with the administrator account it creates.', 1;
    IF EXISTS (SELECT 1
               FROM   dbo.Users)
        THROW 57200, 'Initial administrator setup is already com
pleted. Please sign in with an existing administrator account.', 1;
    IF NULLIF (LTRIM(RTRIM(@Username)), N'') IS NULL
        THROW 57201, 'Administrator username is required.', 1;
    IF LEN(LTRIM(RTRIM(@Username))) > 100
        THROW 57202, 'Administrator username is too long.', 1;
    IF @PasswordHash IS NULL
       OR DATALENGTH(@PasswordHash) <> 64
        THROW 57203, 'The supplied administrator password hash is invalid.', 1;
    IF @PasswordSalt IS NULL
       OR DATALENGTH(@PasswordSalt) <> 32
        THROW 57204, 'The supplied administrator password salt is invalid.', 1;
    DECLARE @RoleId AS INT;
    SELECT   TOP (1) @RoleId = RoleId
    FROM     dbo.Roles
    WHERE    RoleName = N'Administrator'
    ORDER BY RoleId;
    IF @RoleId IS NULL
        THROW 57205, 'The Administrator role is not available. Database reference data is incomplete.', 1;
    IF EXISTS (SELECT 1
               FROM   dbo.Users
               WHERE  Username = LTRIM(RTRIM(@Username)))
        THROW 57206, 'That administrator username already exists.', 1;
    INSERT  dbo.Users (Username, PasswordHash, PasswordSalt, RoleId, MustChangePassword)
    VALUES           (LTRIM(RTRIM(@Username)), @PasswordHash, @PasswordSalt, @RoleId, 1);
    DECLARE @UserId AS INT = CONVERT (INT, SCOPE_IDENTITY());
    INSERT dbo.UserRoles (UserId, RoleId)
    SELECT @UserId,
           R.RoleId
    FROM   dbo.Roles AS R
    WHERE  NOT EXISTS (SELECT 1
                       FROM   dbo.UserRoles AS UR
                       WHERE  UR.UserId = @UserId
                              AND UR.RoleId = R.RoleId);
    COMMIT TRANSACTION;
    SELECT @UserId AS UserId,
           LTRIM(RTRIM(@Username)) AS Username,
           @RoleId AS RoleId;
END

-- ChangeOwnPassword
CREATE   PROCEDURE dbo.ChangeOwnPassword
@UserId INT, @PasswordHash VARBINARY (64), @PasswordSalt VARBINARY (32)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequireAuthenticatedUser @UserId;
    IF @PasswordHash IS NULL
       OR DATALENGTH(@PasswordHash) <> 64
        THROW 57001, 'The supplied password hash is invalid.', 1;
    IF @PasswordSalt IS NULL
       OR DATALENGTH(@PasswordSalt) <> 32
        THROW 57002, 'The supplied password salt is invalid.', 1;
    BEGIN TRANSACTION;
    UPDATE dbo.Users
    SET    PasswordHash       = @PasswordHash,
           PasswordSalt       = @PasswordSalt,
           MustChangePassword = 0,
           UpdatedAt          = SYSDATETIME()
    WHERE  UserId = @UserId;
    IF @@ROWCOUNT = 0
        THROW 57003, 'The user account is inactive or was not found.', 1;
    DECLARE @OperationId AS UNIQUEIDENTIFIER = 
NEWID();
    DECLARE @AuditRecordId AS NVARCHAR (200) = CAST (@UserId AS NVARCHAR (200));
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'PASSWORD_CHANGE', @AuditRecordId);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'Users', @RecordId = @AuditRecordId, @Action = N'UPDATE', @OldValues = NULL, @NewValues = N'{"PasswordChanged":true,"MustChangePassword":false}';
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
END

CREATE   PROCEDURE dbo.GetAdditionalFeeCandidates
    @UserId int,
    @AcademicYearId int,
    @CampusId int = 0,
    @ClassId int = 0,
    @SectionId int = 0
AS
BEGIN
    SET NOCOUNT ON;
    EXEC dbo.RequirePermission @UserId, N'Fees.Collect';
    IF NOT EXISTS (SELECT 1 FROM dbo.AcademicYears
                   WHERE AcademicYearId = @AcademicYearId AND IsCurrent = 1)
        THROW 53040, 'Additional fees must use the current academic year. Reload the page if it has changed.', 1;

    SELECT E.EnrollmentId, S.AdmissionNumber, S.RegistrationNumber, S.StudentName,
           S.FatherName, C.CampusName, CL.ClassName, SEC.SectionName,
           E.BillingStartDate
    FROM dbo.Enrollments E
    JOIN dbo.Students S ON S.AdmissionId = E.AdmissionId
    JOIN dbo.CampusClassSections CCS ON CCS.ClassSectionId = E.ClassSectionId
    JOI
N dbo.Campuses C ON C.CampusId = CCS.CampusId
    JOIN dbo.Classes CL ON CL.ClassId = CCS.ClassId
    JOIN dbo.Sections SEC ON SEC.SectionId = CCS.SectionId
    WHERE E.AcademicYearId = @AcademicYearId
      AND (@ClassId = 0 OR CCS.ClassId = @ClassId)
      AND (@CampusId = 0 OR CCS.CampusId = @CampusId)
      AND (@SectionId = 0 OR CCS.SectionId = @SectionId)
      AND E.Status = N'Active' AND E.BillingReady = 1
    ORDER BY C.CampusName, CL.DisplayOrder, SEC.DisplayOrder,
             S.AdmissionNumberBase, S.AdmissionNumberSuffix, S.StudentName;
END;

