CREATE   PROCEDURE dbo.CreateRegularLecturerCertificate
@UserId INT, @StaffId INT, @RoleTitle NVARCHAR (30), @SubjectTaught NVARCHAR (100), @CertificateDate DATE
AS
BEGIN
