CREATE   PROCEDURE dbo.ReorderSubjects
    @UserId int, @Items dbo.DisplayOrderItem READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXEC dbo.RequirePermission @UserId, N'System.Setup';
    BEGIN TRY
        BEGIN TRANSACTION;
        DECLARE @OrderLock int;
        EXEC @OrderLock=sys.sp_getapplock @Resource=N'SetupOrder:Subjects',
            @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=10000;
        IF @OrderLock<0 THROW 57401, 'Unable to lock setup ordering. Please try again.', 1;
        DECLARE @Count int;
        SELECT @Count=COUNT(*) FROM dbo.Subjects WITH(UPDLOCK,HOLDLOCK);
        IF @Count<>(SELECT COUNT(*) FROM @Items)
            THROW 57600, 'The supplied order must contain every entry in the list.', 1;
        IF EXISTS(SELECT ItemId FROM @Items GROUP BY ItemId HAVING COUNT(*)>1)
            THROW 57601, 'Duplicate entries were supplied.', 1;
        IF EXISTS(SELECT DisplayOrder FROM @Items GROUP BY DisplayOrder HAVING COUNT(*)>1)
            OR EXISTS(SELECT 1 FROM @Items WHERE DisplayOrde
r<1)
            THROW 57602, 'Invalid ordering positions were supplied.', 1;
        IF EXISTS(SELECT 1 FROM @Items I LEFT JOIN dbo.Subjects T ON T.SubjectId=I.ItemId
            WHERE T.SubjectId IS NULL)
            THROW 57603, 'An entry is invalid or belongs to another list.', 1;
        DECLARE @Ranked TABLE(ItemId int PRIMARY KEY, Position int);
        INSERT @Ranked SELECT ItemId, ROW_NUMBER() OVER(ORDER BY DisplayOrder,ItemId) FROM @Items;
        UPDATE T SET DisplayOrder=-R.Position FROM dbo.Subjects T JOIN @Ranked R ON R.ItemId=T.SubjectId;
        UPDATE T SET DisplayOrder=R.Position FROM dbo.Subjects T JOIN @Ranked R ON R.ItemId=T.SubjectId;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;

-- GetStudentAnnualFeeLedger
CREATE PROCEDURE dbo.GetStudentAnnualFeeLedger
@UserId INT, @AdmissionId INT, @AcademicYearId INT
AS
BEGIN
    SET NOCOUNT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Fees.Statement.View';
    IF @AdmissionId <= 0
        THROW 59501, 'A valid student is required.', 1;
    IF @AcademicYearId <= 0

        THROW 59502, 'A valid academic year is required.', 1;
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.Students
                   WHERE  AdmissionId = @AdmissionId)
        THROW 59503, 'The selected student was not found.', 1;
    DECLARE @YearStart AS DATE, @YearEnd AS DATE;
    SELECT @YearStart = StartDate, @YearEnd = EndDate
    FROM   dbo.AcademicYears
    WHERE  AcademicYearId = @AcademicYearId;
    IF @YearStart IS NULL
        THROW 59504, 'The selected academic year was not found.', 1;
    -- Business rule (V20 F-06): use the saved academic-year dates, inclusive.
    -- April 1 through March 31 normally covers twelve months; do not manufacture an end date.
    -- Preserve twelve columns for standard callers; expose extra months for longer saved years.
    IF @YearEnd IS NULL OR @YearEnd < @YearStart
        THROW 59505, 'The academic year has invalid saved dates.', 1;
    DECLARE @MonthCount int = DATEDIFF(month, @YearStart, @YearEnd) + 1;
    DECLARE @ColumnCount int = CASE WHEN @MonthCount < 12 THEN 12 ELSE @MonthCount END;
    DECLARE @Labels nvarchar(max) = N'', @Months nvarchar(max) = N'', @i int = 0;
    WHILE @i < @ColumnCount
    BEGIN
        SET @Labels += N'CASE WHEN ' + CONVERT(nvarchar(10),@i) + N' < @MonthCount THEN FORMAT(DATEADD(month,' + CONVERT(nvarchar(10),@i) + N',@YearStart),''MMM-yy'') ELSE NULL END AS M' + CONVERT(nvarchar(10),@i+1) + N'Label,';
        SET @Months += N'SUM(CASE WHEN Src.MonthIndex=' + CONVERT(nvarchar(10),@i) + N' THEN Src.NetAmount ELSE 0 END) AS M' + CONVERT(nvarchar(10),@i+1) + N'Due,SUM(CASE WHEN Src.MonthIndex=' + CONVERT(nvarchar(10),@i) + N' THEN Src.PaidAmount ELSE 0 END) AS M' + CONVERT(nvarchar(10),@i+1) + N'Paid,';
        SET @i += 1;
    END;
    DECLARE @StudentName AS NVARCHAR (200), @FatherName AS NVARCHAR (200), @RegistrationNumber AS NVARCHAR (50), @CampusName AS NVARCHAR (200), @ClassName AS NVARCHAR (100), @Sect
ionName AS NVARCHAR (100), @YearName AS NVARCHAR (50), @SchoolName AS NVARCHAR (200);
    SELECT   TOP (1) @StudentName = S.StudentName,
                     @FatherName = S.FatherName,
                     @RegistrationNumber = S.RegistrationNumber,
                     @CampusName = CAMP.CampusName,
                     @ClassName = C.ClassName,
                     @SectionName = SEC.SectionName
    FROM     dbo.Students AS S
             LEFT OUTER JOIN
             dbo.Enrollments AS E
             ON E.AdmissionId = S.AdmissionId
                AND E.AcademicYearId = @AcademicYearId
             LEFT OUTER JOIN
             dbo.CampusClassSections AS CCS
             ON CCS.ClassSectionId = E.ClassSectionId
             LEFT OUTER JOIN
             dbo.Campuses AS CAMP
             ON CAMP.CampusId = CCS.CampusId
             LEFT OUTER JOIN
             dbo.Classes AS C
             ON C.ClassId = CCS.ClassId
             LEFT OUTER JOIN
             dbo.Sections AS SEC
             ON SEC.SectionId = CCS.SectionId
    WHERE    S.AdmissionId = @AdmissionId
    ORDER BY E.EnrollmentDate DESC;
    SELECT @YearName = YearName
    FROM   dbo.AcademicYears
    WHERE  AcademicYearId = @AcademicYearId;
    SELECT TOP (1) @SchoolName = SchoolName
    FROM   dbo.SchoolProfile;
    DECLARE @Query nvarchar(max) = N'WITH     ChargePaid
    AS       (SELECT   FPA.BillingChargeId,
                       SUM(FPA.Amount) AS PaidAmount
              FROM     dbo.FeePaymentAllocations AS FPA
                       INNER JOIN
                       dbo.FeePayments AS FP
                       ON FP.FeePaymentId = FPA.FeePaymentId
              WHERE    FP.Status <> N''Reversed''
              GROUP BY FPA.BillingChargeId),
             Charges
    AS       (SELECT FT.FeeTypeId,
                     FT.F
eeTypeName,
                     FT.DisplayOrder,
                     DATEDIFF(month, @YearStart, BC.BillingMonth) AS MonthIndex,
                     BC.NetAmount,
                     ISNULL(CP.PaidAmount, 0) AS PaidAmount
              FROM   dbo.BillingCharges AS BC
                     INNER JOIN
                     dbo.FeeTypes AS FT
                     ON FT.FeeTypeId = BC.FeeTypeId
                     LEFT OUTER JOIN
                     ChargePaid AS CP
                     ON CP.BillingChargeId = BC.BillingChargeId
              WHERE  BC.AdmissionId = @AdmissionId
                     AND BC.Status <> N''Cancelled''
                     AND BC.BillingMonth >= @YearStart
                     AND BC.BillingMonth <= @YearEnd)
    SELECT   @StudentName AS StudentName,
             @FatherName AS FatherName,
             @RegistrationNumber AS RegistrationNumber,
             @CampusName AS CampusName,
             @ClassName AS ClassName,
             @SectionName AS SectionName,
             @YearName AS AcademicYearName,
             @SchoolName AS SchoolName,
             ' + @Labels + N'Src.FeeTypeName,
             Src.DisplayOrder,
             ' + @Months + N'SUM(Src.NetAmount) AS TotalDue,
             SUM(Src.PaidAmount) AS TotalPaid,
             SUM(Src.NetAmount) - SUM(Src.PaidAmount) AS TotalBalance
    FROM     Charges AS Src
    GROUP BY Src.FeeTypeName, Src.DisplayOrder
    UNION ALL
    SELECT   @StudentName,
             @FatherName,
             @RegistrationNumber,
             @CampusName,
             @ClassName,
             @SectionName,
             @YearName,
             @SchoolName,
             ' + @Labels + N'N''TOTAL'',
             999999,
             ' + @Months + N'SUM(NetAmount),
             SUM(PaidAmount),
             SUM(NetAmount)
 - SUM(PaidAmount)
    FROM     Charges AS Src
    ORDER BY DisplayOrder;';
    EXEC sys.sp_executesql @Query,N'@YearStart date,@YearEnd date,@MonthCount int,@StudentName nvarchar(200),@FatherName nvarchar(200),@RegistrationNumber nvarchar(50),@CampusName nvarchar(200),@ClassName nvarchar(100),@SectionName nvarchar(100),@YearName nvarchar(50),@SchoolName nvarchar(200),@AdmissionId int',@YearStart,@YearEnd,@MonthCount,@StudentName,@FatherName,@RegistrationNumber,@CampusName,@ClassName,@SectionName,@YearName,@SchoolName,@AdmissionId;
END;

CREATE   PROCEDURE dbo.ReorderClasses
    @UserId int, @AcademicProgramId int, @Items dbo.DisplayOrderItem READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXEC dbo.RequirePermission @UserId, N'System.Setup';
    BEGIN TRY
        BEGIN TRANSACTION;
        DECLARE @OrderLock int;
        EXEC @OrderLock=sys.sp_getapplock @Resource=N'SetupOrder:Classes',
            @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=10000;
        IF @OrderLock<0 THROW 57401, 'Unable to lock setup ordering. Please try again.', 1;
        DECLARE @Count int;
        SELECT @Count=COUNT(*) FROM dbo.Classes WITH(UPDLOCK,HOLDLOCK) WHERE AcademicProgramId=@AcademicProgramId;
        IF @Count<>(SELECT COUNT(*) FROM @Items)
            THROW 57600, 'The supplied order must contain every entry in the list.', 1;
        IF EXISTS(SELECT ItemId FROM @Items GROUP BY ItemId HAVING COUNT(*)>1)
            THROW 57601, 'Duplicate entries were supplied.', 1;
        IF EXISTS(SELECT DisplayOrder FROM @Items GROUP BY DisplayOrder HAVING COUNT(*)>1)
            OR EXISTS(SELECT 1 FROM @Items WHERE DisplayOrder<1)
            THROW 57602, 'Invalid ordering positions were supplied.', 1;
        IF EXISTS(SELECT 1 FROM @Items I LEFT JOIN dbo.Classes T ON T.ClassId=I.ItemId
            WHERE T.ClassId IS NULL 
OR T.AcademicProgramId<>@AcademicProgramId)
            THROW 57603, 'An entry is invalid or belongs to another list.', 1;
        DECLARE @Ranked TABLE(ItemId int PRIMARY KEY, Position int);
        INSERT @Ranked SELECT ItemId, ROW_NUMBER() OVER(ORDER BY DisplayOrder,ItemId) FROM @Items;
        UPDATE T SET DisplayOrder=-R.Position FROM dbo.Classes T JOIN @Ranked R ON R.ItemId=T.ClassId;
        UPDATE T SET DisplayOrder=R.Position FROM dbo.Classes T JOIN @Ranked R ON R.ItemId=T.ClassId;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;

-- TransferEnrollmentCampus
CREATE PROCEDURE dbo.TransferEnrollmentCampus
@UserId INT, @EnrollmentId INT, @NewClassSectionId INT, @TransferDate DATE, @Remarks NVARCHAR (500), @FeePolicy NVARCHAR (20)=NULL, @FeeSyncReason NVARCHAR (500)=NULL, @FeeEffectiveMonth DATE=NULL, @ReplaceScheduledFees BIT=0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Enrollment.Manage';
    IF @EnrollmentId <= 0
        THROW 52501, 'A valid enrollment is required.', 1;
    IF @
NewClassSectionId <= 0
        THROW 52502, 'A valid destination campus, class and section are required.', 1;
    IF @TransferDate IS NULL
        THROW 52503, 'Transfer date is required.', 1;
    IF @TransferDate > CONVERT (DATE, SYSDATETIME())
        THROW 52504, 'Transfer date cannot be in the future.', 1;
    BEGIN TRANSACTION;
    DECLARE @EnrollmentStartDate AS DATE;
    DECLARE @AdmissionId AS INT, @OldClassSectionId AS INT, @AcademicYearId AS INT, @OldCampusId AS INT, @NewCampusId AS INT, @OldStatus AS NVARCHAR (30);
    SELECT @EnrollmentStartDate=E.EnrollmentDate,
           @AdmissionId = E.AdmissionId,
           @OldClassSectionId = E.ClassSectionId,
           @AcademicYearId = E.AcademicYearId,
           @OldStatus = E.Status,
           @OldCampusId = CCS.CampusId
    FROM   dbo.Enrollments AS E WITH (UPDLOCK, HOLDLOCK)
           INNER JOIN
           dbo.CampusClassSections AS CCS
           ON CCS.ClassSectionId = E.ClassSectionId
    WHERE  E.EnrollmentId = @EnrollmentId
           AND E.Status = N'Active';
    IF @AdmissionId IS NULL
        THROW 52505, 'The selected enrollment is not active or does not exist.', 1;
    IF @TransferDate < @EnrollmentStartDate
        THROW 59308,'Transfer date cannot be before the enrollment date.',1;
    SELECT @NewCampusId = CCS.CampusId
    FROM   dbo.CampusClassSections AS CCS
    WHERE  CCS.ClassSectionId = @NewClassSectionId;
    IF @NewCampusId IS NULL
        THROW 52506, 'The destination class/section does not exist or is inactive.', 1;
    IF @OldCampusId = @NewCampusId
        THROW 52507, 'The destination campus is the same as the student''s current campus. Use Transfer Class or Transfer Section instead.', 1;
    IF @OldClassSectionId = @NewClassSectionId
        THROW 52508, 'The destination class/section is the same as the current placement.', 1;
    UPDATE dbo.Enrollments
    SET    ClassSectionId = @NewClassSectionId,

           UpdatedAt      = SYSDATETIME(),
           Remarks        = COALESCE (NULLIF (@Remarks, N''), Remarks)
    WHERE  EnrollmentId = @EnrollmentId
           AND Status = N'Active';
    IF @@ROWCOUNT <> 1
        THROW 52509, 'The active enrollment could not be transferred.', 1;
    INSERT  dbo.EnrollmentHistory (EnrollmentId, AdmissionId, ActionType, ActionDate, OldClassSectionId, NewClassSectionId, OldStatus, NewStatus, Remarks, UserId)
    VALUES                       (@EnrollmentId, @AdmissionId, N'TRANSFER_CAMPUS', @TransferDate, @OldClassSectionId, @NewClassSectionId, @OldStatus, N'Active', @Remarks, @UserId);
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'TRANSFER_CAMPUS', CONVERT (NVARCHAR (200), @AdmissionId));
    DECLARE @NewValues AS NVARCHAR (MAX);
    SELECT @NewValues = (SELECT @AdmissionId AS AdmissionId,
                                @EnrollmentId AS EnrollmentId,
                                @AcademicYearId AS AcademicYearId,
                                @OldCampusId AS OldCampusId,
                                @NewCampusId AS NewCampusId,
                                @OldClassSectionId AS OldClassSectionId,
                                @NewClassSectionId AS NewClassSectionId,
                                @TransferDate AS TransferDate,
                                @Remarks AS Remarks
                         FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    DECLARE @AuditRecordId AS NVARCHAR (200) = CONVERT (NVARCHAR (200), @EnrollmentId);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'Enrollments', @RecordId = @AuditRecordId, @Action = N'TRANSFER_CAMPUS', @OldValues = NULL, @NewValues = @NewValues;
    IF @FeePolicy IS NOT NULL
        BEGIN
            EXECUTE d
bo.RequirePermission @UserId, N'Fees.Adjust';
            DECLARE @FeeLockResult AS INT;
            DECLARE @FeeLockResource AS NVARCHAR (255) = N'FMSC.GenerateEnrollmentCharges.' + CONVERT (NVARCHAR (20), @EnrollmentId);
            EXECUTE @FeeLockResult = sys.sp_getapplock @Resource = @FeeLockResource, @LockMode = N'Exclusive', @LockOwner = N'Transaction', @LockTimeout = 5000;
            IF @FeeLockResult < 0
                THROW 52510, 'This enrollment is currently being billed or updated elsewhere. Please try again.', 1;
            EXECUTE dbo.SyncTransferStudentFees_Internal @UserId = @UserId, @EnrollmentId = @EnrollmentId, @FeePolicy = @FeePolicy, @Reason = @FeeSyncReason, @EffectiveDate = @TransferDate, @FeeEffectiveMonth=@FeeEffectiveMonth, @ReplaceScheduledFees=@ReplaceScheduledFees;
        END
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @EnrollmentId AS EnrollmentId,
           @AdmissionId AS AdmissionId,
           @NewClassSectionId AS NewClassSectionId;
END

-- ApplyFeeConfigurationToExistingAssignments
CREATE   PROCEDURE dbo.ApplyFeeConfigurationToExistingAssignments
@UserId INT, @CampusId INT, @ClassId INT, @FeeTypeId INT, @EffectiveFrom DATE, @Reason NVARCHAR (500)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT OFF;
    EXECUTE dbo.RequirePermission @UserId, N'Fees.Configuration.Manage';
    IF @Reason IS NULL
       OR LTRIM(RTRIM(@Reason)) = N''
        THROW 53151, 'A reason is required to apply a fee configuration change 
to existing students.', 1;
    IF @EffectiveFrom IS NULL
        THROW 53152, 'An effective-from date is required.', 1;
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.FeeConfigurations
                   WHERE  CampusId = @CampusId
                          AND ClassId = @ClassId
                          AND FeeTypeId = @FeeTypeId)
        THROW 53153, 'No fee configuration exists for the selected campus, class and fee type.', 1;
    DECLARE @NormalizedEffectiveFrom AS DATE = DATEFROMPARTS(YEAR(@EffectiveFrom), MONTH(@EffectiveFrom), 1);
    DECLARE @Candidates TABLE (
        RowNum                 INT             IDENTITY (1, 1),
        StudentFeeAssignmentId INT            ,
        NewAmount              DECIMAL (12, 2));
    INSERT INTO @Candidates (StudentFeeAssignmentId, NewAmount)
    SELECT StudentFeeAssignmentId,
           NewAmount
    FROM   dbo.fn_StaleFeeAssignmentsForConfiguration(@CampusId, @ClassId, @FeeTypeId);
    DECLARE @Total AS INT = (SELECT COUNT(*)
                             FROM   @Candidates);
    DECLARE @Succeeded AS INT = 0;
    DECLARE @Failed AS INT = 0;
    DECLARE @i AS INT = 1;
    DECLARE @CurrentAssignmentId AS INT, @CurrentNewAmount AS DECIMAL (12, 2);
    DECLARE @Failures TABLE (
        StudentFeeAssignmentId INT            ,
        ErrorMessage           NVARCHAR (2000));
    WHILE @i <= @Total
        BEGIN
            SELECT @CurrentAssignmentId = StudentFeeAssignmentId,
                   @CurrentNewAmount = NewAmount
            FROM   @Candidates
            WHERE  RowNum = @i;
            BEGIN TRY
                EXECUTE dbo.ChangeStudentFeeAssignmentAmount_Internal @UserId = @UserId, @StudentFeeAssignmentId = @CurrentAssignmentId, @NewAmount = @CurrentNewAmount, @EffectiveFrom = @NormalizedEffectiveFrom, @Reason = @Reason;
                SET @Succeeded = @Succeeded + 1;
            END TRY
            BEGIN CATCH

          SET @Failed = @Failed + 1;
                INSERT  INTO @Failures (StudentFeeAssignmentId, ErrorMessage)
                VALUES                (@CurrentAssignmentId, ERROR_MESSAGE());
            END CATCH
            SET @i = @i + 1;
        END
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'FEE_APPLY_CONFIG_TO_EXISTING', N'CampusId=' + CONVERT (NVARCHAR (20), @CampusId) + N' ClassId=' + CONVERT (NVARCHAR (20), @ClassId) + N' FeeTypeId=' + CONVERT (NVARCHAR (20), @FeeTypeId) + N' EffectiveFrom=' + CONVERT (NVARCHAR (20), @NormalizedEffectiveFrom) + N' Total=' + CONVERT (NVARCHAR (20), @Total) + N' Succeeded=' + CONVERT (NVARCHAR (20), @Succeeded) + N' Failed=' + CONVERT (NVARCHAR (20), @Failed) + N' Reason=' + @Reason);
    DECLARE @NewValues AS NVARCHAR (MAX) = (SELECT @CampusId AS CampusId,
                                                   @ClassId AS ClassId,
                                                   @FeeTypeId AS FeeTypeId,
                                                   @NormalizedEffectiveFrom AS EffectiveFrom,
                                                   @Reason AS Reason,
                                                   @Total AS TotalAssignments,
                                                   @Succeeded AS Succeeded,
                                                   @Failed AS Failed
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'StudentFeeAssignments', @RecordId = 0, @Action = N'UPDATE', @OldValues = NULL, @NewValues = @NewValues;
    SELECT @Total AS TotalAssignments,
           @Succeeded AS Succeeded,
           @Failed AS Failed,
           @NormalizedEffectiveFrom AS EffectiveFrom;

    SELECT StudentFeeAssignmentId,
           ErrorMessage
    FROM   @Failures;
DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
END

/* ------------------------------------------------------------
   2. Authoritative current charge balance.
      No adjustment table is consulted.
      Completed allocations are signed:
          + collection
          - refund
      Reversed payments contribute zero.
   ------------------------------------------------------------ */

CREATE   FUNCTION dbo.GetFeeChargeBalance
(
    @BillingChargeId BIGINT
)
RETURNS DECIMAL(12,2)
AS
BEGIN
    DECLARE
        @Net DECIMAL(12,2),
        @Paid DECIMAL(12,2);

    SELECT
        @Net = NetAmount
    FROM dbo.BillingCharges
    WHERE BillingChargeId = @BillingChargeId;

    SELECT
        @Paid = ISNULL(SUM(FPA.Amount), 0)
    FROM dbo.FeePaymentAllocations FPA
    INNER JOIN dbo.FeePayments FP
        ON FP.FeePaymentId = FPA.FeePaymentId
       AND FP.Status = N'Completed'
    WHERE FPA.BillingChargeId = @BillingChargeId;

    RETURN
        CASE
            WHEN ISNULL(@Net, 0) - ISNULL(@Paid, 0) < 0
                THEN 0
            ELSE ISNULL(@Net, 0) - ISNULL(@Paid, 0)
        END;
END;

CREATE   PROCEDURE dbo.WriteAuditLog
    @OperationId uniqueidentifier,@UserId int,@TableName nvarchar(128),@RecordId nvarchar(200),
    @Action nvarchar(100),@OldValues nvarchar(max),@NewValues nvarchar(max)
AS
BEGIN
    SET NOCOUNT ON;
    -- R
outine setup, school-profile/contact edits and family-list housekeeping
    -- do not need audit events. Financial, lifecycle, certificate and security
    -- operations remain protected.
    IF @TableName NOT IN
    (N'Users',N'UserRoles',N'Roles',N'RolePermissions',N'Students',N'Enrollments',N'PromotionBatches',N'SchoolProfile',
     N'StudentFeeAssignments',N'FeeConfigurations',N'BillingCharges',N'FeePayments',N'DailyCollectionClosings',
     N'DatabaseBackups',N'BackupHistory',N'LeaveCertificates',N'ProvisionalCertificates',N'CharacterCertificates',
     N'DateOfBirthCertificates',N'NoObjectionCertificates',N'RegularStudentCertificates',N'RegularLecturerCertificates',
     N'BankAccountOpeningCertificates',N'SportsCertificates') RETURN;
    IF NOT EXISTS(SELECT 1 FROM dbo.Users WHERE UserId=@UserId)
        THROW 50001,'The specified user does not exist.',1;
    IF NOT EXISTS(SELECT 1 FROM dbo.AuditOperations WHERE OperationId=@OperationId AND UserId=@UserId)
        THROW 50002,'Audit operation context was not found.',1;
    DECLARE @AuditAction nvarchar(30)=CASE UPPER(LTRIM(RTRIM(@Action)))
        WHEN N'CORRECTION_CREATE' THEN N'INSERT' WHEN N'CORRECTION' THEN N'UPDATE'
        WHEN N'STATUS_CORRECTION' THEN N'UPDATE' WHEN N'BULK_PROMOTION' THEN N'PROMOTE'
        WHEN N'STATUS_SYNC' THEN N'UPDATE' WHEN N'REMOVE_SIBLING' THEN N'DELETE'
        WHEN N'DEACTIVATE' THEN N'UPDATE' WHEN N'MIGRATION_BILLING_CLEANUP' THEN N'OTHER'
        ELSE UPPER(LTRIM(RTRIM(@Action))) END;
    IF @AuditAction NOT IN(N'OTHER',N'LOCK',N'PUBLISH',N'REJECT',N'APPROVE',N'REVERSAL',N'REFUND',N'PAYMENT',
        N'TRANSFER_SECTION',N'TRANSFER_CLASS',N'TRANSFER_CAMPUS',N'PROMOTE',N'LEAVE',N'RE-ADMIT',N'DELETE',N'UPDATE',N'INSERT')
        THROW 50004,'The audit action is not one of the permitted values.',1;
    IF (@OldValues IS NOT NULL AND ISJSON(@OldValues)<>1) OR (@NewValues IS NOT NULL AND ISJSON(@NewValues)<>1)
        THROW 59941,'Audit values must be valid JSON.',1;
    DECLARE @Old TA
BLE(Path nvarchar(4000),FieldName nvarchar(4000),Value nvarchar(max),JsonType int);
    DECLARE @New TABLE(Path nvarchar(4000),FieldName nvarchar(4000),Value nvarchar(max),JsonType int);
    INSERT @Old SELECT * FROM dbo.AuditValueLeaves(@OldValues);
    INSERT @New SELECT * FROM dbo.AuditValueLeaves(@NewValues);
    -- Some callers describe the same field as OldStatus / NewStatus.
    -- Pair those names before comparing so an unchanged status is skipped.
    IF @OldValues IS NOT NULL AND @NewValues IS NOT NULL
    BEGIN
        DECLARE @Names TABLE(OldName nvarchar(4000),NewName nvarchar(4000),FieldName nvarchar(4000));
        INSERT @Names SELECT DISTINCT O.FieldName,N.FieldName,SUBSTRING(O.FieldName,4,4000)
        FROM @Old O JOIN @New N ON N.FieldName=N'New'+SUBSTRING(O.FieldName,4,4000)
        WHERE LEFT(O.FieldName,3)=N'Old';
        UPDATE O SET Path=LEFT(O.Path,LEN(O.Path)-LEN(O.FieldName))+M.FieldName,FieldName=M.FieldName FROM @Old O JOIN @Names M ON M.OldName=O.FieldName;
        UPDATE N SET Path=LEFT(N.Path,LEN(N.Path)-LEN(N.FieldName))+M.FieldName,FieldName=M.FieldName FROM @New N JOIN @Names M ON M.NewName=N.FieldName;
    END;
    -- Rows identified only by generic metadata are deliberately omitted on
    -- creation/deletion. Store the event and its financial/lifecycle context.
    DECLARE @SummaryFields TABLE(Name nvarchar(128) PRIMARY KEY);
    INSERT @SummaryFields VALUES
      (N'AdmissionId'),(N'EnrollmentId'),(N'AcademicYearId'),(N'ClassSectionId'),(N'CampusId'),(N'ClassId'),(N'FeeTypeId'),
      (N'AdmissionNumber'),(N'Status'),(N'Username'),(N'RoleName'),(N'RoleId'),(N'PermissionId'),(N'MustChangePassword'),
      (N'Amount'),(N'PaymentAmount'),(N'TotalAmount'),(N'GrossAmount'),(N'DiscountAmount'),(N'NetAmount'),(N'Frequency'),
      (N'EffectiveFrom'),(N'EffectiveTo'),(N'CancelledAt'),(N'BillingMonth'),(N'BillingStartDate'),(N'UsesTransport'),
      (N'ReceiptNumber'),(N'FeePaymentId'),(N'ResultPaymentId'),(N'TransactionType'),(N'PaymentMethod
'),
      (N'CertificateType'),(N'LeaveDate'),(N'IssueDate'),(N'CertificateNumber'),(N'LeaveRecordId'),(N'LeaveCertificateIssueId'),
      (N'IsRetroactive'),(N'LeavingDate'),(N'WithdrawalDate'),(N'EnrollmentDate'),(N'DateOfAdmission'),
      (N'ClosingDate'),(N'Revision'),(N'SnapshotHash'),(N'ChargesCreated'),(N'RowsRequested'),(N'RowsNotPosted'),
      (N'BillingChargeId'),(N'StudentFeeAssignmentId'),(N'Reason'),(N'PasswordChanged'),(N'FeeProrationCutoffDay'),
      (N'CertificateDate'),(N'ExamType'),(N'ExamYear'),(N'RollNumber'),(N'MarksObtained'),(N'MarksOutOf'),(N'Grade'),(N'AdmissionDate'),(N'AdmissionCampusId'),
      (N'SubjectId'),(N'SubjectName'),(N'DisplayOrder');
    IF @AuditAction IN(N'INSERT',N'DELETE')
    BEGIN
        DELETE O FROM @Old O WHERE NOT EXISTS(SELECT 1 FROM @SummaryFields F WHERE F.Name=O.FieldName);
        DELETE N FROM @New N WHERE NOT EXISTS(SELECT 1 FROM @SummaryFields F WHERE F.Name=N.FieldName);
    END;
    -- Routine student demographic edits are excluded; lifecycle and admission
    -- number changes remain critical. Enrollment changes still record billing.
    IF @TableName=N'Students'
    BEGIN
        DELETE O FROM @Old O WHERE O.FieldName NOT IN(N'Status',N'OldStatus',N'NewStatus',N'AdmissionNumber',N'WithdrawalDate',N'LeavingDate',N'AdmissionDate',N'AdmissionCampusId',N'AdmissionId');
        DELETE N FROM @New N WHERE N.FieldName NOT IN(N'Status',N'OldStatus',N'NewStatus',N'AdmissionNumber',N'WithdrawalDate',N'LeavingDate',N'AdmissionDate',N'AdmissionCampusId',N'AdmissionId');
    END;
    IF @TableName=N'SchoolProfile'
    BEGIN
        DELETE FROM @Old WHERE FieldName<>N'FeeProrationCutoffDay';
        DELETE FROM @New WHERE FieldName<>N'FeeProrationCutoffDay';
        IF NOT EXISTS(SELECT 1 FROM @Old) AND NOT EXISTS(SELECT 1 FROM @New) RETURN;
    END;
    IF @TableName IN(N'FeeConfigurations',N'StudentFeeAssignments')
    BEGIN
        DELETE FROM @Old WHERE FieldName=N'Remarks';
        DELETE FROM @New WHERE FieldName=N
'Remarks';
    END;
    DECLARE @Changes TABLE(Path nvarchar(4000),OldValue nvarchar(max),OldType int,NewValue nvarchar(max),NewType int);
    INSERT @Changes
    SELECT COALESCE(O.Path,N.Path),O.Value,O.JsonType,N.Value,N.JsonType
    FROM @Old O FULL JOIN @New N ON O.Path COLLATE Latin1_General_100_BIN2=N.Path COLLATE Latin1_General_100_BIN2
    WHERE O.JsonType IS NULL OR N.JsonType IS NULL OR O.JsonType<>N.JsonType
       OR ISNULL(O.Value,N'') COLLATE Latin1_General_100_BIN2<>ISNULL(N.Value,N'') COLLATE Latin1_General_100_BIN2;
    IF NOT EXISTS(SELECT 1 FROM @Changes) AND @OldValues IS NOT NULL AND @NewValues IS NOT NULL RETURN;
    IF @TableName=N'Students' AND @AuditAction=N'UPDATE' AND NOT EXISTS(SELECT 1 FROM @Changes) RETURN;
    SELECT @OldValues=N'{'+STRING_AGG(CONVERT(nvarchar(max),N'"'+STRING_ESCAPE(Path,'json')+N'":'+
        CASE OldType WHEN 0 THEN N'null' WHEN 1 THEN N'"'+STRING_ESCAPE(OldValue,'json')+N'"' ELSE OldValue END),N',') WITHIN GROUP(ORDER BY Path)+N'}'
        FROM @Changes WHERE OldType IS NOT NULL;
    SELECT @NewValues=N'{'+STRING_AGG(CONVERT(nvarchar(max),N'"'+STRING_ESCAPE(Path,'json')+N'":'+
        CASE NewType WHEN 0 THEN N'null' WHEN 1 THEN N'"'+STRING_ESCAPE(NewValue,'json')+N'"' ELSE NewValue END),N',') WITHIN GROUP(ORDER BY Path)+N'}'
        FROM @Changes WHERE NewType IS NOT NULL;
    INSERT dbo.AuditLogs(OperationId,UserId,TableName,RecordId,Action,OldValues,NewValues)
        VALUES(@OperationId,@UserId,@TableName,@RecordId,@AuditAction,@OldValues,@NewValues);
END;

-- CreateBankAccountOpeningCertificate
CREATE   PROCEDURE dbo.CreateBankAccountOpeningCertificate
@UserId INT, @StaffId INT, @Designation NVARCHAR (100), @BankName NVARCHAR (100), @BranchName NVARCHAR (150), @MonthlyIncome DECIMAL (18, 2)=NULL, @Purpose NVARCHAR (200), @CertificateDate DATE
AS
BEGIN
    S
ET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Certificates.Create';
    IF @StaffId <= 0
        THROW 58800, 'A valid staff member is required.', 1;
    IF @Designation IS NULL
       OR LTRIM(RTRIM(@Designation)) = N''
        THROW 58801, 'Designation is required.', 1;
    IF @BankName IS NULL
       OR LTRIM(RTRIM(@BankName)) = N''
        THROW 58802, 'Bank name is required.', 1;
    IF @BranchName IS NULL
       OR LTRIM(RTRIM(@BranchName)) = N''
        THROW 58803, 'Branch name is required.', 1;
    IF @Purpose IS NULL
       OR LTRIM(RTRIM(@Purpose)) = N''
        THROW 58804, 'Purpose is required.', 1;
    IF @MonthlyIncome IS NOT NULL
       AND @MonthlyIncome < 0
        THROW 58805, 'Monthly income cannot be negative.', 1;
    IF @CertificateDate IS NULL
        THROW 58806, 'Certificate date is required.', 1;
    IF @CertificateDate > CONVERT (DATE, SYSDATETIME())
        THROW 58807, 'Certificate date cannot be in the future.', 1;
    DECLARE @StaffName AS NVARCHAR (150), @FatherName AS NVARCHAR (150), @Gender AS NVARCHAR (20), @CNIC AS NVARCHAR (20), @BankAccountOpeningCertificateId AS INT;
    BEGIN TRANSACTION;
    SELECT @StaffName = S.StaffName,
           @FatherName = S.FatherName,
           @Gender = S.Gender,
           @CNIC = S.CNIC
    FROM   dbo.Staff AS S WITH (UPDLOCK, HOLDLOCK)
    WHERE  S.StaffId = @StaffId;
    IF @StaffName IS NULL
        THROW 58808, 'The staff member was not found.', 1;
    INSERT  dbo.BankAccountOpeningCertificates (StaffId, StaffName, FatherName, Gender, CNIC, Designation, BankName, BranchName, MonthlyIncome, Purpose, CertificateDate, CreatedByUserId)
    VALUES                                    (@StaffId, @StaffName, @FatherName, @Gender, @CNIC, LTRIM(RTRIM(@Designation)), LTRIM(RTRIM(@BankName)), LTRIM(RTRIM(@BranchName)), NULLIF (@MonthlyIncome, 0), LTRIM(RTRIM(@Purpose)), @CertificateDate, @UserId
);
    SET @BankAccountOpeningCertificateId = CONVERT (INT, SCOPE_IDENTITY());
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    DECLARE @RecordId AS NVARCHAR (200) = CONVERT (NVARCHAR (200), @BankAccountOpeningCertificateId);
    DECLARE @NewValues AS NVARCHAR (MAX);
    SELECT @NewValues = (SELECT @BankAccountOpeningCertificateId AS BankAccountOpeningCertificateId,
                                @StaffId AS StaffId,
                                @StaffName AS StaffName,
                                @FatherName AS FatherName,
                                @Gender AS Gender,
                                @CNIC AS CNIC,
                                @Designation AS Designation,
                                @BankName AS BankName,
                                @BranchName AS BranchName,
                                @MonthlyIncome AS MonthlyIncome,
                                @Purpose AS Purpose,
                                @CertificateDate AS CertificateDate
                         FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'BANK_ACCOUNT_OPENING_CERTIFICATE', CONVERT (NVARCHAR (200), @StaffId));
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'BankAccountOpeningCertificates', @RecordId = @RecordId, @Action = N'INSERT', @OldValues = NULL, @NewValues = @NewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @BankAccountOpeningCertificateId AS BankAccountOpeningCertificateId,
           @StaffId AS StaffId;
END

/* --------------
-------------------------------------------------------------
   STEP 3 - dbo.RecordFailedLogin

   Read-then-write inside one transaction with UPDLOCK/HOLDLOCK, so two
   simultaneous failed attempts cannot both read the same count and lose one.
   --------------------------------------------------------------------------- */
CREATE   PROCEDURE dbo.RecordFailedLogin
(
    @TargetUserId      INT,
    @MaxFailedAttempts INT = 5,
    @LockoutMinutes    INT = 5
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* FIX 54 - FMSC sign-in throttle.
       No RequirePermission: this runs before anyone is signed in, exactly like
       dbo.GetUserForLogin. The parameter is @TargetUserId and NOT @UserId
       because DatabaseHelper rewrites any @UserId parameter to the signed-in
       user, who does not exist yet at this point. */

    IF @MaxFailedAttempts IS NULL OR @MaxFailedAttempts < 1
        SET @MaxFailedAttempts = 5;

    IF @LockoutMinutes IS NULL OR @LockoutMinutes < 1
        SET @LockoutMinutes = 5;

    BEGIN TRANSACTION;

    DECLARE @NewCount INT;

    SELECT @NewCount = FailedLoginCount + 1
    FROM dbo.Users
        WITH (UPDLOCK, HOLDLOCK)
    WHERE UserId = @TargetUserId;

    IF @NewCount IS NULL
    BEGIN
        /* The account disappeared between the sign-in lookup and here. Nothing
           to record; not an error worth failing the sign-in over. */
        ROLLBACK TRANSACTION;
        RETURN;
    END;

    IF @NewCount >= @MaxFailedAttempts
        UPDATE dbo.Users
        SET
            FailedLoginCount = 0,
            LockedUntil = DATEADD(MINUTE, @LockoutMinutes, SYSDATETIME())
        WHERE UserId = @TargetUserId;
    ELSE
        UPDATE dbo.Users
        SET FailedLoginCount = @NewCount
        WHERE UserId = @TargetUserId;

    COMMIT TRANSACTION;
END;

CREATE PROCEDURE dbo.GetFamilyMembershipSummary
    @UserId INT,
    @AdmissionIds dbo.AdmissionIdList READONLY
AS
BEGIN
    SET NOCOUNT ON;

    EXEC dbo.RequirePermission
        @UserId,
        N'Students.View';

    SELECT
        L.AdmissionId,
        FM.FamilyId,
        (
            SELECT COUNT(*)
            FROM dbo.FamilyMembers FM2
            WHERE FM2.FamilyId = FM.FamilyId
        ) AS FamilyMemberCount
    FROM @AdmissionIds L
    LEFT JOIN dbo.FamilyMembers FM
        ON FM.AdmissionId = L.AdmissionId;
END;

