    INSERT  dbo.Students (AdmissionNumber, AdmissionDate, AdmissionCampusId, Registra
tionNumber, StudentName, FatherName, DateOfBirth, Gender, BFormNumber, Religion, BloodGroup, ContactNumber, AlternateContactNumber, Address, PreviousSchool, PlaceOfBirth, FatherOccupation, Disability, Status, BiseEnrolmentNumber, CasteTribe)
    VALUES              (@AdmissionNumber, @AdmissionDate, @AdmissionCampusId, @RegistrationNumber, @StudentName, NULLIF (LTRIM(RTRIM(@FatherName)), N''), @DateOfBirth, NULLIF (LTRIM(RTRIM(@Gender)), N''), NULLIF (LTRIM(RTRIM(@BFormNumber)), N''), NULLIF (LTRIM(RTRIM(@Religion)), N''), NULLIF (LTRIM(RTRIM(@BloodGroup)), N''), NULLIF (LTRIM(RTRIM(@ContactNumber)), N''), NULLIF (LTRIM(RTRIM(@AlternateContactNumber)), N''), NULLIF (LTRIM(RTRIM(@Address)), N''), NULLIF (LTRIM(RTRIM(@PreviousSchool)), N''), NULLIF (LTRIM(RTRIM(@PlaceOfBirth)), N''), NULLIF (LTRIM(RTRIM(@FatherOccupation)), N''), @Disability, N'Active', NULLIF (LTRIM(RTRIM(@BiseEnrolmentNumber)), N''), NULLIF (LTRIM(RTRIM(@CasteTribe)), N''));
    DECLARE @AdmissionId AS INT;
    SET @AdmissionId = SCOPE_IDENTITY();
    INSERT  dbo.Enrollments (AdmissionId, AcademicYearId, ClassSectionId, EnrollmentDate, BillingStartDate, Status, UsesTransport, Remarks)
    VALUES                 (@AdmissionId, @AcademicYearId, @ClassSectionId, @AdmissionDate, @BillingStartDate, N'Active', @UsesTransport, N'Created by admission');
    DECLARE @EnrollmentId AS INT;
    SET @EnrollmentId = SCOPE_IDENTITY();
    INSERT dbo.StudentFeeAssignments (EnrollmentId, AdmissionId, FeeTypeId, Amount, DiscountAmount, Frequency, Remarks)
    SELECT @EnrollmentId,
           @AdmissionId,
           FC.FeeTypeId,
           FC.Amount,
           0,
           FC.Frequency,
           N'Created by admission'
    FROM   dbo.FeeConfigurations AS FC
           INNER JOIN
           dbo.FeeTypes AS FT
           ON FT.FeeTypeId = FC.FeeTypeId
    WHERE  FC.CampusId = @AdmissionCampusId
           AND FC.ClassId = @ClassId
           AND (FT.IsMandatory = 1

   OR (FT.IsTransportLinked = 1
                    AND @UsesTransport = 1)
                OR FC.FeeTypeId IN (SELECT FeeTypeId
                                    FROM   @SelectedFeeTypeIds));
    IF EXISTS (SELECT 1
               FROM   @AdmissionDiscounts AS D
                      LEFT OUTER JOIN
                      dbo.StudentFeeAssignments AS SFA
                      ON SFA.EnrollmentId = @EnrollmentId
                         AND SFA.FeeTypeId = D.FeeTypeId
               WHERE  SFA.StudentFeeAssignmentId IS NULL
                      OR D.DiscountAmount > SFA.Amount)
        THROW 51024, 'A fee discount is invalid or exceeds the assigned fee.', 1;
    UPDATE SFA
    SET    DiscountAmount = D.DiscountAmount,
           UpdatedAt      = SYSDATETIME()
    FROM   dbo.StudentFeeAssignments AS SFA
           INNER JOIN
           @AdmissionDiscounts AS D
           ON D.FeeTypeId = SFA.FeeTypeId
    WHERE  SFA.EnrollmentId = @EnrollmentId;
    EXECUTE dbo.PostEnrollmentOpeningCharges @EnrollmentId = @EnrollmentId;
    INSERT  dbo.EnrollmentHistory (EnrollmentId, AdmissionId, ActionType, ActionDate, OldClassSectionId, NewClassSectionId, OldStatus, NewStatus, Remarks, UserId)
    VALUES                       (@EnrollmentId, @AdmissionId, N'ADMISSION', @AdmissionDate, NULL, @ClassSectionId, NULL, N'Active', N'Initial enrollment created by admission', @UserId);
    INSERT  dbo.StudentStatusHistory (AdmissionId, OldStatus, NewStatus, Reason, EffectiveDate, Remarks, CreatedBy)
    VALUES                          (@AdmissionId, NULL, N'Active', N'Admission', @AdmissionDate, N'Initial student status', @UserId);
    DECLARE @OperationId AS UNIQUEIDENTIFIER;
    SET @OperationId = NEWID();
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'ADMISSION', CAST (@AdmissionId AS NVARCHAR (200)));
    DECLARE @AuditRecordId AS NV
ARCHAR (200);
    SET @AuditRecordId = CAST (@AdmissionId AS NVARCHAR (200));
    DECLARE @AuditValues AS NVARCHAR (MAX);
    SELECT @AuditValues = (SELECT @AdmissionId AS AdmissionId,
                                  @EnrollmentId AS EnrollmentId,
                                  @RegistrationNumber AS RegistrationNumber,
                                  @AdmissionDate AS AdmissionDate,
                                  @BillingStartDate AS BillingStartDate,
                                  @AdmissionCampusId AS AdmissionCampusId,
                                  @AcademicYearId AS AcademicYearId,
                                  @ClassSectionId AS ClassSectionId,
                                  N'Active' AS Status
                           FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'Students', @RecordId = @AuditRecordId, @Action = N'INSERT', @OldValues = NULL, @NewValues = @AuditValues;
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'Enrollments', @RecordId = @AuditRecordId, @Action = N'INSERT', @OldValues = NULL, @NewValues = @AuditValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @AdmissionId AS AdmissionId,
           @EnrollmentId AS EnrollmentId,
           @RegistrationNumber AS RegistrationNumber,
           @AdmissionNumber AS AdmissionNumber;
END

CREATE   PROCEDURE dbo.SaveCampusClassSections
    @UserId int, @CampusId int,
    @Assignments dbo.CampusClassSectionAssignmentType READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXEC dbo.RequirePermission @UserId, N'System.Setup';

  IF NOT EXISTS (SELECT 1 FROM dbo.Campuses WHERE CampusId = @CampusId)
        THROW 50102, 'Please select a valid campus.', 1;
    IF EXISTS (SELECT 1 FROM @Assignments A WHERE A.IsSelected = 1
        AND NOT EXISTS (SELECT 1 FROM dbo.Classes C WHERE C.ClassId = A.ClassId))
        THROW 50104, 'One or more selected classes are invalid.', 1;
    IF EXISTS (SELECT 1 FROM @Assignments A WHERE A.IsSelected = 1
        AND NOT EXISTS (SELECT 1 FROM dbo.Sections S WHERE S.SectionId = A.SectionId))
        THROW 50105, 'One or more selected sections are invalid.', 1;
    BEGIN TRY
        BEGIN TRANSACTION;
        DECLARE @PlacementLocks int;
        SELECT @PlacementLocks=COUNT(*) FROM dbo.CampusClassSections CCS WITH(UPDLOCK,HOLDLOCK)
        WHERE CCS.CampusId=@CampusId AND EXISTS(SELECT 1 FROM @Assignments A WHERE A.ClassId=CCS.ClassId AND A.SectionId=CCS.SectionId);
        IF EXISTS(SELECT 1 FROM dbo.CampusClassSections CCS
            JOIN dbo.Enrollments E WITH(UPDLOCK,HOLDLOCK) ON E.ClassSectionId=CCS.ClassSectionId AND E.Status=N'Active'
            WHERE CCS.CampusId=@CampusId AND CCS.IsActive=1
              AND EXISTS(SELECT 1 FROM @Assignments A WHERE A.ClassId=CCS.ClassId AND A.SectionId=CCS.SectionId)
              AND NOT EXISTS(SELECT 1 FROM @Assignments A WHERE A.ClassId=CCS.ClassId AND A.SectionId=CCS.SectionId AND A.IsSelected=1))
            THROW 50106, 'A class and section still has active students. Move those students before removing the assignment. Nothing was saved.', 1;

        MERGE dbo.CampusClassSections WITH (HOLDLOCK) AS Target
        USING (SELECT DISTINCT @CampusId AS CampusId, ClassId, SectionId
               FROM @Assignments WHERE IsSelected = 1) AS Source
        ON Target.CampusId = Source.CampusId AND Target.ClassId = Source.ClassId
            AND Target.SectionId = Source.SectionId
        WHEN MATCHED THEN UPDATE SET IsActive = 1, UpdatedAt = SYSDATETIME()
        WHEN NOT MATC
HED THEN INSERT (CampusId, ClassId, SectionId, IsActive)
            VALUES (Source.CampusId, Source.ClassId, Source.SectionId, 1);

        UPDATE CCS SET IsActive = 0, UpdatedAt = SYSDATETIME()
        FROM dbo.CampusClassSections CCS
        WHERE CCS.CampusId = @CampusId
            AND EXISTS (SELECT 1 FROM @Assignments A
                WHERE A.ClassId = CCS.ClassId AND A.SectionId = CCS.SectionId)
            AND NOT EXISTS (SELECT 1 FROM @Assignments A
                WHERE A.ClassId = CCS.ClassId AND A.SectionId = CCS.SectionId AND A.IsSelected = 1);
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END

/* ---------------------------------------------------------------------------
   5. Allocation on insert - one trigger per table.

      A trigger rather than an edit to each Create procedure, for three reasons:
      it runs inside the inserting statement's transaction (which is the
      precondition the allocator documents), it covers every insert path
      including any future one, and it means the nine large Create procedures
      are not rewritten at all. This project already uses a trigger for exactly
      this kind of cross-cutting rule (TR_Students_RegistrationNumberImmutable).

      The prefix comes from the row: the leave tables carry CertificateType, so
      School/College become SLC/CLC in one trigger; the two staff tables both
      use EMP, per the operator's decision.
   --------------------------------------------------------------------------- */

/* Leave certificates - SLC for School, CLC for College */
CREATE   TRIGGER dbo.TR_LeaveCertificates_CertificateNumber
ON dbo.LeaveCertificates
AFTER INSERT
AS
BEGIN

  SET NOCOUNT ON;

    DECLARE @Number NVARCHAR(24);
    DECLARE @LeaveRecordId INT, @IssueDate DATE, @Prefix NVARCHAR(8);

    DECLARE pending CURSOR LOCAL FAST_FORWARD FOR
        SELECT I.LeaveRecordId,
               I.LeaveDate,
               CASE WHEN I.CertificateType = N'College' THEN N'CLC' ELSE N'SLC' END
        FROM inserted AS I
        WHERE I.CertificateNumber IS NULL;

    OPEN pending;
    FETCH NEXT FROM pending INTO @LeaveRecordId, @IssueDate, @Prefix;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC dbo.GetNextCertificateNumber @Prefix, @IssueDate, @Number OUTPUT;

        UPDATE dbo.LeaveCertificates
        SET CertificateNumber = @Number
        WHERE LeaveRecordId = @LeaveRecordId;

        FETCH NEXT FROM pending INTO @LeaveRecordId, @IssueDate, @Prefix;
    END;

    CLOSE pending;
    DEALLOCATE pending;
END;

CREATE   TRIGGER dbo.GuardFeeAssignmentPeriods ON dbo.StudentFeeAssignments AFTER INSERT,UPDATE,DELETE AS
BEGIN
 SET NOCOUNT ON;
 IF EXISTS(SELECT 1 FROM inserted WHERE CancelledAt IS NULL AND EffectiveFrom>EffectiveTo)
  THROW 57104,'A fee period cannot end before it starts.',1;
 IF EXISTS(SELECT 1 FROM inserted I JOIN dbo.Enrollments E WITH(UPDLOCK,HOLDLOCK) ON E.EnrollmentId=I.EnrollmentId
   WHERE E.Status<>N'Active') OR EXISTS(SELECT 1 FROM deleted D JOIN dbo.Enrollments E WITH(UPDLOCK,HOLDLOCK) ON E.EnrollmentId=D.EnrollmentId WHERE E.Status<>N'Active')
  THROW 57105,'This enrollment is closed. Its fee assignments are preserved as history.',1;
 IF EXISTS(SELECT 1 FROM inserted I JOIN dbo.StudentFeeAssignments A WITH(UPDLOCK,HOLDLOCK) ON A.EnrollmentId=I.EnrollmentId AND A.FeeTypeId=I.FeeTypeId
   AND A.StudentFeeAssignmentId<>I.StudentFeeAssignmentId WHERE I.CancelledAt IS NULL AND A.CancelledAt IS NULL
   AND ISNULL(I.Effect
iveFrom,'19000101')<=ISNULL(A.EffectiveTo,'99991231')
   AND ISNULL(A.EffectiveFrom,'19000101')<=ISNULL(I.EffectiveTo,'99991231'))
  THROW 57106,'Fee periods overlap. Review the existing periods before applying this change.',1;
END;

