-- CorrectStudentStatus
CREATE   PROCEDURE [dbo].[CorrectStudentStatus]
@UserId INT, @AdmissionId INT, @NewStatus NVARCHAR (30), @NewWithdrawalDate DATE=NULL, @ClearWithdrawalDate BIT=0, @Reason NVARCHAR (500)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Students.Administer';
    IF @AdmissionId <= 0
        THROW 57001, 'A valid student is required.', 1;
    IF @NewStatus NOT IN (N'Active', N'Left')
        THROW 57002, 'Status must be Active or Left.', 1;
    IF NULLIF (LTRIM(RTRIM(@Reason)), N'') IS NULL
        THROW 57003, 'A reason is required for a manual correction.', 1;
    IF @ClearWithdrawalDate = 1
       AND @NewWithdrawalDate IS NOT NULL
        THROW 57004, 'Withdrawal date cannot both be cleared and set at the same time.', 1;
    BEGIN TRANSACTION;
    DECLARE @OldStatus AS NVARCHAR (30), @OldWithdrawalDate AS DATE;
    SELECT @OldStatus = Status,
           @OldWithdrawalDate = WithdrawalDate
    FROM   dbo.Students WITH (UPDLOCK, HOLDLOCK)
    WHER
E  AdmissionId = @AdmissionId;
    IF @OldStatus IS NULL
        BEGIN
            ROLLBACK;
            THROW 57005, 'The selected student was not found.', 1;
        END
    DECLARE @FinalWithdrawalDate AS DATE = CASE WHEN @ClearWithdrawalDate = 1 THEN NULL WHEN @NewWithdrawalDate IS NOT NULL THEN @NewWithdrawalDate ELSE @OldWithdrawalDate END;
    IF @FinalWithdrawalDate > CONVERT (DATE, SYSDATETIME())
        BEGIN
            ROLLBACK;
            THROW 57006, 'Withdrawal date cannot be in the future.', 1;
        END
    IF @OldStatus = @NewStatus
       AND ISNULL(@OldWithdrawalDate, '19000101') = ISNULL(@FinalWithdrawalDate, '19000101')
        BEGIN
            COMMIT TRANSACTION;
            SELECT @AdmissionId AS AdmissionId,
                   @OldStatus AS Status,
                   @OldWithdrawalDate AS WithdrawalDate,
                   CAST (0 AS BIT) AS Changed;
            RETURN;
        END
    IF @NewStatus = N'Active'
       AND @OldStatus = N'Left'
        BEGIN
            IF NOT EXISTS (SELECT 1
                           FROM   dbo.Enrollments WITH (UPDLOCK, HOLDLOCK)
                           WHERE  AdmissionId = @AdmissionId
                                  AND Status = N'Active')
                BEGIN
                    ROLLBACK;
                    THROW 57008, 'This student has no active enrollment. Use Re-Admit Student to bring them back into a class with a proper enrollment date, rather than correcting status directly.', 1;
                END
        END
    UPDATE dbo.Students
    SET    Status         = @NewStatus,
           WithdrawalDate = @FinalWithdrawalDate,
           UpdatedAt      = SYSDATETIME()
    WHERE  AdmissionId = @AdmissionId;
    IF @@ROWCOUNT <> 1
        BEGIN
            ROLLBACK;
            THROW 57007, 'The student status could not be updated.', 1;
        END
    DECLARE @ClosedEnrollmentId AS INT;

DECLARE @ClosedClassSectionId AS INT;
    DECLARE @EnrollmentLeavingDate AS DATE = ISNULL(@FinalWithdrawalDate, CONVERT (DATE, SYSDATETIME()));
    IF @NewStatus = N'Left'
        BEGIN
            SELECT   TOP (1) @ClosedEnrollmentId = E.EnrollmentId,
                             @ClosedClassSectionId = E.ClassSectionId
            FROM     dbo.Enrollments AS E WITH (UPDLOCK, HOLDLOCK)
            WHERE    E.AdmissionId = @AdmissionId
                     AND E.Status = N'Active'
            ORDER BY E.EnrollmentId DESC;
            IF @ClosedEnrollmentId IS NOT NULL
                BEGIN
                    DECLARE @MaxBilledMonth AS DATE = (SELECT MAX(BillingMonth)
                                                       FROM   dbo.BillingCharges
                                                       WHERE  EnrollmentId = @ClosedEnrollmentId
                                                              AND Status <> N'Cancelled');
                    IF @MaxBilledMonth IS NOT NULL
                       AND DATEFROMPARTS(YEAR(@EnrollmentLeavingDate), MONTH(@EnrollmentLeavingDate), 1) < @MaxBilledMonth
                        BEGIN
                            ROLLBACK;
                            THROW 57009, 'This student already has billing charges for a later month than the requested withdrawal date. Cancel/correct those charges first, or choose a withdrawal date in or after the last billed month.', 1;
                        END
                    UPDATE dbo.Enrollments
                    SET    Status      = N'Left',
                           LeavingDate = @EnrollmentLeavingDate,
                           Remarks     = @Reason,
                           UpdatedAt   = SYSDATETIME()
                    WHERE  EnrollmentId = @ClosedEnrollmentId
                           AND Status = N'Active';
                    IF @@ROWCOUNT = 1
                        BEGIN
                            INSERT  db
o.EnrollmentHistory (EnrollmentId, AdmissionId, ActionType, ActionDate, OldClassSectionId, NewClassSectionId, OldStatus, NewStatus, Remarks, UserId)
                            VALUES                       (@ClosedEnrollmentId, @AdmissionId, N'LEAVE', @EnrollmentLeavingDate, @ClosedClassSectionId, NULL, N'Active', N'Left', N'Closed automatically by Student Status Console correction. ' + @Reason, @UserId);
                        END
                END
        END
    IF @OldStatus <> @NewStatus
        BEGIN
            INSERT  dbo.StudentStatusHistory (AdmissionId, OldStatus, NewStatus, Reason, EffectiveDate, Remarks, CreatedBy)
            VALUES                          (@AdmissionId, @OldStatus, @NewStatus, N'Console correction', ISNULL(@FinalWithdrawalDate, CONVERT (DATE, SYSDATETIME())), @Reason, @UserId);
        END
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'STUDENT_STATUS_CORRECTION', CONVERT (NVARCHAR (200), @AdmissionId));
    DECLARE @CorrectionValues AS NVARCHAR (MAX) = (SELECT @AdmissionId AS AdmissionId,
                                                          @OldStatus AS OldStatus,
                                                          @NewStatus AS NewStatus,
                                                          @OldWithdrawalDate AS OldWithdrawalDate,
                                                          @FinalWithdrawalDate AS NewWithdrawalDate,
                                                          @ClosedEnrollmentId AS ClosedEnrollmentId,
                                                          @Reason AS Reason
                                                   FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'Students', @RecordId = @Admi
ssionId, @Action = N'STATUS_CORRECTION', @OldValues = NULL, @NewValues = @CorrectionValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @AdmissionId AS AdmissionId,
           @NewStatus AS Status,
           @FinalWithdrawalDate AS WithdrawalDate,
           CAST (1 AS BIT) AS Changed;
END

-- ReAdmitStudent
CREATE PROCEDURE dbo.ReAdmitStudent
@UserId INT, @AdmissionId INT, @CampusId INT, @AcademicYearId INT, @ClassSectionId INT, @EnrollmentDate DATE, @Reason NVARCHAR (500), @UsesTransport BIT, @MonthlyStartMonth date=NULL, @ChargeYearlyFees bit=NULL, @ReviewedRates nvarchar(max)=NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Students.Administer';
    IF @AdmissionId <= 0
        THROW 56510, 'A valid student is required.', 1;
    IF @CampusId <= 0
        THROW 56511, 'A valid campus is required.', 1;
    IF @AcademicYearId <= 0
        THROW 56512, 'A valid academic year is required.', 1;
    IF @ClassSectionId <= 0
        THROW 56513, 'A valid class section is required.', 1;
    IF @EnrollmentDate IS NULL
        THROW 56514, 'Enrollment date is required.', 1;
    IF @EnrollmentDate > CONVERT (DATE, SYSDATETIME())
        THROW 56515, 'Enrollment date cannot be in the future.', 1;

    IF @MonthlyStartMonth IS NULL OR @ChargeYearlyFees IS NULL
        THROW 57100, 'Choose the monthly start month and yearly-fee decision before readmission.',1;
    BEGIN TRANSACTION;
    DECLARE @OldStudentStatus AS NVARCHAR (30), @OldWithdrawalDate AS DATE, @OldEnrollmentId AS INT = NULL, @ClassId AS INT, @SectionCampusId AS INT, @MaxPriorLeavingDate AS DATE = NULL, @YearStartDate AS DATE, @YearEndDate AS DATE;

SELECT @OldStudentStatus = S.Status,
           @OldWithdrawalDate = S.WithdrawalDate
    FROM   dbo.Students AS S WITH (UPDLOCK, HOLDLOCK)
    WHERE  S.AdmissionId = @AdmissionId;
    IF @OldStudentStatus IS NULL
        THROW 56516, 'The student was not found.', 1;
    SELECT TOP (1) @OldEnrollmentId = E.EnrollmentId
    FROM   dbo.Enrollments AS E WITH (UPDLOCK, HOLDLOCK)
    WHERE  E.AdmissionId = @AdmissionId
           AND E.Status = N'Active';
    IF @OldEnrollmentId IS NOT NULL
        THROW 56517, 'The student already has an active enrollment.', 1;
    IF @OldStudentStatus = N'Active'
        THROW 56524, 'The student is already active.', 1;
    SELECT @MaxPriorLeavingDate = MAX(E2.LeavingDate)
    FROM   dbo.Enrollments AS E2
    WHERE  E2.AdmissionId = @AdmissionId
           AND E2.LeavingDate IS NOT NULL;
    IF @MaxPriorLeavingDate IS NOT NULL
       AND @EnrollmentDate <= @MaxPriorLeavingDate
        BEGIN
            ROLLBACK;
            THROW 56527, 'The re-admission enrollment date must be after the student''s most recent leaving date on file. Correct the prior enrollment''s leaving date first if this re-admission is genuinely meant to start on or before it.', 1;
        END
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.Campuses
                   WHERE  CampusId = @CampusId)
        THROW 56518, 'The selected campus is not active.', 1;
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.AcademicYears
                   WHERE  AcademicYearId = @AcademicYearId)
        THROW 56519, 'The selected academic year is not active.', 1;
    SELECT @YearStartDate = StartDate,
           @YearEndDate = EndDate
    FROM   dbo.AcademicYears
    WHERE  AcademicYearId = @AcademicYearId;
    IF @EnrollmentDate < @YearStartDate
       OR @EnrollmentDate > @YearEndDate
        BEGIN
            ROLLBACK;
            THROW 56528, 'The re-admission enrollment date
 must fall within the selected academic year''s date range.', 1;
        END
    SELECT @SectionCampusId = CCS.CampusId,
           @ClassId = CCS.ClassId
    FROM   dbo.CampusClassSections AS CCS
    WHERE  CCS.ClassSectionId = @ClassSectionId;
    IF @SectionCampusId IS NULL
        THROW 56521, 'The selected class section is invalid.', 1;
    IF @SectionCampusId <> @CampusId
        THROW 56522, 'The selected class section does not belong to the selected campus.', 1;
    DECLARE @MissingMandatoryFees AS NVARCHAR (1000);
    SELECT @MissingMandatoryFees = STRING_AGG(FT.FeeTypeName, N', ')
    FROM   dbo.FeeTypes AS FT
    WHERE  FT.IsMandatory = 1
           AND NOT EXISTS (SELECT 1
                           FROM   dbo.FeeConfigurations AS FC
                           WHERE  FC.CampusId = @CampusId
                                  AND FC.ClassId = @ClassId
                                  AND FC.FeeTypeId = FT.FeeTypeId);
    IF @MissingMandatoryFees IS NOT NULL
        BEGIN
            DECLARE @MandatoryFeeErrorMsg AS NVARCHAR (1100) = N'Required fee configuration is missing for the selected class: ' + @MissingMandatoryFees + N'.';
            ROLLBACK;
            THROW 56525, @MandatoryFeeErrorMsg, 1;
        END

    IF @ReviewedRates IS NULL OR ISJSON(@ReviewedRates)<>1
      THROW 57107,'Review the readmission rates before confirming.',1;
    DECLARE @Rates TABLE(FeeTypeId int,Amount decimal(12,2),Frequency nvarchar(40));
    INSERT @Rates SELECT FeeTypeId,Amount,Frequency FROM OPENJSON(@ReviewedRates)
       WITH(FeeTypeId int,Amount decimal(12,2),Frequency nvarchar(40));
    IF EXISTS(SELECT FC.FeeTypeId,FC.Amount,FC.Frequency FROM dbo.FeeConfigurations FC WITH(UPDLOCK,HOLDLOCK)
       JOIN dbo.FeeTypes FT ON FT.FeeTypeId=FC.FeeTypeId WHERE FC.CampusId=@CampusId AND FC.ClassId=@ClassId
       AND (@UsesTransport=1 OR FT.IsTransportLinked=0) EXCEPT SELECT * FROM @Rates)
       OR EXISTS(SELECT * FROM @
Rates EXCEPT SELECT FC.FeeTypeId,FC.Amount,FC.Frequency FROM dbo.FeeConfigurations FC
       JOIN dbo.FeeTypes FT ON FT.FeeTypeId=FC.FeeTypeId WHERE FC.CampusId=@CampusId AND FC.ClassId=@ClassId
       AND (@UsesTransport=1 OR FT.IsTransportLinked=0))
      THROW 57108,'Readmission rates changed. Review them again; nothing was saved.',1;
    DECLARE @CutoffDay AS INT;
    SELECT TOP (1) @CutoffDay = FeeProrationCutoffDay
    FROM   dbo.SchoolProfile;
    DECLARE @BillingStartDate AS DATE;
    SET @BillingStartDate = CASE WHEN @CutoffDay BETWEEN 1 AND 28
                                      AND DAY(@EnrollmentDate) >= @CutoffDay THEN DATEADD(MONTH, 1, DATEFROMPARTS(YEAR(@EnrollmentDate), MONTH(@EnrollmentDate), 1)) ELSE @EnrollmentDate END;

    IF DAY(@MonthlyStartMonth)<>1 OR @MonthlyStartMonth<DATEFROMPARTS(YEAR(@EnrollmentDate),MONTH(@EnrollmentDate),1)
       OR @MonthlyStartMonth>DATEFROMPARTS(YEAR(@YearEndDate),MONTH(@YearEndDate),1)
        THROW 57101,'Choose a monthly start month within the remaining academic year.',1;
    SET @BillingStartDate=@MonthlyStartMonth;
    INSERT  dbo.Enrollments (AdmissionId, AcademicYearId, ClassSectionId, EnrollmentDate, BillingStartDate, Status, Remarks, UsesTransport)
    VALUES                 (@AdmissionId, @AcademicYearId, @ClassSectionId, @EnrollmentDate, @BillingStartDate, N'Active', @Reason, @UsesTransport);
    DECLARE @EnrollmentId AS INT;
    SET @EnrollmentId = SCOPE_IDENTITY();
    INSERT dbo.StudentFeeAssignments (EnrollmentId, AdmissionId, FeeTypeId, Amount, DiscountAmount, Frequency, Remarks)
    SELECT @EnrollmentId,
           @AdmissionId,
           FC.FeeTypeId,
           FC.Amount,
           CASE WHEN FC.Frequency=N'Yearly' AND @ChargeYearlyFees=0 THEN FC.Amount ELSE 0 END,
           FC.Frequency,
           CASE WHEN FC.Frequency=N'Yearly' AND @ChargeYearlyFees=0 THEN N'Yearly fee explicitly waived at re-admission' ELSE N'Created by re-admission' END
    FROM   dbo.FeeC
onfigurations AS FC
           INNER JOIN
           dbo.FeeTypes AS FT
           ON FT.FeeTypeId = FC.FeeTypeId
    WHERE  FC.CampusId = @CampusId
           AND FC.ClassId = @ClassId
           AND (@UsesTransport = 1
                OR FT.IsTransportLinked = 0);
    EXECUTE dbo.PostEnrollmentOpeningCharges @EnrollmentId = @EnrollmentId;
    UPDATE dbo.Students
    SET    Status         = N'Active',
           WithdrawalDate = NULL,
           UpdatedAt      = SYSDATETIME()
    WHERE  AdmissionId = @AdmissionId;
    IF @@ROWCOUNT <> 1
        THROW 56523, 'The student status could not be updated.', 1;
    INSERT  dbo.EnrollmentHistory (EnrollmentId, AdmissionId, ActionType, ActionDate, OldClassSectionId, NewClassSectionId, OldStatus, NewStatus, Remarks, UserId)
    VALUES                       (@EnrollmentId, @AdmissionId, N'RE-ADMIT', @EnrollmentDate, NULL, @ClassSectionId, NULL, N'Active', @Reason, @UserId);
    INSERT  dbo.StudentStatusHistory (AdmissionId, OldStatus, NewStatus, Reason, EffectiveDate, Remarks, CreatedBy)
    VALUES                          (@AdmissionId, @OldStudentStatus, N'Active', N'Re-admission', @EnrollmentDate, @Reason, @UserId);
    DECLARE @OperationId AS UNIQUEIDENTIFIER;
    SET @OperationId = NEWID();
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'RE-ADMIT', CONVERT (NVARCHAR (200), @AdmissionId));
    DECLARE @EnrollmentNewValues AS NVARCHAR (MAX), @EnrollmentAuditRecordId AS NVARCHAR (200);
    SELECT @EnrollmentNewValues = (SELECT @AdmissionId AS AdmissionId,
                                          @EnrollmentId AS EnrollmentId,
                                          @CampusId AS CampusId,
                                          @AcademicYearId AS AcademicYearId,
                                          @ClassSectionId AS ClassSectionId,

        @EnrollmentDate AS EnrollmentDate,
                                          @BillingStartDate AS BillingStartDate,
                                          @UsesTransport AS UsesTransport, @ChargeYearlyFees AS ChargeYearlyFees,
                                          N'Active' AS Status,
                                          @Reason AS Remarks
                                   FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    SET @EnrollmentAuditRecordId = CONVERT (NVARCHAR (200), @EnrollmentId);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'Enrollments', @RecordId = @EnrollmentAuditRecordId, @Action = N'RE-ADMIT', @OldValues = NULL, @NewValues = @EnrollmentNewValues;
    DECLARE @StudentOldValues AS NVARCHAR (MAX), @StudentNewValues AS NVARCHAR (MAX), @StudentAuditRecordId AS NVARCHAR (200);
    SELECT @StudentOldValues = (SELECT @AdmissionId AS AdmissionId,
                                       @OldStudentStatus AS Status,
                                       @OldWithdrawalDate AS WithdrawalDate
                                FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    SELECT @StudentNewValues = (SELECT @AdmissionId AS AdmissionId,
                                       N'Active' AS Status,
                                       NULL AS WithdrawalDate
                                FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    SET @StudentAuditRecordId = CONVERT (NVARCHAR (200), @AdmissionId);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'Students', @RecordId = @StudentAuditRecordId, @Action = N'RE-ADMIT', @OldValues = @StudentOldValues, @NewValues = @StudentNewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @AdmissionId AS AdmissionId,

           @EnrollmentId AS EnrollmentId,
           @EnrollmentDate AS EnrollmentDate;
END

CREATE   TRIGGER dbo.TR_SportsCertificates_CertificateNumber
ON dbo.SportsCertificates
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Number NVARCHAR(24);
    DECLARE @RecordId INT, @IssueDate DATE;

    DECLARE pending CURSOR LOCAL FAST_FORWARD FOR
        SELECT SportsCertificateId, CertificateDate
        FROM inserted
        WHERE CertificateNumber IS NULL;

    OPEN pending;
    FETCH NEXT FROM pending INTO @RecordId, @IssueDate;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC dbo.GetNextCertificateNumber N'SPT', @IssueDate, @Number OUTPUT;

        UPDATE dbo.SportsCertificates
        SET CertificateNumber = @Number
        WHERE SportsCertificateId = @RecordId;

        FETCH NEXT FROM pending INTO @RecordId, @IssueDate;
    END;

    CLOSE pending;
    DEALLOCATE pending;
END;

CREATE   PROCEDURE dbo.CorrectEnrollmentStatus
@UserId INT, @EnrollmentId INT=NULL, @AdmissionId INT=NULL, @NewStatus NVARCHAR (30)=NULL, @NewEnrollmentDate DATE=NULL, @NewLeavingDate DATE=NULL, @ClearLeavingDate BIT=0, @NewClassSectionId INT=NULL, @AcademicYearId INT=NULL, @Reason NVARCHAR (500)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
        EXECUTE dbo.RequirePermission @UserId, N'Students.Administer';
        IF NULLIF (LTRIM(RTRIM(@Reason)), N'') IS NULL
            THROW 57101, 'A reason is required for a manual correction.', 1;
        IF @ClearLeavingDate = 1

       AND @NewLeavingDate IS NOT NULL
            THROW 57102, 'Leaving date cannot both be cleared and set at the same time.', 1;
        BEGIN TRANSACTION;
        IF @EnrollmentId IS NULL
           OR @EnrollmentId = 0
            BEGIN
                IF @AdmissionId IS NULL
                   OR @AdmissionId <= 0
                    BEGIN
                        ROLLBACK;
                        THROW 57103, 'A valid student is required to create an enrollment.', 1;
                    END
                DECLARE @PriorStudentStatus AS NVARCHAR (30);
                DECLARE @PriorStudentWithdrawalDate AS DATE;
                SELECT @PriorStudentStatus = Status,
                       @PriorStudentWithdrawalDate = WithdrawalDate
                FROM   dbo.Students WITH (UPDLOCK, HOLDLOCK)
                WHERE  AdmissionId = @AdmissionId;
                IF @PriorStudentStatus IS NULL
                    BEGIN
                        ROLLBACK;
                        THROW 57104, 'The selected student was not found.', 1;
                    END
                IF @AcademicYearId IS NULL
                   OR @AcademicYearId <= 0
                    BEGIN
                        ROLLBACK;
                        THROW 57105, 'A valid academic year is required.', 1;
                    END
                IF @NewClassSectionId IS NULL
                   OR @NewClassSectionId <= 0
                    BEGIN
                        ROLLBACK;
                        THROW 57106, 'A valid class section is required.', 1;
                    END
                IF @NewEnrollmentDate IS NULL
                    BEGIN
                        ROLLBACK;
                        THROW 57107, 'Enrollment date is required.', 1;
                    END
                SET @NewStatus = ISNULL(NULLIF (@NewStatus, N''), N'Active');
                IF @NewStatus NOT IN (N'Active', N'Promoted'
, N'Left')
                    BEGIN
                        ROLLBACK;
                        THROW 57108, 'Status must be Active, Promoted or Left.', 1;
                    END
                IF NOT EXISTS (SELECT 1
                               FROM   dbo.CampusClassSections
                               WHERE  ClassSectionId = @NewClassSectionId)
                    BEGIN
                        ROLLBACK;
                        THROW 57109, 'The selected class section is invalid.', 1;
                    END
                DECLARE @NewEffectiveLeavingDate AS DATE = CASE WHEN @ClearLeavingDate = 1 THEN NULL ELSE @NewLeavingDate END;
                IF @NewEffectiveLeavingDate IS NOT NULL
                   AND @NewEffectiveLeavingDate < @NewEnrollmentDate
                    BEGIN
                        ROLLBACK;
                        THROW 57110, 'Leaving date cannot be before the enrollment date.', 1;
                    END
                IF @NewStatus = N'Left'
                   AND @NewEffectiveLeavingDate IS NULL
                    BEGIN
                        ROLLBACK;
                        THROW 57117, 'A leaving date is required when creating a Left enrollment record.', 1;
                    END
                IF @NewStatus = N'Promoted'
                   AND NOT EXISTS (SELECT 1
                                   FROM   dbo.Enrollments WITH (UPDLOCK, HOLDLOCK)
                                   WHERE  AdmissionId = @AdmissionId
                                          AND Status = N'Active')
                    BEGIN
                        ROLLBACK;
                        THROW 57118, 'Marking a new enrollment Promoted requires an existing Active enrollment for this student. Create/select the destination enrollment first, or use the Promotion function.', 1;
                    END
                IF @NewStatus = N'Active'
                   AND EXISTS (SELECT 1\
r
                               FROM   dbo.Enrollments WITH (UPDLOCK, HOLDLOCK)
                               WHERE  AdmissionId = @AdmissionId
                                      AND Status = N'Active')
                    BEGIN
                        ROLLBACK;
                        THROW 57216, 'An Active enrollment already exists for this student. Select and correct the existing enrollment instead.', 1;
                    END
                INSERT  dbo.Enrollments (AdmissionId, AcademicYearId, ClassSectionId, EnrollmentDate, LeavingDate, Status, Remarks)
                VALUES                 (@AdmissionId, @AcademicYearId, @NewClassSectionId, @NewEnrollmentDate, @NewEffectiveLeavingDate, @NewStatus, @Reason);
                SET @EnrollmentId = CONVERT (INT, SCOPE_IDENTITY());
                INSERT  dbo.EnrollmentHistory (EnrollmentId, AdmissionId, ActionType, ActionDate, OldClassSectionId, NewClassSectionId, OldStatus, NewStatus, Remarks, UserId)
                VALUES                       (@EnrollmentId, @AdmissionId, N'CORRECTION_CREATE', @NewEnrollmentDate, NULL, @NewClassSectionId, NULL, @NewStatus, @Reason, @UserId);
                DECLARE @StudentStatusSynced AS BIT = 0;
                IF @NewStatus = N'Active'
                   AND @PriorStudentStatus <> N'Active'
                    BEGIN
                        UPDATE dbo.Students
                        SET    Status         = N'Active',
                               WithdrawalDate = NULL,
                               UpdatedAt      = SYSDATETIME()
                        WHERE  AdmissionId = @AdmissionId;
                        INSERT  dbo.StudentStatusHistory (AdmissionId, OldStatus, NewStatus, Reason, EffectiveDate, Remarks, CreatedBy)
                        VALUES                          (@AdmissionId, @PriorStudentStatus, N'Active', N'Synchronized by enrollment correction (create).', @NewEnrollmentDate, @Reason, @UserId);

      SET @StudentStatusSynced = 1;
                    END
                DECLARE @CreateOperationId AS UNIQUEIDENTIFIER = NEWID();
                INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
                VALUES                     (@CreateOperationId, @UserId, N'ENROLLMENT_CORRECTION_CREATE', CONVERT (NVARCHAR (200), @AdmissionId));
                DECLARE @CreateAuditValues nvarchar(max)=(SELECT @EnrollmentId EnrollmentId,@AdmissionId AdmissionId,
                    @AcademicYearId AcademicYearId,@NewClassSectionId ClassSectionId,@NewEnrollmentDate EnrollmentDate,
                    @NewEffectiveLeavingDate LeavingDate,@NewStatus Status,@Reason Reason
                    FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES);
                EXECUTE dbo.WriteAuditLog @OperationId = @CreateOperationId, @UserId = @UserId, @TableName = N'Enrollments', @RecordId = @EnrollmentId, @Action = N'CORRECTION_CREATE', @OldValues = NULL, @NewValues = @CreateAuditValues;
                IF @StudentStatusSynced = 1
                    BEGIN
                        DECLARE @CreateSyncValues AS NVARCHAR (MAX) = (SELECT @AdmissionId AS AdmissionId,
                                                                              @PriorStudentStatus AS OldStatus,
                                                                              N'Active' AS NewStatus,
                                                                              @EnrollmentId AS EnrollmentId
                                                                       FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
                        EXECUTE dbo.WriteAuditLog @OperationId = @CreateOperationId, @UserId = @UserId, @TableName = N'Students', @RecordId = @AdmissionId, @Action = N'STATUS_SYNC', @OldValues = NULL, @NewValues = @CreateSyncValues;
                    END
                DELETE dbo.AuditOperations WHERE OperationId=@Cre
ateOperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@CreateOperationId);
COMMIT TRANSACTION;
                SELECT @EnrollmentId AS EnrollmentId,
                       @AdmissionId AS AdmissionId,
                       @NewStatus AS Status,
                       CAST (1 AS BIT) AS Changed;
                RETURN;
            END
        DECLARE @OldAdmissionId AS INT, @OldStatus AS NVARCHAR (30), @OldEnrollmentDate AS DATE, @OldLeavingDate AS DATE, @OldClassSectionId AS INT;
        SELECT @OldAdmissionId = AdmissionId,
               @OldStatus = Status,
               @OldEnrollmentDate = EnrollmentDate,
               @OldLeavingDate = LeavingDate,
               @OldClassSectionId = ClassSectionId
        FROM   dbo.Enrollments WITH (UPDLOCK, HOLDLOCK)
        WHERE  EnrollmentId = @EnrollmentId;
        IF @OldAdmissionId IS NULL
            BEGIN
                ROLLBACK;
                THROW 57111, 'The selected enrollment was not found.', 1;
            END
        DECLARE @EditPriorStudentStatus AS NVARCHAR (30);
        DECLARE @EditPriorStudentWithdrawalDate AS DATE;
        SELECT @EditPriorStudentStatus = Status,
               @EditPriorStudentWithdrawalDate = WithdrawalDate
        FROM   dbo.Students WITH (UPDLOCK, HOLDLOCK)
        WHERE  AdmissionId = @OldAdmissionId;
        IF @EditPriorStudentStatus IS NULL
            BEGIN
                ROLLBACK;
                THROW 57119, 'The student record for this enrollment was not found.', 1;
            END
        DECLARE @FinalStatus AS NVARCHAR (30) = ISNULL(NULLIF (@NewStatus, N''), @OldStatus);
        IF @FinalStatus NOT IN (N'Active', N'Promoted', N'Left')
            BEGIN
                ROLLBACK;
                THROW 57112, 'Status must be Active, Promoted or Left.', 1;
            END
        DECLARE @FinalEnrollmentDate AS DATE = ISNULL(@NewEnrollmentDate, @OldEnrollmentDate);

        DECLARE @FinalLeavingDate AS DATE = CASE WHEN @ClearLeavingDate = 1 THEN NULL WHEN @NewLeavingDate IS NOT NULL THEN @NewLeavingDate ELSE @OldLeavingDate END;
        DECLARE @FinalClassSectionId AS INT = ISNULL(@NewClassSectionId, @OldClassSectionId);
        IF @FinalLeavingDate IS NOT NULL
           AND @FinalLeavingDate < @FinalEnrollmentDate
            BEGIN
                ROLLBACK;
                THROW 57113, 'Leaving date cannot be before the enrollment date.', 1;
            END
        IF @FinalClassSectionId <> @OldClassSectionId
           AND NOT EXISTS (SELECT 1
                           FROM   dbo.CampusClassSections
                           WHERE  ClassSectionId = @FinalClassSectionId)
            BEGIN
                ROLLBACK;
                THROW 57114, 'The selected class section is invalid.', 1;
            END
        IF @FinalStatus = @OldStatus
           AND @FinalEnrollmentDate = @OldEnrollmentDate
           AND ISNULL(@FinalLeavingDate, '19000101') = ISNULL(@OldLeavingDate, '19000101')
           AND @FinalClassSectionId = @OldClassSectionId
            BEGIN
                DELETE dbo.AuditOperations WHERE OperationId=@CreateOperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@CreateOperationId);
COMMIT TRANSACTION;
                SELECT @EnrollmentId AS EnrollmentId,
                       @OldAdmissionId AS AdmissionId,
                       @OldStatus AS Status,
                       CAST (0 AS BIT) AS Changed;
                RETURN;
            END
        IF @FinalEnrollmentDate <> @OldEnrollmentDate
           AND (EXISTS (SELECT 1
                        FROM   dbo.BillingCharges
                        WHERE  EnrollmentId = @EnrollmentId)
                OR EXISTS (SELECT 1
                           FROM   dbo.FeePayments
                           WHERE  EnrollmentId = @EnrollmentId)
                OR EXISTS (SEL
ECT 1
                           FROM   dbo.EnrollmentHistory
                           WHERE  EnrollmentId = @EnrollmentId))
            BEGIN
                ROLLBACK;
                THROW 57116, 'This enrollment already has billing, payment or status history, so its enrollment (start) date cannot be changed by an ordinary correction. Correct the dependent records first, or create a new enrollment with the correct start date.', 1;
            END
        IF @FinalStatus = N'Left'
           AND @FinalLeavingDate IS NULL
            BEGIN
                ROLLBACK;
                THROW 57117, 'A leaving date is required when setting an enrollment to Left.', 1;
            END
        IF @FinalStatus = N'Promoted'
           AND @OldStatus <> N'Promoted'
           AND NOT EXISTS (SELECT 1
                           FROM   dbo.Enrollments WITH (UPDLOCK, HOLDLOCK)
                           WHERE  AdmissionId = @OldAdmissionId
                                  AND Status = N'Active'
                                  AND EnrollmentId <> @EnrollmentId)
            BEGIN
                ROLLBACK;
                THROW 57118, 'Marking this enrollment Promoted requires an existing Active enrollment for this student. Create/select the destination enrollment first, or use the Promotion function.', 1;
            END
        IF @FinalLeavingDate IS NOT NULL
           AND (@OldLeavingDate IS NULL
                OR @FinalLeavingDate <> @OldLeavingDate)
            BEGIN
                DECLARE @MaxBilledMonth AS DATE = (SELECT MAX(BillingMonth)
                                                   FROM   dbo.BillingCharges
                                                   WHERE  EnrollmentId = @EnrollmentId
                                                          AND Status <> N'Cancelled');
                IF @MaxBilledMonth IS NOT NULL
                   AND DATEFROMPARTS(YEAR(@FinalLeavingDate), MONTH(@Fi
nalLeavingDate), 1) < @MaxBilledMonth
                    BEGIN
                        ROLLBACK;
                        THROW 57120, 'This enrollment already has billing charges for a later month than the requested leaving date. Cancel/correct those charges first, or choose a leaving date in or after the last billed month.', 1;
                    END
            END
        IF @FinalStatus = N'Active'
           AND EXISTS (SELECT 1
                       FROM   dbo.Enrollments WITH (UPDLOCK, HOLDLOCK)
                       WHERE  AdmissionId = @OldAdmissionId
                              AND Status = N'Active'
                              AND EnrollmentId <> @EnrollmentId)
            BEGIN
                ROLLBACK;
                THROW 57216, 'An Active enrollment already exists for this student. Select and correct the existing enrollment instead.', 1;
            END
        UPDATE dbo.Enrollments
        SET    Status         = @FinalStatus,
               EnrollmentDate = @FinalEnrollmentDate,
               LeavingDate    = @FinalLeavingDate,
               ClassSectionId = @FinalClassSectionId,
               UpdatedAt      = SYSDATETIME(),
               Remarks        = COALESCE (NULLIF (@Reason, N''), Remarks)
        WHERE  EnrollmentId = @EnrollmentId;
        IF @@ROWCOUNT <> 1
            BEGIN
                ROLLBACK;
                THROW 57115, 'The enrollment could not be updated.', 1;
            END
        INSERT  dbo.EnrollmentHistory (EnrollmentId, AdmissionId, ActionType, ActionDate, OldClassSectionId, NewClassSectionId, OldStatus, NewStatus, Remarks, UserId)
        VALUES                       (@EnrollmentId, @OldAdmissionId, N'CORRECTION', CONVERT (DATE, SYSDATETIME()), @OldClassSectionId, @FinalClassSectionId, @OldStatus, @FinalStatus, @Reason, @UserId);
        DECLARE @EditStudentStatusSynced AS BIT = 0;
        DECLARE @NewStudentStatus AS NVARCHAR (30) = @EditPrio
rStudentStatus;
        DECLARE @NewStudentWithdrawalDate AS DATE = @EditPriorStudentWithdrawalDate;
        IF @FinalStatus = N'Active'
           AND @EditPriorStudentStatus <> N'Active'
            BEGIN
                SET @NewStudentStatus = N'Active';
                SET @NewStudentWithdrawalDate = NULL;
                SET @EditStudentStatusSynced = 1;
            END
        ELSE
            IF @OldStatus = N'Active'
               AND @FinalStatus = N'Left'
                BEGIN
                    SET @NewStudentStatus = N'Left';
                    SET @NewStudentWithdrawalDate = @FinalLeavingDate;
                    SET @EditStudentStatusSynced = 1;
                END
        IF @EditStudentStatusSynced = 1
            BEGIN
                UPDATE dbo.Students
                SET    Status         = @NewStudentStatus,
                       WithdrawalDate = @NewStudentWithdrawalDate,
                       UpdatedAt      = SYSDATETIME()
                WHERE  AdmissionId = @OldAdmissionId;
                INSERT  dbo.StudentStatusHistory (AdmissionId, OldStatus, NewStatus, Reason, EffectiveDate, Remarks, CreatedBy)
                VALUES                          (@OldAdmissionId, @EditPriorStudentStatus, @NewStudentStatus, N'Synchronized by enrollment correction.', ISNULL(@NewStudentWithdrawalDate, CONVERT (DATE, SYSDATETIME())), @Reason, @UserId);
            END
        DECLARE @EditOperationId AS UNIQUEIDENTIFIER = NEWID();
        INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
        VALUES                     (@EditOperationId, @UserId, N'ENROLLMENT_CORRECTION', CONVERT (NVARCHAR (200), @OldAdmissionId));
        DECLARE @EditValues AS NVARCHAR (MAX) = (SELECT @EnrollmentId AS EnrollmentId,
                                                        @OldStatus AS OldStatus,
                                                        @FinalStatus AS NewStatus
,
                                                        @OldEnrollmentDate AS OldEnrollmentDate,
                                                        @FinalEnrollmentDate AS NewEnrollmentDate,
                                                        @OldLeavingDate AS OldLeavingDate,
                                                        @FinalLeavingDate AS NewLeavingDate,
                                                        @OldClassSectionId AS OldClassSectionId,
                                                        @FinalClassSectionId AS NewClassSectionId,
                                                        @Reason AS Reason
                                                 FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
        EXECUTE dbo.WriteAuditLog @OperationId = @EditOperationId, @UserId = @UserId, @TableName = N'Enrollments', @RecordId = @EnrollmentId, @Action = N'CORRECTION', @OldValues = NULL, @NewValues = @EditValues;
        IF @EditStudentStatusSynced = 1
            BEGIN
                DECLARE @EditSyncValues AS NVARCHAR (MAX) = (SELECT @OldAdmissionId AS AdmissionId,
                                                                    @EditPriorStudentStatus AS OldStatus,
                                                                    @NewStudentStatus AS NewStatus,
                                                                    @EditPriorStudentWithdrawalDate AS OldWithdrawalDate,
                                                                    @NewStudentWithdrawalDate AS NewWithdrawalDate,
                                                                    @EnrollmentId AS EnrollmentId
                                                             FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
                EXECUTE dbo.WriteAuditLog @OperationId = @EditOperationId, @UserId = @UserId, @TableName = N'Students', @RecordId = @OldAdmissionId, @Action = N'STATUS_SYNC', @
OldValues = NULL, @NewValues = @EditSyncValues;
            END
        DELETE dbo.AuditOperations WHERE OperationId=@CreateOperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@CreateOperationId);
DELETE dbo.AuditOperations WHERE OperationId=@EditOperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@EditOperationId);
COMMIT TRANSACTION;
        SELECT @EnrollmentId AS EnrollmentId,
               @OldAdmissionId AS AdmissionId,
               @FinalStatus AS Status,
               CAST (1 AS BIT) AS Changed;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK;
        THROW;
    END CATCH
END

/* The two staff certificates share the EMP series, per the operator's decision. */
CREATE   TRIGGER dbo.TR_RegularLecturerCertificates_CertificateNumber
ON dbo.RegularLecturerCertificates
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Number NVARCHAR(24);
    DECLARE @RecordId INT, @IssueDate DATE;

    DECLARE pending CURSOR LOCAL FAST_FORWARD FOR
        SELECT RegularLecturerCertificateId, CertificateDate
        FROM inserted
        WHERE CertificateNumber IS NULL;

    OPEN pending;
    FETCH NEXT FROM pending INTO @RecordId, @IssueDate;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC dbo.GetNextCertificateNumber N'EMP', @IssueDate, @Number OUTPUT;

        UPDATE dbo.RegularLecturerCertificates
        SET CertificateNumber = @Number
        WHERE RegularLecturerCertificateId = @RecordId;

        FETCH NEXT FROM pending INTO @RecordId, @IssueDate;
    END;

    CLOSE pending;
    DEALLOCATE pending;
END;

CREATE   PROCEDURE dbo.GetBillingAndDiscountsReport
    @UserId int,
    @View nvarchar(30),
    @GroupBy nvarchar(30) = N'Month',
    @FromDate date = NULL,
    @ToDate date = NULL,
    @CampusId int = 0,
    @ClassId int = 0,
    @SectionId int = 0
AS
BEGIN
    SET NOCOUNT ON;
    EXEC dbo.RequirePermission @UserId, N'Reports.View';

    IF @View NOT IN (N'Billing Summary', N'Billing Detail', N'Discount Detail')
        THROW 59904, 'The billing report view is not supported.', 1;
    IF @View = N'Billing Summary' AND @GroupBy NOT IN
       (N'Day', N'Week', N'Month', N'Class', N'Campus', N'Fee Type')
        THROW 59905, 'The billing report grouping is not supported.', 1;
    IF @FromDate IS NOT NULL AND @ToDate IS NOT NULL AND @FromDate > @ToDate
        THROW 59906, 'The billing report date range is invalid.', 1;

    SELECT BC.BillingCharge
Id, BC.ChargeDate, BC.BillingMonth, S.RegistrationNumber, S.AdmissionNumber, S.StudentName,
           CAMP.CampusName, C.ClassName, SEC.SectionName, FT.FeeTypeName,
           BC.GrossAmount, BC.DiscountAmount, BC.NetAmount
    INTO #Billing
    FROM dbo.BillingCharges BC
    JOIN dbo.Students S ON S.AdmissionId = BC.AdmissionId
    JOIN dbo.Enrollments E ON E.EnrollmentId = BC.EnrollmentId
    JOIN dbo.CampusClassSections CCS ON CCS.ClassSectionId = E.ClassSectionId
    JOIN dbo.Campuses CAMP ON CAMP.CampusId = CCS.CampusId
    JOIN dbo.Classes C ON C.ClassId = CCS.ClassId
    JOIN dbo.Sections SEC ON SEC.SectionId = CCS.SectionId
    JOIN dbo.FeeTypes FT ON FT.FeeTypeId = BC.FeeTypeId
    WHERE BC.Status <> N'Cancelled' AND (@FromDate IS NULL OR BC.ChargeDate >= @FromDate) AND (@ToDate IS NULL OR BC.ChargeDate <= @ToDate)
      AND (@CampusId = 0 OR CCS.CampusId = @CampusId)
      AND (@ClassId = 0 OR CCS.ClassId = @ClassId)
      AND (@SectionId = 0 OR CCS.SectionId = @SectionId);

    IF @View = N'Billing Detail'
    BEGIN
        SELECT AdmissionNumber [Admission Number], StudentName [Student], ClassName [Class], FeeTypeName [Fee Type],
               BillingMonth [Billing Period], ChargeDate [Charge Date], GrossAmount [Gross Amount],
               DiscountAmount [Discount], NetAmount [Net Charge]
        FROM #Billing ORDER BY ChargeDate, StudentName, FeeTypeName;
        SELECT COALESCE(SUM(GrossAmount), 0) [Gross Billed], COALESCE(SUM(DiscountAmount), 0) Discounts,
               COALESCE(SUM(NetAmount), 0) [Net Billed] FROM #Billing;
        RETURN;
    END;

    IF @View = N'Discount Detail'
    BEGIN
        SELECT AdmissionNumber [Admission Number], StudentName [Student], ClassName [Class], FeeTypeName [Fee Type],
               BillingMonth [Billing Period], ChargeDate [Charge Date], GrossAmount [Gross Amount],
               DiscountAmount [Applied Discount], NetAmount [Net Charge]

     FROM #Billing WHERE DiscountAmount > 0 ORDER BY ChargeDate, StudentName, FeeTypeName;
        SELECT COALESCE(SUM(GrossAmount), 0) [Gross Billed], COALESCE(SUM(DiscountAmount), 0) Discounts,
               COALESCE(SUM(NetAmount), 0) [Net Billed]
        FROM #Billing WHERE DiscountAmount > 0;
        RETURN;
    END;

    SELECT CASE @GroupBy
               WHEN N'Day' THEN CONVERT(char(10), ChargeDate, 23)
               WHEN N'Week' THEN CONCAT(CONVERT(char(10), DATEADD(day, -(DATEDIFF(day, 0, ChargeDate) % 7), ChargeDate), 23), N' week')
               WHEN N'Month' THEN CONVERT(char(7), ChargeDate, 126)
               WHEN N'Fee Type' THEN FeeTypeName
               WHEN N'Class' THEN ClassName
               WHEN N'Campus' THEN CampusName END [Group],
           COUNT(*) [Charges], COALESCE(SUM(GrossAmount), 0) [Gross Charges],
           COALESCE(SUM(DiscountAmount), 0) [Discounts Applied], COALESCE(SUM(NetAmount), 0) [Net Charges]
    FROM #Billing
    GROUP BY CASE @GroupBy
               WHEN N'Day' THEN CONVERT(char(10), ChargeDate, 23)
               WHEN N'Week' THEN CONCAT(CONVERT(char(10), DATEADD(day, -(DATEDIFF(day, 0, ChargeDate) % 7), ChargeDate), 23), N' week')
               WHEN N'Month' THEN CONVERT(char(7), ChargeDate, 126)
               WHEN N'Fee Type' THEN FeeTypeName
               WHEN N'Class' THEN ClassName
               WHEN N'Campus' THEN CampusName END
    ORDER BY [Group];
    SELECT COALESCE(SUM(GrossAmount), 0) [Gross Billed], COALESCE(SUM(DiscountAmount), 0) Discounts,
           COALESCE(SUM(NetAmount), 0) [Net Billed] FROM #Billing;
END;


