-- SetEnrollmentBillingStartDate
CREATE   PROCEDURE dbo.SetEnrollmentBillingStartDate
@UserId INT, @EnrollmentId INT, @BillingStartDate DATE, @Reason NVARCHAR (500)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Fees.Adjust';
    IF @Billing
StartDate IS NULL
        THROW 58001, 'A billing start date is required.', 1;
    IF NULLIF (LTRIM(RTRIM(@Reason)), N'') IS NULL
        THROW 58002, 'A reason is required for this change.', 1;
    BEGIN TRANSACTION;
    DECLARE @AdmissionId AS INT, @EnrollmentDate AS DATE, @OldBillingStartDate AS DATE, @Status AS NVARCHAR (30);
    SELECT @AdmissionId = E.AdmissionId,
           @EnrollmentDate = E.EnrollmentDate,
           @OldBillingStartDate = E.BillingStartDate,
           @Status = E.Status
    FROM   dbo.Enrollments AS E WITH (UPDLOCK, HOLDLOCK)
    WHERE  E.EnrollmentId = @EnrollmentId;
    IF @AdmissionId IS NULL
        BEGIN
            ROLLBACK;
            THROW 58003, 'The selected enrollment does not exist.', 1;
        END
    IF @BillingStartDate < @EnrollmentDate
        BEGIN
            ROLLBACK;
            THROW 58004, 'Billing start date cannot be earlier than the enrollment date.', 1;
        END
    UPDATE dbo.Enrollments
    SET    BillingStartDate = @BillingStartDate,
           UpdatedAt        = SYSDATETIME()
    WHERE  EnrollmentId = @EnrollmentId;
    DECLARE @OperationId AS UNIQUEIDENTIFIER;
    SET @OperationId = NEWID();
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'ENROLLMENT_BILLING_START_DATE_CHANGE', CONVERT (NVARCHAR (200), @EnrollmentId));
    DECLARE @OldValues AS NVARCHAR (MAX);
    SELECT @OldValues = (SELECT @EnrollmentId AS EnrollmentId,
                                @AdmissionId AS AdmissionId,
                                @OldBillingStartDate AS BillingStartDate
                         FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    DECLARE @NewValues AS NVARCHAR (MAX);
    SELECT @NewValues = (SELECT @EnrollmentId AS EnrollmentId,
                                @AdmissionId AS AdmissionId,

     @BillingStartDate AS BillingStartDate,
                                @Reason AS Reason
                         FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    DECLARE @AuditRecordId AS NVARCHAR (200);
    SET @AuditRecordId = CONVERT (NVARCHAR (200), @EnrollmentId);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'Enrollments', @RecordId = @AuditRecordId, @Action = N'UPDATE', @OldValues = @OldValues, @NewValues = @NewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @EnrollmentId AS EnrollmentId,
           @AdmissionId AS AdmissionId,
           @OldBillingStartDate AS OldBillingStartDate,
           @BillingStartDate AS NewBillingStartDate;
END

CREATE   PROCEDURE dbo.ReorderFeeTypes
    @UserId int, @Items dbo.DisplayOrderItem READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXEC dbo.RequirePermission @UserId, N'Fees.Configura
tion.Manage';
    BEGIN TRY
        BEGIN TRANSACTION;
        DECLARE @OrderLock int;
        EXEC @OrderLock=sys.sp_getapplock @Resource=N'SetupOrder:FeeTypes',
            @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=10000;
        IF @OrderLock<0 THROW 57401, 'Unable to lock setup ordering. Please try again.', 1;
        DECLARE @Count int;
        SELECT @Count=COUNT(*) FROM dbo.FeeTypes WITH(UPDLOCK,HOLDLOCK);
        IF @Count<>(SELECT COUNT(*) FROM @Items)
            THROW 57600, 'The supplied order must contain every entry in the list.', 1;
        IF EXISTS(SELECT ItemId FROM @Items GROUP BY ItemId HAVING COUNT(*)>1)
            THROW 57601, 'Duplicate entries were supplied.', 1;
        IF EXISTS(SELECT DisplayOrder FROM @Items GROUP BY DisplayOrder HAVING COUNT(*)>1)
            OR EXISTS(SELECT 1 FROM @Items WHERE DisplayOrder<1)
            THROW 57602, 'Invalid ordering positions were supplied.', 1;
        IF EXISTS(SELECT 1 FROM @Items I LEFT JOIN dbo.FeeTypes T ON T.FeeTypeId=I.ItemId
            WHERE T.FeeTypeId IS NULL)
            THROW 57603, 'An entry is invalid or belongs to another list.', 1;
        DECLARE @Ranked TABLE(ItemId int PRIMARY KEY, Position int);
        INSERT @Ranked SELECT ItemId, ROW_NUMBER() OVER(ORDER BY DisplayOrder,ItemId) FROM @Items;
        UPDATE T SET DisplayOrder=-R.Position FROM dbo.FeeTypes T JOIN @Ranked R ON R.ItemId=T.FeeTypeId;
        UPDATE T SET DisplayOrder=R.Position FROM dbo.FeeTypes T JOIN @Ranked R ON R.ItemId=T.FeeTypeId;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;

-- Audit paths are flattened only for changed values, including nested objects
-- and bulk arrays. JSON types, explicit nulls and absent properties remain distinct.
CREATE   FUNCTION dbo.AuditValueLeaves(@Json nvarchar(max))
RETURNS @Leaves TABLE (Path nvarchar(4000), FieldName nvarchar(4000), Value nvarchar(max), JsonType int)
AS
BEGIN
    IF @Json IS NULL OR ISJSON(@Json)<>1 RETURN;
    DECLARE @Nodes TABLE (NodeId int IDENTITY, Path nvarchar(4000), FieldName nvarchar(4000), Value nvarchar(max), JsonType int);
    INSERT @Nodes(Path,FieldName,Value,JsonType)
        VALUES(N'',N'',@Json,CASE WHEN LEFT(LTRIM(@Json),1)=N'[' THEN 4 ELSE 5 END);
    DECLARE @Id int=1,@Max int,@Path nvarchar(4000),@Name nvarchar(4000),@Value nvarchar(max),@Type int;
    WHILE EXISTS(SELECT 1 FROM @Nodes WHERE NodeId=@Id)
    BEGIN
        SELECT @Path=Path,@Name=FieldName,@Value=Value,@Type=JsonType FROM @Nodes WHERE NodeId=@Id;
        IF @Type IN (4,5) AND EXISTS(SELECT 1 FROM OPENJSON(@Value))
        BEGIN
            INSERT @Nodes(Path,FieldName,Value,JsonType)
            SELECT CASE WHEN @Type=4 THEN CONCAT(@Path,N'[',[key],N']')
                        WHEN @Path=N'' THEN [key] ELSE CONCAT(@Path,N'.',[key]) END,
                   [key],value,type
            FROM OPENJSON(@Value)
            WHERE [key] NOT IN (N'CreatedAt',N'UpdatedAt',N'CreatedByUserId',N'UpdatedByUserId',N'PasswordHash'
,N'PasswordSalt');
        END
        ELSE INSERT @Leaves VALUES(CASE WHEN @Path=N'' THEN N'$' ELSE @Path END,@Name,@Value,@Type);
        SET @Id+=1;
    END;
    RETURN;
END;

-- RenameOwnUsername
CREATE   PROCEDURE dbo.RenameOwnUsername
@UserId INT, @NewUsername NVARCHAR (100)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequireAuthenticatedUser @UserId;
    SET @NewUsername = LTRIM(RTRIM(@NewUsername));
    IF NULLIF (@NewUsername, N'') IS NULL
        THROW 57301, 'Username is required.', 1;
    IF LEN(@NewUsername) > 100
        THROW 57302, 'Username is too long (100 characters maximum).', 1;
    IF EXISTS (SELECT 1
               FROM   dbo.Users
               WHERE  Username = @NewUsername
                      AND UserId <> @UserId)
        THROW 57303, 'That username is already in use by another account.', 1;
    DECLARE @OldUsername AS NVARCHAR (100);
    SELECT @OldUsername = Username
    FROM   dbo.Users
    WHERE  UserId = @UserId;
    BEGIN TRANSACTION;

 UPDATE dbo.Users
    SET    Username  = @NewUsername,
           UpdatedAt = SYSDATETIME()
    WHERE  UserId = @UserId;
    IF @@ROWCOUNT = 0
        THROW 57304, 'The user account is inactive or was not found.', 1;
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    DECLARE @AuditRecordId AS NVARCHAR (200) = CAST (@UserId AS NVARCHAR (200));
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'USERNAME_RENAME', @AuditRecordId);
    DECLARE @OldValues AS NVARCHAR (MAX) = (SELECT @OldUsername AS Username
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER);
    DECLARE @NewValues AS NVARCHAR (MAX) = (SELECT @NewUsername AS Username
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'Users', @RecordId = @AuditRecordId, @Action = N'UPDATE', @OldValues = @OldValues, @NewValues = @NewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
END

CREATE   PROCEDURE dbo.ReconcileEnrollmentDates
 @UserId int, @EnrollmentId int, @EnrollmentDate date, @BillingStartDate date,
 @Reason nvarchar(500), @AllowLegacyExceptions bit=0,
 @Preview bit=1, @ExpectedSnapshot nvarchar(max)=NULL
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.RequirePermission @UserId,N'Students.Administer';
 EXEC dbo.RequirePermission @UserId,N'Fees.Adjust';
 IF NULLIF(LTRIM(RTRIM(@Reason)),N'') IS NULL THROW 57400,'Enter a reason for this correction.',1;
 IF @EnrollmentDate IS NULL OR @EnrollmentDate>CONVERT(date,SYSDATETIME())
  THROW 57401,'Enter an enrollment start that is not in the future.',1;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @AdmissionId int,@Ready bit,@Return datetime2,@YearStart date,@YearEnd date,@FirstAdmission date,
   @Status nvarchar(30),@ClassSectionId int,@Locked int,@LockResult int;
  SELECT @AdmissionId=AdmissionId FROM dbo.Enrollments WHERE EnrollmentId=@EnrollmentId;
  IF @AdmissionId IS NULL THROW 57402,'The enrollment no longer exists.',1;
  SELECT @FirstAdmission=AdmissionDate FROM dbo.Students WITH(UPDLOCK,HOLDLOCK) WHERE AdmissionId=@AdmissionId;
  SELECT @Locked=COUNT(*) FROM dbo.Enrollments WITH(UPDLOCK,HOLDLOCK) WHERE AdmissionId=@AdmissionId;
  SELECT @Ready=E.BillingReady,@Return=E.ReturnConfirmedAt,@Status=E.Status,@ClassSectionId=E.ClassSectionId,
   @YearStart=Y.StartDate,@YearE
nd=Y.EndDate
   FROM dbo.Enrollments E JOIN dbo.AcademicYears Y ON Y.AcademicYearId=E.AcademicYearId WHERE E.EnrollmentId=@EnrollmentId;
  IF @Status<>N'Active' THROW 57403,'Closed enrollments are view only.',1;
  IF @Ready=1 AND @BillingStartDate IS NULL THROW 57404,'Billing start is required for a confirmed enrollment.',1;
  IF @BillingStartDate<@EnrollmentDate OR @BillingStartDate>@YearEnd
   THROW 57405,'Billing start must be on or after enrollment start and within the academic year.',1;
  IF @AllowLegacyExceptions=0 AND (@EnrollmentDate<@FirstAdmission OR @EnrollmentDate<@YearStart OR @EnrollmentDate>@YearEnd
   OR EXISTS(SELECT 1 FROM dbo.Enrollments WHERE AdmissionId=@AdmissionId AND EnrollmentId<>@EnrollmentId
     AND ISNULL(LeavingDate,'99991231')>@EnrollmentDate))
   THROW 57406,'The start precedes admission, overlaps another enrollment, or falls outside its academic year.',1;
  DECLARE @LockResource nvarchar(255)=N'FMSC.GenerateEnrollmentCharges.'+CONVERT(nvarchar(20),@EnrollmentId);
  EXEC @LockResult=sys.sp_getapplock @Resource=@LockResource,@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=0;
  IF @LockResult<0 THROW 57407,'Billing is being changed elsewhere. Reload and try again.',1;
  SELECT @Locked=COUNT(*) FROM dbo.StudentFeeAssignments WITH(UPDLOCK,HOLDLOCK) WHERE EnrollmentId=@EnrollmentId;
  SELECT @Locked=COUNT(*) FROM dbo.BillingCharges WITH(UPDLOCK,HOLDLOCK) WHERE EnrollmentId=@EnrollmentId;
  SELECT @Locked=COUNT(*) FROM dbo.FeePaymentAllocations A WITH(UPDLOCK,HOLDLOCK)
   JOIN dbo.BillingCharges B ON B.BillingChargeId=A.BillingChargeId WHERE B.EnrollmentId=@EnrollmentId;
  DECLARE @Snapshot nvarchar(max)=(SELECT
   JSON_QUERY((SELECT * FROM dbo.Enrollments WHERE AdmissionId=@AdmissionId ORDER BY EnrollmentId FOR JSON PATH,INCLUDE_NULL_VALUES)) Enrollments,
   JSON_QUERY((SELECT * FROM dbo.StudentFeeAssignments WHERE EnrollmentId=@EnrollmentId ORDER BY StudentFeeAssignmentId FOR JSON PATH,INCLUDE_NULL_VALUES)) Assignments,
   JSON_QUERY((SE
LECT * FROM dbo.BillingCharges WHERE EnrollmentId=@EnrollmentId ORDER BY BillingChargeId FOR JSON PATH,INCLUDE_NULL_VALUES)) Charges,
   JSON_QUERY((SELECT A.* FROM dbo.FeePaymentAllocations A JOIN dbo.BillingCharges B ON B.BillingChargeId=A.BillingChargeId
    WHERE B.EnrollmentId=@EnrollmentId ORDER BY A.FeePaymentAllocationId FOR JSON PATH,INCLUDE_NULL_VALUES)) Allocations
   FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
  IF @Preview=0 AND (@ExpectedSnapshot IS NULL OR @ExpectedSnapshot<>@Snapshot)
   THROW 57408,'Records changed after the preview. Review the reconciliation again.',1;
  DECLARE @Opening date=DATEFROMPARTS(YEAR(@BillingStartDate),MONTH(@BillingStartDate),1),
   @AsOf date=CASE WHEN CONVERT(date,SYSDATETIME())<@YearEnd THEN CONVERT(date,SYSDATETIME()) ELSE @YearEnd END;
  -- Retain valid months already posted ahead of today within this academic year.
  SELECT @AsOf=CASE WHEN MAX(BillingMonth)>@AsOf THEN MAX(BillingMonth) ELSE @AsOf END
   FROM dbo.BillingCharges WHERE EnrollmentId=@EnrollmentId AND ChargeKind=N'Monthly' AND Status<>N'Cancelled' AND BillingMonth<=@YearEnd;
  DECLARE @CorrectedReturn datetime2=CASE WHEN @Return IS NOT NULL AND @Return<@EnrollmentDate THEN CONVERT(datetime2,@EnrollmentDate) ELSE @Return END;
  DECLARE @Expected TABLE(StudentFeeAssignmentId int,FeeTypeId int,BillingMonth date,ChargeKind nvarchar(20),
   ChargeDate date,GrossAmount decimal(18,2),DiscountAmount decimal(18,2));
  IF @Ready=1
  BEGIN
   ;WITH Months AS (
    SELECT @Opening BillingMonth WHERE @Opening<=@AsOf
    UNION ALL SELECT DATEADD(month,1,BillingMonth) FROM Months WHERE DATEADD(month,1,BillingMonth)<=@AsOf)
   INSERT @Expected
   SELECT F.StudentFeeAssignmentId,F.FeeTypeId,M.BillingMonth,N'Monthly',M.BillingMonth,F.Amount,F.DiscountAmount
    FROM Months M JOIN dbo.StudentFeeAssignments F ON F.EnrollmentId=@EnrollmentId
    WHERE F.CancelledAt IS NULL AND F.Frequency=N'Monthly'
     AND (F.EffectiveFrom IS NULL OR M.BillingMonth>=F.EffectiveFrom)
     AND (F.Effecti
veTo IS NULL OR M.BillingMonth<=F.EffectiveTo) OPTION(MAXRECURSION 1200);
   INSERT @Expected
   SELECT F.StudentFeeAssignmentId,F.FeeTypeId,@Opening,N'Annual',COALESCE(CONVERT(date,@CorrectedReturn),@EnrollmentDate),
    COALESCE(B.GrossAmount,F.Amount),COALESCE(B.DiscountAmount,F.DiscountAmount)
    FROM dbo.StudentFeeAssignments F OUTER APPLY(SELECT TOP(1) GrossAmount,DiscountAmount FROM dbo.BillingCharges
     WHERE EnrollmentId=@EnrollmentId AND FeeTypeId=F.FeeTypeId AND ChargeKind=N'Annual' AND Status<>N'Cancelled' ORDER BY BillingChargeId) B
    WHERE F.EnrollmentId=@EnrollmentId AND F.CancelledAt IS NULL AND F.Frequency=N'Yearly'
     AND (F.EffectiveFrom IS NULL OR @Opening>=F.EffectiveFrom) AND (F.EffectiveTo IS NULL OR @Opening<=F.EffectiveTo);
  END;
  IF EXISTS(SELECT 1 FROM @Expected GROUP BY FeeTypeId,BillingMonth,ChargeKind HAVING COUNT(*)>1)
   THROW 57409,'Fee-assignment periods overlap. Correct the assignments before reconciling.',1;
  DECLARE @Cancel TABLE(BillingChargeId bigint PRIMARY KEY);
  INSERT @Cancel SELECT B.BillingChargeId FROM dbo.BillingCharges B
   WHERE B.EnrollmentId=@EnrollmentId AND B.Status<>N'Cancelled' AND B.ChargeKind IN(N'Monthly',N'Annual')
    AND NOT EXISTS(SELECT 1 FROM @Expected X WHERE X.FeeTypeId=B.FeeTypeId AND X.BillingMonth=B.BillingMonth AND X.ChargeKind=B.ChargeKind
     AND (B.ChargeKind<>N'Annual' OR B.ChargeDate=X.ChargeDate));
  DECLARE @Blocked int=(SELECT COUNT(*) FROM @Cancel C JOIN dbo.BillingCharges B ON B.BillingChargeId=C.BillingChargeId
   WHERE B.Status<>N'Open' OR EXISTS(SELECT 1 FROM dbo.FeePaymentAllocations WHERE BillingChargeId=B.BillingChargeId));
  DECLARE @Add TABLE(StudentFeeAssignmentId int,FeeTypeId int,BillingMonth date,ChargeKind nvarchar(20),ChargeDate date,
   GrossAmount decimal(18,2),DiscountAmount decimal(18,2));
  INSERT @Add SELECT X.* FROM @Expected X WHERE NOT EXISTS(SELECT 1 FROM dbo.BillingCharges B
   WHERE B.EnrollmentId=@EnrollmentId AND B.FeeTypeId=X.FeeTypeId AND B.ChargeKind=X.Char
geKind
    AND B.BillingMonth=X.BillingMonth AND B.Status<>N'Cancelled' AND NOT EXISTS(SELECT 1 FROM @Cancel C WHERE C.BillingChargeId=B.BillingChargeId));
  DECLARE @CancelCount int=(SELECT COUNT(*) FROM @Cancel),@AddCount int=(SELECT COUNT(*) FROM @Add),
   @CancelledAmount decimal(18,2)=COALESCE((SELECT SUM(B.NetAmount) FROM @Cancel C JOIN dbo.BillingCharges B ON B.BillingChargeId=C.BillingChargeId),0),
   @AddedAmount decimal(18,2)=COALESCE((SELECT SUM(GrossAmount-DiscountAmount) FROM @Add),0);
  IF @Preview=1
  BEGIN
   COMMIT;
   SELECT @Snapshot Snapshot,@CancelCount CancelCount,@AddCount AddCount,@CancelledAmount CancelledAmount,@AddedAmount AddedAmount,
    @Blocked BlockedCount,@AsOf ThroughDate,@CorrectedReturn ReturnDate;
   RETURN;
  END;
  IF @Blocked>0 THROW 57410,'Affected charges have payment history. Reverse or refund those payments in Student Fees before reconciling; no records were changed.',1;
  UPDATE dbo.Enrollments SET EnrollmentDate=@EnrollmentDate,BillingStartDate=@BillingStartDate,
   ReturnConfirmedAt=@CorrectedReturn,UpdatedAt=SYSDATETIME() WHERE EnrollmentId=@EnrollmentId;
  UPDATE B SET Status=N'Cancelled',Remarks=LEFT(COALESCE(B.Remarks+N' | ',N'')+N'Enrollment reconciliation: '+@Reason,1000)
   FROM dbo.BillingCharges B JOIN @Cancel C ON C.BillingChargeId=B.BillingChargeId;
  INSERT dbo.BillingCharges(StudentFeeAssignmentId,EnrollmentId,AdmissionId,FeeTypeId,BillingMonth,ChargeDate,DueDate,GrossAmount,DiscountAmount,ChargeKind,Remarks)
   SELECT StudentFeeAssignmentId,@EnrollmentId,@AdmissionId,FeeTypeId,BillingMonth,ChargeDate,ChargeDate,GrossAmount,DiscountAmount,ChargeKind,
    LEFT(N'Enrollment reconciliation: '+@Reason,1000) FROM @Add;
  INSERT dbo.EnrollmentHistory(EnrollmentId,AdmissionId,ActionType,ActionDate,OldClassSectionId,NewClassSectionId,OldStatus,NewStatus,Remarks,UserId)
   VALUES(@EnrollmentId,@AdmissionId,N'CORRECTION',CONVERT(date,SYSDATETIME()),@ClassSectionId,@ClassSectionId,@Status,@Status,
    LEFT(N'Dates and billing re
conciled: '+@Reason,500),@UserId);
  DECLARE @Operation uniqueidentifier=NEWID(),@After nvarchar(max)=(SELECT @EnrollmentId EnrollmentId,@EnrollmentDate EnrollmentDate,
   @BillingStartDate BillingStartDate,@CorrectedReturn ReturnConfirmedAt,@CancelCount CancelledCharges,@AddCount AddedCharges,
   @Reason Reason,@AllowLegacyExceptions LegacyException,
   JSON_QUERY((SELECT * FROM dbo.BillingCharges WHERE EnrollmentId=@EnrollmentId ORDER BY BillingChargeId FOR JSON PATH)) Charges
   FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
  INSERT dbo.AuditOperations(OperationId,UserId,OperationType,CorrelationNote) VALUES(@Operation,@UserId,N'ENROLLMENT_RECONCILIATION',CONVERT(nvarchar(200),@EnrollmentId));
  DECLARE @Record nvarchar(200)=CONVERT(nvarchar(200),@EnrollmentId);
  EXEC dbo.WriteAuditLog @OperationId=@Operation,@UserId=@UserId,@TableName=N'Enrollments',@RecordId=@Record,@Action=N'CORRECTION',@OldValues=@Snapshot,@NewValues=@After;
  COMMIT;
  SELECT @CancelCount CancelledCharges,@AddCount AddedCharges;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;

CREATE   PROCEDURE dbo.SaveCampus
@UserId INT, @CampusCode NVARCHAR (30), @CampusName NVARCHAR (150), @CampusType NVARCHAR (30), @CampusId INT=0, @AddressLine NVARCHAR (500)=NULL, @City NVARCHAR (100)=NULL, @ContactNumber NVARCHAR (30)=NULL, @Email NVARCHAR (150)=NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @OrderLock int;
    EXEC @OrderLock=sys.sp_getapplock @Resource=N'SetupOrder:Campuses', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=10000;
    IF @OrderLock<0 THROW 57401, 'Unable to lock setup ordering. Please try again.', 1;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'System.Setup';
    IF NULLIF (LTRIM(RTRIM(@CampusCode)), N'') IS NULL
        THROW 56001, 'Campus code is required.', 1;
    IF NULLIF (LTRIM(RTRIM(@CampusName)), N'
') IS NULL
        THROW 56002, 'Campus name is required.', 1;
    IF @CampusId = 0
        BEGIN
            DECLARE @NextOrder int;
            SELECT @NextOrder=ISNULL(MAX(DisplayOrder),0)+1 FROM dbo.Campuses WITH(UPDLOCK,HOLDLOCK);
            INSERT dbo.Campuses (DisplayOrder, CampusCode, CampusName, CampusType, AddressLine, City, ContactNumber, Email)
            VALUES (@NextOrder, @CampusCode, @CampusName, @CampusType, @AddressLine, @City, @ContactNumber, @Email);
            COMMIT TRANSACTION;
            SELECT CONVERT (INT, SCOPE_IDENTITY()) AS CampusId;
        END
    ELSE
        BEGIN
            UPDATE dbo.Campuses
            SET    CampusCode    = @CampusCode,
                   CampusName    = @CampusName,
                   CampusType    = @CampusType,
                   AddressLine   = @AddressLine,
                   City          = @City,
                   ContactNumber = @ContactNumber,
                   Email         = @Email,
                   UpdatedAt     = SYSDATETIME()
            WHERE  CampusId = @CampusId;
            IF @@ROWCOUNT = 0
                THROW 56003, 'The selected campus was not found.', 1;
            COMMIT TRANSACTION;
            SELECT @CampusId AS CampusId;
        END
END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END

-- ProcessFeeTransaction
CREATE   PROCEDURE dbo.ProcessFeeTransaction
@GroupReceiptNumber NVARCHAR (40)=NULL, @AdmissionId INT, @EnrollmentId INT, @TransactionType NVARCHAR (20), @Amount DECIMAL (12, 2), @TransactionDate DATE, @PaymentMethod NVARCHAR (30), @ReferenceNumber NVARCHAR (100), @Remarks NVARCHAR (500), @FeePaymentId INT, @BillingChargeId BIGINT, @Allocations dbo.FeePaymentAllocationType READONLY, @UserId INT
AS
BEGIN

    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Fees.Collect';
    SET @TransactionType = LTRIM(RTRIM(@TransactionType));
    IF @TransactionType NOT IN (N'Collection', N'Correction', N'Refund', N'Reversal')
        THROW 54001, 'Invalid fee transaction type.', 1;
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.Students
                   WHERE  AdmissionId = @AdmissionId)
        THROW 54002, 'The selected student was not found.', 1;
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.Enrollments
                   WHERE  EnrollmentId = @EnrollmentId
                          AND AdmissionId = @AdmissionId)
        THROW 54003, 'The selected enrollment does not belong to this student.', 1;
    IF @TransactionDate IS NULL
        THROW 54005, 'The transaction date is required.', 1;
    IF @TransactionDate > CAST (GETDATE() AS DATE)
        THROW 54004, 'The transaction date cannot be in the future.', 1;
    BEGIN TRANSACTION;
    DECLARE @ReceiptNumber AS NVARCHAR (40) = NULL, @ResultPaymentId AS INT = NULL, @NewBalance AS DECIMAL (12, 2) = NULL, @PaymentAmount AS DECIMAL (12, 2) = 0, @DiscountTotal AS DECIMAL (12, 2) = 0, @EnrollmentDate AS DATE = NULL;
    SELECT @EnrollmentDate = EnrollmentDate
    FROM   dbo.Enrollments WITH (UPDLOCK, HOLDLOCK)
    WHERE  EnrollmentId = @EnrollmentId
           AND AdmissionId = @AdmissionId;
    IF @EnrollmentDate IS NULL
        THROW 54006, 'The selected enrollment has no valid enrollment date.', 1;
    IF @TransactionType = N'Collection'
        BEGIN
            IF @TransactionDate < @EnrollmentDate
                THROW 54007, 'The transaction date cannot be before the enrollment date.', 1;
            SELECT @PaymentAmount = ISNULL(SUM(CASE WHEN Amount > 0 THEN Amount ELSE 0 END), 0),
                   @DiscountTotal = ISNULL(-SUM(CASE WHEN Amount < 0 THEN Amount ELSE 0 END), 0)
            FROM   @
Allocations;
            IF @PaymentAmount <= 0
               AND @DiscountTotal <= 0
                THROW 54010, 'Enter a payment or a discount.', 1;
            IF ABS(@Amount - @PaymentAmount) > 0.005
                THROW 54011, 'The payment total does not match the Pay Now allocations.', 1;
            IF EXISTS (SELECT 1
                       FROM   @Allocations AS A
                              LEFT OUTER JOIN
                              dbo.BillingCharges AS BC WITH (UPDLOCK, HOLDLOCK)
                              ON BC.BillingChargeId = A.BillingChargeId CROSS APPLY (SELECT ISNULL(SUM(CASE WHEN X.Amount > 0 THEN X.Amount ELSE 0 END), 0) AS PaymentPart,
                                                                                            ISNULL(-SUM(CASE WHEN X.Amount < 0 THEN X.Amount ELSE 0 END), 0) AS DiscountPart
                                                                                     FROM   @Allocations AS X
                                                                                     WHERE  X.BillingChargeId = A.BillingChargeId) AS V
                       WHERE  BC.BillingChargeId IS NULL
                              OR BC.AdmissionId <> @AdmissionId
                              OR BC.EnrollmentId <> @EnrollmentId
                              OR BC.Status = N'Cancelled'
                              OR BC.ChargeDate IS NULL
                              OR V.DiscountPart > dbo.GetFeeChargeBalance(A.BillingChargeId)
                              OR V.PaymentPart + V.DiscountPart > dbo.GetFeeChargeBalance(A.BillingChargeId))
                THROW 54013, 'One or more selected charges is invalid: it has been cancelled, belongs to another student or enrollment, has no charge date, or its remaining balance no longer covers this allocation. Refresh and try again.', 1;
            IF @PaymentAmount > 0
               AND NULLIF (LTRIM(RTRIM(@PaymentMethod)), N'') IS NULL

 THROW 54014, 'Select a payment method.', 1;
            UPDATE BC
            SET    DiscountAmount = BC.DiscountAmount + D.DiscountAmount,
                   Remarks        = CASE WHEN NULLIF (LTRIM(RTRIM(@Remarks)), N'') IS NULL THEN BC.Remarks WHEN NULLIF (BC.Remarks, N'') IS NULL THEN @Remarks ELSE BC.Remarks + N' | ' + @Remarks END
            FROM   dbo.BillingCharges AS BC
                   INNER JOIN
                   (SELECT   BillingChargeId,
                             -SUM(CASE WHEN Amount < 0 THEN Amount ELSE 0 END) AS DiscountAmount
                    FROM     @Allocations
                    GROUP BY BillingChargeId
                    HAVING   SUM(CASE WHEN Amount < 0 THEN Amount ELSE 0 END) < 0) AS D
                   ON D.BillingChargeId = BC.BillingChargeId;
            IF @PaymentAmount > 0
                BEGIN
                    IF @GroupReceiptNumber IS NULL
                        BEGIN
                            EXECUTE dbo.GetNextFeeReceiptNumber @ReceiptDate = @TransactionDate, @ReceiptNumber = @ReceiptNumber OUTPUT;
                        END
                    ELSE
                        BEGIN
                            SET @ReceiptNumber = @GroupReceiptNumber;
                        END
                    INSERT  dbo.FeePayments (AdmissionId, EnrollmentId, PaymentDate, ReceiptNumber, TotalAmount, PaymentMethod, ReferenceNumber, Remarks, Status, IsGroupPayment, CreatedByUserId)
                    VALUES                 (@AdmissionId, @EnrollmentId, @TransactionDate, @ReceiptNumber, @PaymentAmount, @PaymentMethod, NULLIF (LTRIM(RTRIM(@ReferenceNumber)), N''), NULLIF (LTRIM(RTRIM(@Remarks)), N''), N'Completed', CASE WHEN @GroupReceiptNumber IS NULL THEN 0 ELSE 1 END, @UserId);
                    SET @ResultPaymentId = CONVERT (INT, SCOPE_IDENTITY());
                    INSERT dbo.FeePaymentAllocations (FeePaymentId, AdmissionId, BillingChargeId, Amount, Remarks)

    SELECT @ResultPaymentId,
                           @AdmissionId,
                           BillingChargeId,
                           Amount,
                           NULL
                    FROM   @Allocations
                    WHERE  Amount > 0;
                END
            UPDATE BC
            SET    Status = CASE WHEN dbo.GetFeeChargeBalance(BC.BillingChargeId) <= 0 THEN N'Paid' WHEN dbo.GetFeeChargeBalance(BC.BillingChargeId) < BC.NetAmount THEN N'PartiallyPaid' ELSE N'Open' END
            FROM   dbo.BillingCharges AS BC
                   INNER JOIN
                   (SELECT DISTINCT BillingChargeId
                    FROM   @Allocations) AS A
                   ON A.BillingChargeId = BC.BillingChargeId;
            SELECT TOP (1) @NewBalance = dbo.GetFeeChargeBalance(BC.BillingChargeId)
            FROM   dbo.BillingCharges AS BC
                   INNER JOIN
                   (SELECT   TOP (1) BillingChargeId
                    FROM     @Allocations
                    ORDER BY BillingChargeId) AS A
                   ON A.BillingChargeId = BC.BillingChargeId;
        END
    IF @TransactionType IN (N'Correction', N'Refund')
        BEGIN
            IF @FeePaymentId IS NULL
                THROW 54020, 'Select a completed payment.', 1;
            DECLARE @OriginalTotal AS DECIMAL (12, 2), @OriginalPaymentDate AS DATE, @AlreadyReduced AS DECIMAL (12, 2), @RemainingReducible AS DECIMAL (12, 2), @ReductionAmount AS DECIMAL (12, 2);
            SELECT @OriginalTotal = TotalAmount,
                   @OriginalPaymentDate = PaymentDate
            FROM   dbo.FeePayments WITH (UPDLOCK, HOLDLOCK)
            WHERE  FeePaymentId = @FeePaymentId
                   AND AdmissionId = @AdmissionId
                   AND EnrollmentId = @EnrollmentId
                   AND Status = N'Completed'
                   AND TotalAmount > 0;
            IF @OriginalTotal IS NULL

              THROW 54022, 'The selected payment is not an active completed payment.', 1;
            IF @OriginalPaymentDate IS NULL
                THROW 54026, 'The selected payment has no valid payment date.', 1;
            IF @TransactionDate < @OriginalPaymentDate
                THROW 54027, 'The transaction date cannot be before the original payment date.', 1;
            SELECT @AlreadyReduced = ISNULL(-SUM(FPA.Amount), 0)
            FROM   dbo.FeePayments AS P
                   INNER JOIN
                   dbo.FeePaymentAllocations AS FPA
                   ON FPA.FeePaymentId = P.FeePaymentId
            WHERE  P.RelatedFeePaymentId = @FeePaymentId
                   AND P.Status = N'Completed'
                   AND P.TotalAmount < 0
                   AND FPA.Amount < 0;
            SET @AlreadyReduced = ISNULL(@AlreadyReduced, 0);
            SET @RemainingReducible = @OriginalTotal - @AlreadyReduced;
            IF @TransactionType = N'Correction'
                BEGIN
                    IF @Amount < 0
                        THROW 54021, 'The corrected amount cannot be negative. To remove the entire payment, correct it to 0 or use Reversal.', 1;
                    IF @Amount >= @RemainingReducible
                        THROW 54023, 'The corrected amount must be less than the currently collected amount.', 1;
                    SET @ReductionAmount = @RemainingReducible - @Amount;
                END
            ELSE
                BEGIN
                    IF @Amount <= 0
                        THROW 54036, 'The refund amount must be greater than zero.', 1;
                    SET @ReductionAmount = @Amount;
                END
            IF @ReductionAmount <= 0
                THROW 54024, 'No reduction is required for the selected amount.', 1;
            EXECUTE dbo.GetNextFeeReceiptNumber @ReceiptDate = @TransactionDate, @ReceiptNumber = @ReceiptNumber OUTPUT;

   INSERT  dbo.FeePayments (AdmissionId, EnrollmentId, PaymentDate, ReceiptNumber, TotalAmount, PaymentMethod, ReferenceNumber, Remarks, Status, CreatedByUserId, RelatedFeePaymentId)
            VALUES                 (@AdmissionId, @EnrollmentId, @TransactionDate, @ReceiptNumber, -@ReductionAmount, CASE WHEN @TransactionType = N'Correction' THEN N'Correction' ELSE N'Refund' END, COALESCE (NULLIF (LTRIM(RTRIM(@ReferenceNumber)), N''), (SELECT ReceiptNumber
                                                                                                                                                                                                                                                                 FROM   dbo.FeePayments
                                                                                                                                                                                                                                                                 WHERE  FeePaymentId = @FeePaymentId)), NULLIF (LTRIM(RTRIM(@Remarks)), N''), N'Completed', @UserId, @FeePaymentId);
            SET @ResultPaymentId = CONVERT (INT, SCOPE_IDENTITY());
            DECLARE @RemainingReduction AS DECIMAL (12, 2) = @ReductionAmount, @ChargeId AS BIGINT, @OriginalAllocation AS DECIMAL (12, 2), @AlreadyOnCharge AS DECIMAL (12, 2), @Available AS DECIMAL (12, 2), @Take AS DECIMAL (12, 2);
            DECLARE ReductionCursor CURSOR LOCAL FAST_FORWARD
                FOR SELECT   FPA.BillingChargeId,
                             FPA.Amount,
                             ISNULL((SELECT -SUM(RA.Amount)
                                     FROM   dbo.FeePayments AS RP
                                            INNER JOIN
                                            dbo.FeePaymentAllocations AS RA
                                            ON RA.FeePaymentId = RP.FeePaymentId
                                     WHERE  RP.RelatedFeePaymentId = @FeePaymentId

                                            AND RP.Status = N'Completed'
                                            AND RP.TotalAmount < 0
                                            AND RA.BillingChargeId = FPA.BillingChargeId
                                            AND RA.Amount < 0), 0) AS AlreadyOnCharge
                    FROM     dbo.FeePaymentAllocations AS FPA
                    WHERE    FPA.FeePaymentId = @FeePaymentId
                             AND FPA.Amount > 0
                    ORDER BY FPA.FeePaymentAllocationId;
            OPEN ReductionCursor;
            FETCH NEXT FROM ReductionCursor INTO @ChargeId, @OriginalAllocation, @AlreadyOnCharge;
            WHILE @@FETCH_STATUS = 0
                  AND @RemainingReduction > 0
                BEGIN
                    SET @Available = @OriginalAllocation - ISNULL(@AlreadyOnCharge, 0);
                    IF @Available > 0
                        BEGIN
                            SET @Take = CASE WHEN @Available < @RemainingReduction THEN @Available ELSE @RemainingReduction END;
                            INSERT  dbo.FeePaymentAllocations (FeePaymentId, AdmissionId, BillingChargeId, Amount, Remarks)
                            VALUES                           (@ResultPaymentId, @AdmissionId, @ChargeId, -@Take, CASE WHEN @TransactionType = N'Correction' THEN N'Correction' ELSE N'Refund' END);
                            SET @RemainingReduction -= @Take;
                        END
                    FETCH NEXT FROM ReductionCursor INTO @ChargeId, @OriginalAllocation, @AlreadyOnCharge;
                END
            CLOSE ReductionCursor;
            DEALLOCATE ReductionCursor;
            IF @RemainingReduction > 0
                THROW 54025, 'The amount could not be fully allocated against the selected payment.', 1;
            UPDATE BC
            SET    Status  = CASE WHEN dbo.GetFeeChargeBalance(BC.BillingChargeId) <= 0 THEN N'Paid' W
HEN dbo.GetFeeChargeBalance(BC.BillingChargeId) < BC.NetAmount THEN N'PartiallyPaid' ELSE N'Open' END,
                   Remarks = CASE WHEN NULLIF (LTRIM(RTRIM(@Remarks)), N'') IS NULL THEN BC.Remarks WHEN NULLIF (BC.Remarks, N'') IS NULL THEN @Remarks ELSE BC.Remarks + N' | ' + @Remarks END
            FROM   dbo.BillingCharges AS BC
            WHERE  BC.BillingChargeId IN (SELECT DISTINCT BillingChargeId
                                          FROM   dbo.FeePaymentAllocations
                                          WHERE  FeePaymentId = @ResultPaymentId);
            SELECT TOP (1) @NewBalance = dbo.GetFeeChargeBalance(BC.BillingChargeId)
            FROM   dbo.BillingCharges AS BC
                   INNER JOIN
                   (SELECT   TOP (1) BillingChargeId
                    FROM     dbo.FeePaymentAllocations
                    WHERE    FeePaymentId = @ResultPaymentId
                    ORDER BY BillingChargeId) AS A
                   ON A.BillingChargeId = BC.BillingChargeId;
        END
    IF @TransactionType = N'Reversal'
        BEGIN
            IF @FeePaymentId IS NULL
                THROW 54030, 'Select a completed payment to reverse.', 1;
            IF EXISTS (SELECT 1
                       FROM   dbo.FeePayments
                       WHERE  RelatedFeePaymentId = @FeePaymentId
                              AND Status = N'Completed'
                              AND TotalAmount < 0)
                THROW 54031, 'This payment already has a refund or correction. Reverse it through the appropriate transaction instead.', 1;
            DECLARE @AffectedCharges TABLE (
                BillingChargeId BIGINT PRIMARY KEY);
            INSERT @AffectedCharges (BillingChargeId)
            SELECT DISTINCT BillingChargeId
            FROM   dbo.FeePaymentAllocations
            WHERE  FeePaymentId = @FeePaymentId;
            DECLARE @OriginalReversalPaymentDate AS DATE = NULL;

        SELECT @Amount = TotalAmount,
                   @OriginalReversalPaymentDate = PaymentDate
            FROM   dbo.FeePayments WITH (UPDLOCK, HOLDLOCK)
            WHERE  FeePaymentId = @FeePaymentId
                   AND AdmissionId = @AdmissionId
                   AND EnrollmentId = @EnrollmentId
                   AND Status = N'Completed'
                   AND TotalAmount > 0;
            IF @Amount IS NULL
               OR @Amount <= 0
                THROW 54032, 'The selected payment is already reversed or is not a valid completed payment.', 1;
            IF @OriginalReversalPaymentDate IS NULL
                THROW 54034, 'The selected payment has no valid payment date.', 1;
            IF @TransactionDate < @OriginalReversalPaymentDate
                THROW 54035, 'The reversal date cannot be before the original payment date.', 1;
            UPDATE dbo.FeePayments
            SET    Status = N'Reversed'
            WHERE  FeePaymentId = @FeePaymentId
                   AND AdmissionId = @AdmissionId
                   AND EnrollmentId = @EnrollmentId
                   AND Status = N'Completed';
            IF @@ROWCOUNT = 0
                THROW 54033, 'The selected payment could not be reversed.', 1;
            UPDATE BC
            SET    Status = CASE WHEN dbo.GetFeeChargeBalance(BC.BillingChargeId) <= 0 THEN N'Paid' WHEN dbo.GetFeeChargeBalance(BC.BillingChargeId) < BC.NetAmount THEN N'PartiallyPaid' ELSE N'Open' END
            FROM   dbo.BillingCharges AS BC
                   INNER JOIN
                   @AffectedCharges AS AC
                   ON AC.BillingChargeId = BC.BillingChargeId;
        END
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType)
    VALUES                     (@OperationId, @UserId, CASE WHEN @TransactionType = N'Collection' THEN N'PAYMENT' WHEN @TransactionType = N'Correction'
 THEN N'FEE_CORRECTION' WHEN @TransactionType = N'Refund' THEN N'FEE_REFUND' ELSE N'FEE_REVERSAL' END);
    DECLARE @AuditTableName AS NVARCHAR (128), @AuditRecordId AS NVARCHAR (200), @AuditAction AS NVARCHAR (100), @AuditNewValues AS NVARCHAR (MAX);
    SET @AuditTableName = N'FeePayments';
    SET @AuditRecordId = CASE WHEN @TransactionType IN (N'Collection', N'Correction', N'Refund') THEN CONVERT (NVARCHAR (200), @ResultPaymentId) ELSE CONVERT (NVARCHAR (200), @FeePaymentId) END;
    SET @AuditAction = CASE WHEN @TransactionType = N'Collection' THEN N'PAYMENT' WHEN @TransactionType = N'Correction' THEN N'UPDATE' WHEN @TransactionType = N'Refund' THEN N'REFUND' WHEN @TransactionType = N'Reversal' THEN N'REVERSAL' ELSE N'OTHER' END;
    SET @AuditNewValues = (SELECT @AdmissionId AS AdmissionId,
                                  @EnrollmentId AS EnrollmentId,
                                  @TransactionType AS TransactionType,
                                  @Amount AS Amount,
                                  @PaymentAmount AS PaymentAmount,
                                  @DiscountTotal AS DiscountAmount,
                                  @FeePaymentId AS FeePaymentId,
                                  @ResultPaymentId AS ResultPaymentId,
                                  @ReceiptNumber AS ReceiptNumber
                           FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = @AuditTableName, @RecordId = @AuditRecordId, @Action = @AuditAction, @OldValues = NULL, @NewValues = @AuditNewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT @ResultPaymentId AS FeePaymentId,
           @ReceiptNumber AS ReceiptNumber,
           @TransactionType AS TransactionType,
           @Amount AS Amount,
           @NewBalance AS Balanc
e;
END

CREATE   PROCEDURE dbo.SaveAcademicProgram
@UserId INT, @AcademicProgramId INT, @ProgramType NVARCHAR (30), @ProgramCode NVARCHAR (30)=NULL, @ProgramName NVARCHAR (150), @DisplayOrder INT=0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'System.Setup';
    BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @OrderLock int;
    EXEC @OrderLock = sys.sp_getapplock @Resource=N'SetupOrder:AcademicPrograms', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=10000;
    IF @OrderLock < 0 THROW 57401, 'Unable to lock setup ordering. Please try again.', 1;
    IF NULLIF (LTRIM(RTRIM(@ProgramType)), N'') IS NULL
        THROW 56420, 'Program type is required.', 1;
    IF NULLIF (LTRIM(RTRIM(@ProgramName)), N'') IS NULL
        THROW 56421, 'Program name is required.', 1;
    IF @AcademicProgramId = 0
        BEGIN
            SELECT @DisplayOrder = ISNULL(MAX(DisplayOrder), 0) + 1
                    FROM   dbo.AcademicPrograms WITH (UPDLOCK,HOLDLOCK);
            INSERT  dbo.AcademicPrograms (ProgramCode, ProgramName, ProgramType, DisplayOrder, CreatedAt)
            VALUES                      (NULLIF (LTRIM(RTRIM(@ProgramCode)), N''), LTRIM(RTRIM(@ProgramName)), LTRIM(RTRIM(@ProgramType)), @DisplayOrder, SYSUTCDATETIME());

    COMMIT TRANSACTION;
    SELECT CONVERT (INT, SCOPE_IDENTITY()) AS AcademicProgramId;
            RETURN;
        END
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.AcademicPrograms
                   WHERE  AcademicProgramId = @AcademicProgramId)
        THROW 56422, 'The selected program was not found.', 1;
    UPDATE dbo.AcademicPrograms
    SET    ProgramCode  = NULLIF (LTRIM(RTRIM(@ProgramCode)), N''),
           ProgramName  = LTRIM(RTRIM(@ProgramName)),

 ProgramType  = LTRIM(RTRIM(@ProgramType)),
           UpdatedAt    = SYSUTCDATETIME()
    WHERE  AcademicProgramId = @AcademicProgramId;

    COMMIT TRANSACTION;
    SELECT @AcademicProgramId AS AcademicProgramId;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END

-- ChangeStudentFeeAssignmentAmount_Internal
CREATE PROCEDURE dbo.ChangeStudentFeeAssignmentAmount_Internal
@UserId INT, @StudentFeeAssignmentId INT, @NewAmount DECIMAL (12, 2), @EffectiveFrom DATE, @Reason NVARCHAR (500)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @Reason IS NULL
       OR LTRIM(RTRIM(@Reason)) = N''
        THROW 53140, 'A reason is required to change a fee amount.', 1;
    IF @NewAmount < 0
        THROW 53141, 'Amount cannot be negative.', 1;
    IF @EffectiveFrom IS NULL
        THROW 53147, 'An effective-from date is required.', 1;
    DECLARE @EnrollmentId AS INT, @AdmissionId AS INT, @FeeTypeId AS INT, @OldAmount AS DECIMAL (12, 2), @DiscountAmount AS DECIMAL (12, 2), @Frequency AS NVARCHAR (20), @Remarks AS NVARCHAR (500), @ExistingEffectiveFrom AS DATE, @ExistingEffectiveTo AS DATE, @CancelledAt AS DATETIME2;
    SELECT @EnrollmentId = EnrollmentId,
           @AdmissionId = AdmissionId,
           @FeeTypeId = FeeTypeId,
           @OldAmount = Amount,
           @DiscountAmount = DiscountAmount,
           @Frequency = Frequency,
           @Remarks = Remarks,
           @ExistingEffectiveFrom = EffectiveFrom,
           @ExistingEffectiveTo = EffectiveTo,
           @CancelledAt = CancelledAt
    FROM   dbo.StudentFeeAssignments
    WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId;
    IF @EnrollmentId IS NULL
        THROW 53142, 'The selected student fee assignment
 does not exist.', 1;
    IF @CancelledAt IS NOT NULL
        THROW 53143, 'This fee assignment has been cancelled.', 1;
    IF @ExistingEffectiveTo IS NOT NULL
        THROW 53144, 'This fee assignment has already been closed/superseded.', 1;
    DECLARE @NormalizedEffectiveFrom AS DATE = DATEFROMPARTS(YEAR(@EffectiveFrom), MONTH(@EffectiveFrom), 1);
    DECLARE @NormalizedOldEffectiveTo AS DATE = DATEADD(MONTH, -1, @NormalizedEffectiveFrom);

    -- UNBILLED_RATE_REPLACEMENT: no extra version or obsolete scheduled action.
    IF @ExistingEffectiveFrom IS NOT NULL AND @NormalizedEffectiveFrom <= @ExistingEffectiveFrom
       AND NOT EXISTS (SELECT 1 FROM dbo.BillingCharges WHERE StudentFeeAssignmentId = @StudentFeeAssignmentId)
    BEGIN
        BEGIN TRANSACTION;
        -- Serialize against posting or another rate edit before checking the timeline.
        IF NOT EXISTS (SELECT 1 FROM dbo.StudentFeeAssignments WITH (UPDLOCK, HOLDLOCK)
                       WHERE StudentFeeAssignmentId = @StudentFeeAssignmentId AND EffectiveTo IS NULL
                         AND CancelledAt IS NULL AND Amount = @OldAmount AND EffectiveFrom = @ExistingEffectiveFrom)
            THROW 53146, 'The fee has changed. Refresh the fees and try again.', 1;
        IF EXISTS (SELECT 1 FROM dbo.BillingCharges WITH (UPDLOCK, HOLDLOCK)
                   WHERE EnrollmentId = @EnrollmentId AND FeeTypeId = @FeeTypeId
                     AND (BillingMonth >= @NormalizedEffectiveFrom OR StudentFeeAssignmentId = @StudentFeeAssignmentId))
            THROW 53148, 'Choose a month after the last month already billed for this fee.', 1;
        IF EXISTS (SELECT 1 FROM dbo.StudentFeeAssignments
                   WHERE EnrollmentId = @EnrollmentId AND FeeTypeId = @FeeTypeId
                     AND StudentFeeAssignmentId <> @StudentFeeAssignmentId AND CancelledAt IS NULL
                     AND (EffectiveTo IS NULL OR EffectiveTo >= @NormalizedEffectiveFrom))
            THROW 53145, 'The se
lected month overlaps another fee period. Choose a later month.', 1;
        IF @NewAmount < @DiscountAmount
            THROW 53149, 'The new fee cannot be lower than its existing discount.', 1;
        UPDATE dbo.StudentFeeAssignments
        SET Amount = @NewAmount, EffectiveFrom = @NormalizedEffectiveFrom, UpdatedAt = SYSDATETIME()
        WHERE StudentFeeAssignmentId = @StudentFeeAssignmentId;
        DECLARE @ReplacementOperation uniqueidentifier = NEWID();
        INSERT dbo.AuditOperations(OperationId, UserId, OperationType, CorrelationNote)
        VALUES(@ReplacementOperation, @UserId, N'FEE_ASSIGNMENT_AMOUNT_CHANGE', N'Unbilled rate replaced in place');
        DECLARE @ReplacementOld nvarchar(max) = (SELECT @OldAmount Amount, @ExistingEffectiveFrom EffectiveFrom FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
        DECLARE @ReplacementNew nvarchar(max) = (SELECT @NewAmount Amount, @NormalizedEffectiveFrom EffectiveFrom, @Reason Reason FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
        EXEC dbo.WriteAuditLog @OperationId = @ReplacementOperation, @UserId = @UserId,
             @TableName = N'StudentFeeAssignments', @RecordId = @StudentFeeAssignmentId,
             @Action = N'UPDATE', @OldValues = @ReplacementOld, @NewValues = @ReplacementNew;
        DELETE dbo.AuditOperations WHERE OperationId = @ReplacementOperation
          AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId = @ReplacementOperation);
        COMMIT TRANSACTION;
        SELECT StudentFeeAssignmentId, EnrollmentId, AdmissionId, FeeTypeId, Amount, DiscountAmount,
               Frequency, EffectiveFrom, EffectiveTo
        FROM dbo.StudentFeeAssignments WHERE StudentFeeAssignmentId = @StudentFeeAssignmentId;
        RETURN;
    END;
    IF @ExistingEffectiveFrom IS NOT NULL
       AND @NormalizedEffectiveFrom <= @ExistingEffectiveFrom
        THROW 53145, 'Effective-from month must be after this version''s own starting month.', 1;
    DECLARE @LastBilledMonth AS DATE = (SELECT MAX(BillingMo
nth)
                                        FROM   dbo.BillingCharges
                                        WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId);
    IF @LastBilledMonth IS NOT NULL
       AND @NormalizedEffectiveFrom <= @LastBilledMonth
        THROW 53148, 'Effective-from month cannot be on or before the last month already billed for this fee.', 1;
    IF @NewAmount < @DiscountAmount
        BEGIN
            DECLARE @DiscountMessage AS NVARCHAR (2048) = N'The new fee amount (' + CONVERT (NVARCHAR (30), @NewAmount) + N') cannot be lower than the discount already applied to this fee (' + CONVERT (NVARCHAR (30), @DiscountAmount) + N'). Reduce the discount first, or enter an amount of at least ' + CONVERT (NVARCHAR (30), @DiscountAmount) + N'.';
            THROW 53149, @DiscountMessage, 1;
        END
    BEGIN TRANSACTION;
    UPDATE dbo.StudentFeeAssignments
    SET    EffectiveTo = @NormalizedOldEffectiveTo,
           UpdatedAt   = SYSDATETIME()
    WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId
           AND EffectiveTo IS NULL;
    IF @@ROWCOUNT = 0
        BEGIN
            ROLLBACK;
            THROW 53146, 'The fee assignment could not be updated (it may have just been changed by another operation).', 1;
        END
    INSERT  dbo.StudentFeeAssignments (EnrollmentId, AdmissionId, FeeTypeId, Amount, DiscountAmount, Frequency, Remarks, EffectiveFrom, EffectiveTo)
    VALUES                           (@EnrollmentId, @AdmissionId, @FeeTypeId, @NewAmount, @DiscountAmount, @Frequency, @Remarks, @NormalizedEffectiveFrom, NULL);
    DECLARE @NewStudentFeeAssignmentId AS INT = CONVERT (INT, SCOPE_IDENTITY());
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'FEE_ASSIGNMENT_AMOUNT_CHANGE', CONVERT (NVARCHAR (200), @StudentFeeAssignmentId) +
 N' -> ' + CONVERT (NVARCHAR (200), @NewStudentFeeAssignmentId));
    DECLARE @OldValues AS NVARCHAR (MAX) = (SELECT @StudentFeeAssignmentId AS StudentFeeAssignmentId,
                                                   @OldAmount AS Amount,
                                                   @ExistingEffectiveFrom AS EffectiveFrom
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    DECLARE @NewValues AS NVARCHAR (MAX) = (SELECT @NewStudentFeeAssignmentId AS StudentFeeAssignmentId,
                                                   @NewAmount AS Amount,
                                                   @NormalizedEffectiveFrom AS EffectiveFrom,
                                                   @Reason AS Reason,
                                                   @EnrollmentId AS EnrollmentId,
                                                   @AdmissionId AS AdmissionId,
                                                   @FeeTypeId AS FeeTypeId,
                                                   @StudentFeeAssignmentId AS PreviousVersionId
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'StudentFeeAssignments', @RecordId = @NewStudentFeeAssignmentId, @Action = N'UPDATE', @OldValues = @OldValues, @NewValues = @NewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT StudentFeeAssignmentId,
           EnrollmentId,
           AdmissionId,
           FeeTypeId,
           Amount,
           DiscountAmount,
           Frequency,
           EffectiveFrom,
           EffectiveTo
    FROM   dbo.StudentFeeAssignments
    WHERE  StudentFeeAssignmentId = @NewStudentFeeAssignmentId;
END

Two students ... same receipt number").
   Cause: the post-check still required one receipt per child, but FIX 70/70b
   deliberately gives the whole family ONE shared receipt number.
   Only the 59227 check changes; everything else is identical to fmsc v4.dacpac.
   Safe to run once on the live database (ALTER, no data change). */
CREATE   PROCEDURE dbo.ProcessFamilyFeeTransaction
    @TransactionType NVARCHAR(20),
    @TransactionDate DATE,
    @PaymentMethod   NVARCHAR(30),
    @ReferenceNumber NVARCHAR(100),
    @Remarks         NVARCHAR(500),
    @Allocations     dbo.FamilyFeeAllocationType READONLY,
    @UserId          INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    EXEC dbo.RequirePermission
        @UserId,
        N'Fees.Collect';

    SET @TransactionType =
        LTRIM(RTRIM(@TransactionType));

    IF @TransactionType NOT IN
    (
        N'Collection',
        N'Correction',
        N'Refund',
        N'Reversal'
    )
        THROW 59217, 'Invalid fee transaction type.', 1;


    /* ========================================================================
       VALIDATE THE WHOLE FAMILY BEFORE ANYTHING IS WRITTEN

       Every check below covers the entire batch at once. Validating up front is
       not what makes the operation atomic - the transaction is - but it means a
       family with a bad line is refused with a sentence that names the problem
       instead of failing after some children have already been processed.
       ======================================================================== */

    IF NOT EXISTS
    (
        SELECT 1
        FROM @Allocations
    )
        THROW 59218, 'No fee allocations were supplied, so there is nothing to collect.', 1;


    /* A row w
ith no student, no enrollment or no charge cannot be attributed to
       anybody. This catches a malformed batch rather than a data problem. */
    IF EXISTS
    (
        SELECT 1
        FROM @Allocations
        WHERE AdmissionId <= 0
           OR EnrollmentId <= 0
           OR BillingChargeId <= 0
    )
        THROW 59219, 'A family collection line is missing its student, enrollment or charge. Nothing has been posted.', 1;


    /* Every student. */
    IF EXISTS
    (
        SELECT 1
        FROM @Allocations A
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM dbo.Students S
            WHERE S.AdmissionId = A.AdmissionId
        )
    )
        THROW 59220, 'One of the students in this family collection no longer exists. Nothing has been posted.', 1;


    /* Every enrollment, and that it belongs to the student it is filed under.
       A mismatch here would post a charge against the wrong child. */
    IF EXISTS
    (
        SELECT 1
        FROM @Allocations A
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM dbo.Enrollments E
            WHERE E.EnrollmentId = A.EnrollmentId
              AND E.AdmissionId = A.AdmissionId
        )
    )
        THROW 59221, 'One of the enrollments in this family collection does not belong to its student. Nothing has been posted.', 1;


    /* Every charge, and that it belongs to that student's enrollment. */
    IF EXISTS
    (
        SELECT 1
        FROM @Allocations A
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM dbo.BillingCharges BC
            WHERE BC.BillingChargeId = A.BillingChargeId
              AND BC.AdmissionId = A.AdmissionId
              AND BC.EnrollmentId = A.EnrollmentId
        )
    )
        THROW 59222, 'One of the fee charges in this family collection does not belong to its student. Nothing has been posted.', 1;


    /* ==============================================================
==========
       GROUP THE BATCH BY STUDENT, IN A FIXED ORDER

       ROW_NUMBER rather than IDENTITY so the order is the ORDER BY and not an
       implementation detail: the sequence decides the order in which the engine
       takes its locks, which is what keeps two concurrent family collections
       from deadlocking on each other.
       ======================================================================== */

    DECLARE @Groups TABLE
    (
        Seq          INT NOT NULL PRIMARY KEY,
        AdmissionId  INT NOT NULL,
        EnrollmentId INT NOT NULL
    );

    INSERT INTO @Groups (Seq, AdmissionId, EnrollmentId)
    SELECT
        ROW_NUMBER() OVER (ORDER BY AdmissionId, EnrollmentId),
        AdmissionId,
        EnrollmentId
    FROM
    (
        SELECT DISTINCT
            AdmissionId,
            EnrollmentId
        FROM @Allocations
    ) D;


    /* dbo.ProcessFeeTransaction requires @Amount to equal the sum of that call's
       POSITIVE allocations and rejects a non-positive amount (54011). A student
       whose lines are discounts only would fail inside the loop, after the
       transaction had opened; refusing it here says which situation it is. */
    IF EXISTS
    (
        SELECT 1
        FROM @Groups G
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM @Allocations A
            WHERE A.AdmissionId = G.AdmissionId
              AND A.EnrollmentId = G.EnrollmentId
              AND A.Amount > 0
        )
    )
        THROW 59223, 'One of the students in this family collection has nothing payable - only discounts. Nothing has been posted.', 1;


    /* ========================================================================
       RUN THE FAMILY
       ======================================================================== */

    DECLARE @Receipts TABLE
    (
        AdmissionId   INT           NOT NULL,
        EnrollmentId  INT           NOT NULL,
        FeePaymentId  INT   
        NULL,
        ReceiptNumber NVARCHAR(40)  NULL,
        Amount        DECIMAL(12,2) NULL,
        Balance       DECIMAL(12,2) NULL
    );

    /* dbo.ProcessFeeTransaction returns exactly these five columns. The names
       and types are declared to match it, because INSERT ... EXEC matches a
       result set to its target by position and data type. */
    DECLARE @OneResult TABLE
    (
        FeePaymentId    INT,
        ReceiptNumber   NVARCHAR(40),
        TransactionType NVARCHAR(20),
        Amount          DECIMAL(12,2),
        Balance         DECIMAL(12,2)
    );

    DECLARE @One dbo.FeePaymentAllocationType;

    DECLARE @Seq INT = 1;
    DECLARE @GroupCount INT =
        (SELECT COUNT(*) FROM @Groups);

    DECLARE @AdmissionId INT;
    DECLARE @EnrollmentId INT;
    DECLARE @StudentAmount DECIMAL(12,2);
    DECLARE @Processed INT = 0;

    /* The engine's own nullable inputs. Assigned to variables rather than
       written as NULL in the EXEC, because EXEC parameter values must be
       constants or variables. */
    DECLARE @NoPaymentId INT = NULL;
    DECLARE @NoChargeId BIGINT = NULL;


    /* ONE transaction for the whole family. See the header: this is the only
       boundary that writes, and XACT_ABORT ON in both procedures means any
       failure inside the engine rolls all of it back. */
    BEGIN TRANSACTION;

    /* FIX 70b: ONE receipt number for the whole collection, taken here so a
       family collection does not consume one number per child and leave gaps in
       the series. Inside the transaction, so a rollback gives the number back. */
    DECLARE @FamilyReceiptNumber NVARCHAR(40);

    EXEC dbo.GetNextFeeReceiptNumber
        @ReceiptDate = @TransactionDate,
        @ReceiptNumber = @FamilyReceiptNumber OUTPUT;

    WHILE @Seq <= @GroupCount
    BEGIN
        SELECT
            @AdmissionId = AdmissionId,
            @EnrollmentId = EnrollmentId
        FROM @Groups
        WHERE Seq = @S
eq;

        /* One child's allocations, in the shape the engine takes. */
        DELETE FROM @One;

        INSERT INTO @One (BillingChargeId, Amount)
        SELECT
            BillingChargeId,
            Amount
        FROM @Allocations
        WHERE AdmissionId = @AdmissionId
          AND EnrollmentId = @EnrollmentId;

        SELECT
            @StudentAmount = SUM(Amount)
        FROM @One
        WHERE Amount > 0;

        DELETE FROM @OneResult;

        INSERT INTO @OneResult
        (
            FeePaymentId,
            ReceiptNumber,
            TransactionType,
            Amount,
            Balance
        )
        EXEC dbo.ProcessFeeTransaction
            @AdmissionId = @AdmissionId,
            @EnrollmentId = @EnrollmentId,
            @TransactionType = @TransactionType,
            @Amount = @StudentAmount,
            @TransactionDate = @TransactionDate,
            @PaymentMethod = @PaymentMethod,
            @ReferenceNumber = @ReferenceNumber,
            @Remarks = @Remarks,
            @GroupReceiptNumber = @FamilyReceiptNumber,
            @FeePaymentId = @NoPaymentId,
            @BillingChargeId = @NoChargeId,
            @Allocations = @One,
            @UserId = @UserId;

        INSERT INTO @Receipts
        (
            AdmissionId,
            EnrollmentId,
            FeePaymentId,
            ReceiptNumber,
            Amount,
            Balance
        )
        SELECT
            @AdmissionId,
            @EnrollmentId,
            FeePaymentId,
            ReceiptNumber,
            Amount,
            Balance
        FROM @OneResult;

        SET @Processed = @Processed + 1;
        SET @Seq = @Seq + 1;
    END;


    /* ========================================================================
       PROVE THE FAMILY IS WHOLE BEFORE COMMITTING

       These four run inside the transaction, so a collection that did not
       produce one payment and one receipt per child rolls itse
lf back instead of
       committing something half-formed. They are the difference between "the
       loop finished" and "the family was collected".
       ======================================================================== */

    IF @Processed <> @GroupCount
        THROW 59224, 'Not every student in the family collection produced a payment, so the whole collection has been rolled back.', 1;

    IF (SELECT COUNT(*) FROM @Receipts) <> @GroupCount
        THROW 59225, 'Not every student in the family collection produced a payment row, so the whole collection has been rolled back.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM @Receipts
        WHERE ReceiptNumber IS NULL
           OR LTRIM(RTRIM(ReceiptNumber)) = ''
    )
        THROW 59226, 'A student in the family collection received no receipt number, so the whole collection has been rolled back.', 1;

    /* FIX 70b/70: a family Collection is issued ONE receipt number that every
       child's payment shares (ProcessFeeTransaction stamps @GroupReceiptNumber
       and sets IsGroupPayment = 1; UQ_FeePayments_Receipt_Single is filtered to
       IsGroupPayment = 0 for exactly this reason; GetFeeReceiptGroup prints the
       whole family from that one number).

       This check used to demand the opposite - that no two children share a
       number - so every family of two or more children was rolled back with
       59227. What it must prove now is that every child's payment carries the
       family's number and nothing else. */
    IF @TransactionType = N'Collection'
    BEGIN
        IF EXISTS
        (
            SELECT 1
            FROM @Receipts
            WHERE ReceiptNumber <> @FamilyReceiptNumber
        )
            THROW 59227, 'A student in the family collection was not given the family receipt number, so the whole collection has been rolled back.', 1;
    END
    ELSE
    BEGIN
        /* Any other type keeps its own number per payment (ProcessFeeTransaction

           allocates them itself), so there the numbers must all differ. */
        IF EXISTS
        (
            SELECT ReceiptNumber
            FROM @Receipts
            GROUP BY ReceiptNumber
            HAVING COUNT(*) > 1
        )
            THROW 59227, 'Two students in the family collection were given the same receipt number, so the whole collection has been rolled back.', 1;
    END;


    IF EXISTS
    (
        SELECT 1
        FROM @Receipts
        WHERE FeePaymentId IS NULL
    )
        THROW 59228, 'A student in the family collection has no payment record, so the whole collection has been rolled back.', 1;


    /* The one commit that writes. Everything above is provisional until here. */
    COMMIT TRANSACTION;


    /* ========================================================================
       RETURN RESULT - one row per child, in a fixed order, so the caller can
       report each child's own receipt number.
       ======================================================================== */

    SELECT
        AdmissionId,
        EnrollmentId,
        FeePaymentId,
        ReceiptNumber,
        Amount,
        Balance
    FROM @Receipts
    ORDER BY AdmissionId;
END;

Set Billing Start" on the Student Lifecycle screen for any individual correction needed from here on.', 1;
        END
    IF NOT EXISTS (SELECT 1
                   FROM   dbo.SchoolProfile
                   WHERE  SchoolProfileId = 1)
        BEGIN
            ROLLBACK;
            THROW 58104, 'School profile has not been set up yet. Complete School Information first.', 1;
        END
    DECLARE @Candidates TABLE (
        EnrollmentId INT PRIMARY KEY);
    INSERT INTO @Candidates (EnrollmentId)
    SELECT E.EnrollmentId
    FROM   dbo.Enrollments AS E
    WHERE  E.Status = N'Active'
           AND E.BillingStartDate IS NULL
           AND NOT EXISTS (SELECT 1
                           FROM   dbo.StudentFeeAssignments AS SFA
                                  INNER JOIN
                                  dbo.BillingCharges AS BC
                                  ON BC.StudentFeeAssignmentId = SFA.StudentFeeAssignmentId
                           WHERE  SFA.EnrollmentId = E.EnrollmentId);
    DECLARE @EnrollmentId AS INT, @ProcessedCount AS INT = 0;
    DECLARE cleanup_cursor CURSOR LOCAL FAST_FORWARD
        FOR SELECT EnrollmentId
            FROM   @Candidates;
    OPEN cleanup_cursor;
    FETCH NEXT FROM cleanup_cursor INTO @EnrollmentId;
    WHILE @@FETCH_STATUS = 0

        BEGIN
            EXECUTE dbo.SetEnrollmentBillingStartDate @UserId = @UserId, @EnrollmentId = @EnrollmentId, @BillingStartDate = @GoLiveDate, @Reason = @Reason;
            SET @ProcessedCount += 1;
            FETCH NEXT FROM cleanup_cursor INTO @EnrollmentId;
        END
    CLOSE cleanup_cursor;
    DEALLOCATE cleanup_cursor;
    UPDATE dbo.SchoolProfile
    SET    MigrationBillingCleanupCompletedAt       = SYSDATETIME(),
           MigrationBillingCleanupCompletedByUserId = @UserId,
           MigrationBillingCleanupEnrollmentCount   = @ProcessedCount,
           UpdatedAt                                = SYSDATETIME(),
           UpdatedByUserId                          = @UserId
    WHERE  SchoolProfileId = 1;
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    DECLARE @NewValues AS NVARCHAR (MAX) = (SELECT @GoLiveDate AS GoLiveDate,
                                                   @Reason AS Reason,
                                                   @ProcessedCount AS EnrollmentsProcessed
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    COMMIT TRANSACTION;
    SELECT @ProcessedCount AS EnrollmentsProcessed,
           @GoLiveDate AS GoLiveDate;
END

-- ReverseBillingCharge
CREATE   PROCEDURE dbo.ReverseBillingCharge
@UserId INT, @BillingChargeId BIGINT, @Reason NVARCHAR (500)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Fees.Collect';
    IF NULLIF (LTRIM(RTRIM(@Reason)), N'') IS NULL
        THROW 53201, 'A reason is required to reverse a charge.', 1;
    DECLARE @Status AS NVARCHAR (40);
    DECLARE @FeeTypeName AS NVARCHAR (200);
    DECLARE @NetAmount AS DECIMAL (18, 2);
    DECLARE @BillingMonth AS DATE;
    DECLARE @AdmissionId AS INT;
    SELECT @Status = BC.Status,
           @FeeTypeName = FT.FeeTypeName,
           @NetAmount = BC.NetAmount,
           @BillingMonth = BC.BillingMonth,
           @AdmissionId = BC.AdmissionId
    FROM   dbo.BillingCharges AS BC
           INNER JOIN
           dbo.FeeTypes AS FT
           ON FT.FeeTypeId = BC.FeeTypeId
    WHERE  BC.BillingChargeId = @BillingChargeId;
    IF @Status IS NULL
        THROW 53200, 'The selected charge does not exist. Reload the list and try again.', 1;
    IF @Status = N'Cancelled'
        THROW 53202, 'This charge has already been reversed.', 1;
    IF @Status <> N'Open'
       OR (SELECT ISNULL(SUM(A.Amount), 0)
           FROM   dbo.FeePaymentAllocations AS A
                  INNER JOIN
                  dbo.FeePayments AS FP
                  ON FP.FeePaymentId = A.FeePaymentId

                     AND FP.Status = N'Completed'
           WHERE  A.BillingChargeId = @BillingChargeId) > 0
        THROW 53203, 'This fee has already been collected. It cannot be reversed as an uncollected charge - use Correction, Refund or Reversal in Student Fees.', 1;
    DECLARE @OldValues AS NVARCHAR (MAX) = (SELECT BC.BillingChargeId AS BillingChargeId,
                                                   BC.StudentFeeAssignmentId AS StudentFeeAssignmentId,
                                                   BC.EnrollmentId AS EnrollmentId,
                                                   BC.AdmissionId AS AdmissionId,
                                                   BC.FeeTypeId AS FeeTypeId,
                                                   BC.BillingMonth AS BillingMonth,
                                                   BC.ChargeDate AS ChargeDate,
                                                   BC.DueDate AS DueDate,
                                                   BC.GrossAmount AS GrossAmount,
                                                   BC.DiscountAmount AS DiscountAmount,
                                                   BC.NetAmount AS NetAmount,
                                                   BC.Status AS Status,
                                                   BC.Remarks AS Remarks
                                            FROM   dbo.BillingCharges AS BC
                                            WHERE  BC.BillingChargeId = @BillingChargeId
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    DECLARE @CleanedReason AS NVARCHAR (500) = LTRIM(RTRIM(@Reason));
    BEGIN TRY
        BEGIN TRANSACTION;
        UPDATE dbo.BillingCharges
        SET    Status  = N'Cancelled',
               Remarks = LEFT(ISNULL(BC.Remarks + N' | ', N'') + N'Charge reversed: ' + @CleanedReason, 1000)
        FROM   dbo.BillingCharges AS BC

     WHERE  BC.BillingChargeId = @BillingChargeId
               AND BC.Status = N'Open';
        IF @@ROWCOUNT = 0
            THROW 53204, 'The charge could not be reversed because it changed while this screen was open. Reload the list and try again.', 1;
        DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
        INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
        VALUES                     (@OperationId, @UserId, N'FEE_CHARGE_REVERSAL', CONVERT (NVARCHAR (50), @BillingChargeId));
        DECLARE @NewValues AS NVARCHAR (MAX) = (SELECT N'Cancelled' AS Status,
                                                       @CleanedReason AS Reason,
                                                       N'Single uncollected charge reversed; no payment had been allocated to it.' AS Note
                                                FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
        EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'BillingCharges', @RecordId = @BillingChargeId, @Action = N'REVERSAL', @OldValues = @OldValues, @NewValues = @NewValues;
        DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK;
        THROW;
    END CATCH
    SELECT @BillingChargeId AS BillingChargeId,
           @AdmissionId AS AdmissionId,
           @FeeTypeName AS FeeTypeName,
           @BillingMonth AS BillingMonth,
           @NetAmount AS AmountReversed,
           @CleanedReason AS Reason,
           N'Cancelled' AS Status;
END

-- SaveStudentFeeDiscount
CREATE   PROCEDURE dbo.SaveStudentFeeDiscount
@UserId INT, 
@StudentFeeAssignmentId INT, @DiscountAmount DECIMAL (12, 2)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    EXECUTE dbo.RequirePermission @UserId, N'Fees.Adjust';
    IF @DiscountAmount IS NULL
        SET @DiscountAmount = 0;
    IF @DiscountAmount < 0
        THROW 53101, 'Discount cannot be negative.', 1;
    DECLARE @Amount AS DECIMAL (12, 2), @EnrollmentId AS INT, @AdmissionId AS INT, @OldDiscountAmount AS DECIMAL (12, 2);
    SELECT @Amount = Amount,
           @EnrollmentId = EnrollmentId,
           @AdmissionId = AdmissionId,
           @OldDiscountAmount = DiscountAmount
    FROM   dbo.StudentFeeAssignments
    WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId
           AND CancelledAt IS NULL;
    IF @Amount IS NULL
        THROW 53102, 'The selected student fee assignment does not exist.', 1;
    IF @DiscountAmount > @Amount
        THROW 53103, 'Discount cannot be greater than the fee amount.', 1;
    BEGIN TRANSACTION;
    UPDATE dbo.StudentFeeAssignments
    SET    DiscountAmount = @DiscountAmount,
           UpdatedAt      = SYSDATETIME()
    WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId
           AND CancelledAt IS NULL;
    IF @@ROWCOUNT = 0
        BEGIN
            ROLLBACK;
            THROW 53104, 'The student fee assignment could not be updated.', 1;
        END
    UPDATE BC
    SET    DiscountAmount = CASE WHEN @DiscountAmount > BC.GrossAmount THEN BC.GrossAmount ELSE @DiscountAmount END
    FROM   dbo.BillingCharges AS BC
    WHERE  BC.StudentFeeAssignmentId = @StudentFeeAssignmentId
           AND BC.Status <> N'Cancelled'
           AND NOT EXISTS (SELECT 1
                           FROM   dbo.FeePaymentAllocations AS FPA
                                  INNER JOIN
                                  dbo.FeePayments AS FP
                                  ON FP.FeePaymentId = FPA.FeePaymentId

  WHERE  FPA.BillingChargeId = BC.BillingChargeId
                                  AND FP.Status = N'Completed');
    DECLARE @OperationId AS UNIQUEIDENTIFIER = NEWID();
    INSERT  dbo.AuditOperations (OperationId, UserId, OperationType, CorrelationNote)
    VALUES                     (@OperationId, @UserId, N'FEE_DISCOUNT_CHANGE', CONVERT (NVARCHAR (200), @StudentFeeAssignmentId));
    DECLARE @OldValues AS NVARCHAR (MAX) = (SELECT @StudentFeeAssignmentId AS StudentFeeAssignmentId,
                                                   @OldDiscountAmount AS DiscountAmount
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    DECLARE @NewValues AS NVARCHAR (MAX) = (SELECT @StudentFeeAssignmentId AS StudentFeeAssignmentId,
                                                   @DiscountAmount AS DiscountAmount,
                                                   @EnrollmentId AS EnrollmentId,
                                                   @AdmissionId AS AdmissionId
                                            FOR    JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);
    EXECUTE dbo.WriteAuditLog @OperationId = @OperationId, @UserId = @UserId, @TableName = N'StudentFeeAssignments', @RecordId = @StudentFeeAssignmentId, @Action = N'UPDATE', @OldValues = @OldValues, @NewValues = @NewValues;
    DELETE dbo.AuditOperations WHERE OperationId=@OperationId AND NOT EXISTS(SELECT 1 FROM dbo.AuditLogs WHERE OperationId=@OperationId);
COMMIT TRANSACTION;
    SELECT StudentFeeAssignmentId,
           EnrollmentId,
           AdmissionId,
           Amount AS StandardAmount,
           DiscountAmount,
           Amount - DiscountAmount AS NetAmount
    FROM   dbo.StudentFeeAssignments
    WHERE  StudentFeeAssignmentId = @StudentFeeAssignmentId;
END
